window.EXERCISES=[{"id":"3BC06AD3","name":"21s Bicep Curl","primary":"biceps","secondary":[],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/00311201-Barbell-Curl_Upper-Arms_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00311201-Barbell-Curl_Upper-Arms.mp4","howto":["Grab a straight or curved bar evenly and stand tall. Bring your shoulders back, squeeze your glutes, and take a breath.","Curl the weight halfway (to the point where your wrists align with your elbows) for seven repetitions.","Immediately start curling the bar from the halfway point to the top (where your wrists are a couple of inches higher than your elbows) for another seven repetitions.","Finish by doing seven complete repetitions from full arm extension to the top position, breathing steadily as you do."]},{"id":"B4F2FF72","name":"Ab Scissors","primary":"abdominals","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/62141201-Lying-Scissors-Cross-(male)_Hips_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/62141201-Lying-Scissors-Cross-(male)_Hips_.mp4","howto":["Sit on an exercise mat, lean back, and place your hands on the floor and to your sides for balance.","Engage your abs and raise your feet several inches off the floor while keeping your knees extended.","Take a breath and cross your legs by bringing the right one over the left. Immediately uncross them and move the left leg over the right.","Keep alternating until you get tired, breathing steadily as you do reps."]},{"id":"99D5F10E","name":"Ab Wheel","primary":"abdominals","secondary":[],"equipment":"other","type":"reps_only","thumb":"assets/thumbs/08571201-Wheel-Rollout_Waist_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/08571201-Wheel-Rollout_Waist.mp4","howto":["Grab an ab wheel and get down on your knees.","Lean forward and place the ab wheel on the floor while holding it firmly with both hands.","Engage your abs and take a breath.","Roll the ab wheel forward as you extend your body.","Move forward as much as your ab strength allows and roll the wheel back to the starting position. Exhale."]},{"id":"5E0DDACE","name":"Aerobics","primary":"cardio","secondary":[],"equipment":"none","type":"duration","thumb":"assets/thumbs/109781201-Step-Side-Jump-over-StepBox-(male)_Plyometrics_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/109781201-Step-Side-Jump-over-StepBox-(male)_Plyometrics_.mp4","howto":[]},{"id":"43573BB8","name":"Air Bike","primary":"cardio","secondary":[],"equipment":"machine","type":"duration","thumb":"assets/thumbs/38931201-Assault-Bike-Run_Cardio_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/38931201-Assault-Bike-Run_Cardio_.mp4","howto":[]},{"id":"A69FF221","name":"Arnold Press (Dumbbell)","primary":"shoulders","secondary":["triceps"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/02871201-Dumbbell-Arnold-Press-II_Shoulders_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/02871201-Dumbbell-Arnold-Press-II_Shoulders.mp4","howto":["Grab a pair of light dumbbells and sit on a gym bench with an upright back support.","Lift the dumbbells and rest them on your thighs.","Bring your shoulders back, engage your abs, and take a breath.","Thrust the dumbbells and bring them to your sides.","Take a breath and press the dumbbells to an overhead position as you breathe out.","Lower the dumbbells slowly as you rotate your wrists in, breathing in on the way down. You should end up with the dumbbells in front of your chin and palms facing your body.","Press again, rotating your wrists to complete the repetition with your palms facing forward."]},{"id":"D4A2FE7E","name":"Around The World","primary":"chest","secondary":["upper_back","shoulders","lats"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/02881201-Dumbbell-Around-Pullover_Chest_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/02881201-Dumbbell-Around-Pullover_Chest.mp4","howto":["Lie on a flat bench with a dumbbell in each hand.","Position the dumbbells over your upper thighs with your arms straight and palms facing down.","Bring your shoulders back, engage your abs, and breathe in.","Slowly move the dumbbells from your upper thighs to behind your head in an arc motion, keeping your arms straight. Breathe out.","Immediately move the weights from behind your head to the starting position in an arc as you breathe in. While doing so, twist your wrists to have your palms facing down at the starting position."]},{"id":"5BFF35BA","name":"Assisted Pistol Squats","primary":"quadriceps","secondary":["hamstrings","glutes"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/17621201-Single-Leg-Squat-with-Support-(pistol)_Thighs_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/17621201-Single-Leg-Squat-with-Support-(pistol)_Thighs_.mp4","howto":["Stand next to a squat rack and grab it with one hand for balance.","Lift one foot off the floor and raise the leg a few inches forward. Keep your opposite foot firmly planted on the floor.","Engage your abs, bring your shoulders back, and take a breath.","Squat by bending your knee and moving the opposite leg forward, keeping the foot off the floor.","Descend as much as possible and push through the heel to lift yourself as you exhale.","Once finished training one leg, support yourself on the opposite foot and perform the same number of reps."]},{"id":"4F5866F8","name":"Back Extension (Hyperextension)","primary":"lower_back","secondary":["hamstrings","glutes"],"equipment":"machine","type":"reps_only","thumb":"assets/thumbs/18601201-Hyperextension-(VERSION-2)_Hips_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/18601201-Hyperextension-(VERSION-2)_Hips.mp4","howto":["Set yourself up on a back extension machine. Have your hips and thighs against the pad and your ankles locked on the foot brace.","Engage your abs, cross your arms in front of your chest, and take a breath.","Lower yourself by bending at the hips and move down until you feel a stretch in your hamstrings and glutes.","Engage your buttocks and lower back to raise your torso to the top position, pausing for a moment and exhaling."]},{"id":"A05C064D","name":"Back Extension (Machine)","primary":"lower_back","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/05731201-Lever-Back-Extension_Waist_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/05731201-Lever-Back-Extension_Waist.mp4","howto":["Sit on a back extension machine with your buttocks against a pad.","Place the foot pad just over your feet.","The top pad should be against your upper back.","Adjust the load on the machine and cross your arms in front of your chest.","Take a breath, engage your abs, and push the top pad backward by engaging your lower back muscles. Breathe out.","Lean forward to the starting position as you breathe in."]},{"id":"091737FA","name":"Back Extension (Weighted Hyperextension)","primary":"lower_back","secondary":["hamstrings","glutes"],"equipment":"machine","type":"bodyweight_reps","thumb":"assets/thumbs/50351201-Weighted-Hyperextension_Hips_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/50351201-Weighted-Hyperextension_Hips_.mp4","howto":["Set yourself up inside a back extension bench. Have your heels secured against a pad and your hips against another pad.","Bend forward and grab a weight plate off the floor or have a training partner hand it to you.","Extend your body and take a breath.","Bend your body at the hips while keeping your shoulders back and spine neutral. Move down as much as your muscle flexibility allows.","Extend your body by engaging your posterior chain and exhale near the top."]},{"id":"F51D9080","name":"Ball Slams","primary":"full_body","secondary":[],"equipment":"other","type":"weight_reps","thumb":"assets/thumbs/75351201-Medicine-Ball-Slam-(VERSION-2)-(male)_Waist_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/75351201-Medicine-Ball-Slam-(VERSION-2)-(male)_Waist_.mp4","howto":["Stand tall with your feet in a comfortable stance and your toes pointing slightly out.","Hold a medicine ball in both hands, keeping it at stomach level.","Engage your midsection, bend your knees slightly, and thrust the medicine ball overhead. Your arms should be straight, and the ball should be directly overhead for balance.","Inhale and use your upper body muscles to accelerate the ball down and slam it as hard as you can just in front of your body. Breathe out.","Bend your knees enough to pick up the ball while keeping your spine neutral.","Breathe in and repeat the sequence."]},{"id":"E8D86EE8","name":"Band Pullaparts","primary":"shoulders","secondary":["upper_back"],"equipment":"resistance_band","type":"reps_only","thumb":"assets/thumbs/45681201-Resistance-Band-Pull-Apart_Shoulders_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/45681201-Resistance-Band-Pull-Apart_Shoulders_.mp4","howto":["Grab a looped or open-ended resistance band with handles on both ends. The band should offer moderate resistance.","Extend your arms in front of your body and have your palms neutral (facing one another).","Take a breath and pull the band apart, bringing your arms to the sides while keeping them straight. Exhale.","Bring your arms together as you breathe in."]},{"id":"084A67CA","name":"Battle Ropes","primary":"cardio","secondary":[],"equipment":"machine","type":"duration","thumb":"assets/thumbs/01281201-Battling-Ropes_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/01281201-Battling-Ropes.mp4","howto":["Grab the pair of battle ropes.","Bend your knees and lean forward slightly while keeping your spine neutral.","Take a breath and move one arm up to shoulder level while bringing the opposite one down to your knees.","Immediately move both arms in the opposite direction, changing their position.","Alternate your arms at a steady tempo, breathing regularly as you do.","Go for as long as possible until you feel a deep burn in your upper back and shoulders."]},{"id":"B3B1D947","name":"Bear Crawl","primary":"full_body","secondary":[],"equipment":"none","type":"distance_duration","thumb":"assets/thumbs/65991201-Bear-Crawl-(low-hip)-(male)_Plyometrics_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/65991201-Bear-Crawl-(low-hip)-(male)_Plyometrics_.mp4","howto":["Get down on your knees and hands. Your hands should be shoulder-width apart.","Engage your abs and lift your knees off the ground.","Breathe in and start moving forward on your hands and feet while keeping your knees in the air.","Bring your right arm and left knee forward, then your left arm and right knee forward.","Continue alternating and breathe steadily as you move forward."]},{"id":"2DBCA395","name":"Behind the Back Curl (Cable)","primary":"biceps","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/48381201-Cable-Unilateral-Bicep-Curl_Upper-Arms_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/48381201-Cable-Unilateral-Bicep-Curl_Upper-Arms_.mp4","howto":["Set the pulleys at around mid-thigh height, attach handles, and select the load.","Grab the handles one by one and stand so the pulleys are behind you.","Take a couple of steps forward to lift the weights off their stacks and allow the weight to pull your elbows behind your torso.","With your chest out, lean your torso slightly forward and stagger your stance (one foot forward, the other one back).","Breathe in, engage your abs, and curl until your wrists are at elbow level. Squeeze your biceps and exhale.","Slowly extend your arms, allowing the handles to travel behind your body, and breathe in.","Repeat."]},{"id":"DDB29047","name":"Behind the Back Wrist Curl (Barbell)","primary":"forearms","secondary":[],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/63651201-EZ-Barbell-Standing-Back-Wrist-Curl_Forearms_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/63651201-EZ-Barbell-Standing-Back-Wrist-Curl_Forearms_.mp4","howto":["Place a loaded barbell or EZ bar on the floor and stand in front of it.","With your arms to your sides and palms facing back, squat, and grab the bar evenly. Keep your back straight.","Push through your heels and squat up, lifting the bar behind your body.","Take a breath and flex your wrists to curl the barbell without moving your elbows or arms. Breathe out at the top.","Extend your wrists as you breathe in."]},{"id":"3D1CDC75","name":"Belt Squat (Machine)","primary":"quadriceps","secondary":["glutes","hamstrings"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/29501201-Lever-Belt-Squat_Thighs_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/29501201-Lever-Belt-Squat_Thighs_.mp4","howto":["Load the machine appropriately and put on the weight belt.","Step on the platform and hook the belt’s chain to the machine’s lever via a carabiner.","Stand tall and grab the handles or horizontal bar in front.","Position your feet at a comfortable width for squats with your toes pointing slightly out.","Bring your chest out, engage your abs, and unrack the weight. You can hold onto the bar or handles in front of you for balance.","Breathe in and descend until your thighs are roughly parallel to the bar.","Pause briefly and push through your heels to extend your knees, exhaling at the top.","Breathe in and repeat."]},{"id":"CD6DC8E5","name":"Bench Dip","primary":"triceps","secondary":["shoulders","chest"],"equipment":"other","type":"reps_only","thumb":"assets/thumbs/13991201-Bench-dip-on-floor_Upper-Arms_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/13991201-Bench-dip-on-floor_Upper-Arms.mp4","howto":["Face away from a sturdy gym bench, plyo box, or chair.","Lean back and place your hands flat on the object's edge.","Straighten your legs and support your lower body on your heels. Your torso should be upright.","Engage your abs, take a breath, and descend by bending your elbows.","Move down until your elbows form a 90-degree angle and pause for a moment.","Extend your arms and exhale near the top."]},{"id":"79D0BB3A","name":"Bench Press (Barbell)","primary":"chest","secondary":["triceps","shoulders"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/00251201-Barbell-Bench-Press_Chest_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00251201-Barbell-Bench-Press_Chest.mp4","howto":["Lie on the bench.","Extend your arms and grab the bar evenly, having your hands slightly wider than shoulder-width apart.","Bring your shoulder blades back and dig them into the bench.","Arch your lower back and plant your feet flat on the floor.","Take a breath, unrack the bar, and bring it over your chest.","Inhale again and lower the barbell to your lower chest, tapping it slightly.","Hold for a moment and press the bar until your elbows are straight. Exhale."]},{"id":"99C1F2AD","name":"Bench Press (Cable)","primary":"chest","secondary":["shoulders","triceps"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/01511201-Cable-Bench-Press_Chest_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/01511201-Cable-Bench-Press_Chest.mp4","howto":["Place a flat gym bench in the middle of a double cable machine.","Adjust the load on both weight stacks, position the pulleys low, and attach handles.","Grab both handles and sit on the bench while keeping your arms close to your body.","Lie back carefully and bring your arms to your sides without flaring your elbows.","Bring your shoulders back, engage your abs, and take a breath.","Push both handles up and in, tapping your knuckles at the top as you exhale.","Lower the weights carefully until your elbows are at torso level, and breathe in.","Once finished, bring your arms in, get up slowly, and release both handles."]},{"id":"3601968B","name":"Bench Press (Dumbbell)","primary":"chest","secondary":["triceps","shoulders"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/02891201-Dumbbell-Bench-Press_Chest_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/02891201-Dumbbell-Bench-Press_Chest.mp4","howto":["Grab a pair of dumbbells, sit on a flat gym bench, and place both weights on top of your thighs.","Bring your shoulders back, engage your abs, take a breath, and flex your arms.","Kick both dumbbells up with your thighs as you lie back.","With your arms straight and dumbbells over your chest, dig your shoulder blades into the bench and place your feet flat on the floor.","Take another breath and lower both dumbbells to your sides. Keep your elbows somewhat tucked.","Lower the weights until your elbows are at torso level.","Press both dumbbells to the starting position, bringing them together as you exhale."]},{"id":"0FBF7195","name":"Bench Press (Smith Machine)","primary":"chest","secondary":["shoulders","triceps"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/07481201-Smith-Bench-Press_Chest_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/07481201-Smith-Bench-Press_Chest.mp4","howto":["Place a flat gym bench in the middle of a Smith machine.","Adjust the bar to a height where you can grab and unrack it from a lying position.","Lie on the bench and position your lower chest directly underneath the bar.","Grab the bar with an even overhand grip.","Bring your shoulders back and dig the balls of your feet into the floor.","Take a breath and unrack the bar.","Lower the bar until it taps your chest and press it to the top as you exhale."]},{"id":"35B51B87","name":"Bench Press - Close Grip (Barbell)","primary":"triceps","secondary":["chest","shoulders"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/00301201-Barbell-Close-Grip-Bench-Press_Upper-Arms_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00301201-Barbell-Close-Grip-Bench-Press_Upper-Arms.mp4","howto":["Set the barbell at a height where you can reach it from a lying position.","Lie on the bench and position your head underneath the bar.","Reach up and grab the bar with an even, overhand grip. Your hands should be shoulder-width apart.","Bring your shoulder blades back and draw your feet back and toward the bench, digging the balls of your feet into the floor.","Engage your body, unrack the bar, and bring it over your chest.","Breathe in and lower the barbell to your lower chest.","Press the bar to the top position and exhale.","Once finished, bring the barbell over the rack and rest it gently."]},{"id":"E644F828","name":"Bench Press - Wide Grip (Barbell)","primary":"chest","secondary":["shoulders","triceps"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/01221201-Barbell-Wide-Bench-Press_Chest_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/01221201-Barbell-Wide-Bench-Press_Chest.mp4","howto":["Set the barbell at a height where you can grab it from a lying position.","Lie on the bench and position yourself so that the bar is directly over your forehead.","Reach up and grab the bar with an overhand grip. Start with your hands shoulder-width apart, and gradually increase your grip width.","Retract your shoulder blades and dig them into the bench.","Bring your feet back and in toward the bench, digging the balls of your feet into the floor.","Engage your upper body, unrack the barbell, and bring it over your chest.","Take a breath and lower the barbell to the bottom (lower chest, nipple line).","Tap your torso and push the bar back to the top, squeezing your triceps, shoulders, and pectorals. Exhale near the top.","Once finished, bring the bar back over the safety pins and rack it."]},{"id":"EA820646","name":"Bent Over Row (Band)","primary":"upper_back","secondary":["lats","biceps","forearms"],"equipment":"resistance_band","type":"weight_reps","thumb":"assets/thumbs/38991201-Band-bent-over-row-(male)_Back_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/38991201-Band-bent-over-row-(male)_Back.mp4","howto":["Take an open-ended resistance band with handles on both sides.","Step over the middle of the band with both feet.","Grab both handles and lean forward while keeping your spine neutral. The band should offer some tension even with your arms fully extended. You can increase or decrease the tension by having your feet closer or wider apart.","Bring your shoulders back and take a breath.","Pull both ends of the band up and in until your elbows are at torso level. Exhale at the top.","Extend your arms as you breathe in."]},{"id":"55E6546F","name":"Bent Over Row (Barbell)","primary":"upper_back","secondary":["lats","biceps","forearms"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/00271201-Barbell-Bent-Over-Row_Back_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00271201-Barbell-Bent-Over-Row_Back.mp4","howto":["Stand in front of a loaded barbell with your feet in a comfortable stance and toes pointing slightly out.","Lean forward by hinging at the hip and keep your spine in a neutral position.","Grab the barbell with an even overhand grip.","Engage your abs and lift the bar several inches off the floor.","With your shoulders back and midsection tight, take a breath and row the barbell.","Lift the bar until it taps your stomach and hold the position for a moment as you exhale.","Lower the bar slowly."]},{"id":"23E92538","name":"Bent Over Row (Dumbbell)","primary":"upper_back","secondary":["lats","biceps","forearms"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/02931201-Dumbbell-Bent-Over-Row_Back_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/02931201-Dumbbell-Bent-Over-Row_Back.mp4","howto":["Grab a pair of dumbbells and stand tall.","Bring your shoulders back, engage your abs, and lean forward while keeping your back straight. Your torso should be as parallel to the floor as possible.","Have your arms straight and hanging down with your wrists neutral (facing one another).","Take a breath and row both dumbbells until your elbows are at torso level. Exhale at the top.","Lower the weights, breathing in on the way down."]},{"id":"EB813C91","name":"Bent Over Row (Smith Machine)","primary":"upper_back","secondary":["lats","biceps","forearms"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/13591201-Smith-Bent-Over-Pronated-Grip-Row_Back-FIX_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/13591201-Smith-Bent-Over-Pronated-Grip-Row_Back-FIX_.mp4","howto":["Set the bar at mid-thigh height and add your weight.","Stand close to the bar, almost pressing your thighs against it. Your feet should be hip-width apart.","Grab the bar with an overhand grip - palms facing back. Have your hands roughly shoulder-width apart.","Breathe in, engage your abs, and unrack the bar.","Lower the bar to mid-shin height by leaning your torso forward and pushing your buttocks back. Your spine should remain in a neutral position.","Take another breath and pull the bar in one fluid motion while keeping your torso at the same angle.","Exhale at the top as you squeeze your back muscles.","Slowly lower the bar until your arms are straight and breathe in on the way down.","Repeat."]},{"id":"A5AC6449","name":"Bicep Curl (Barbell)","primary":"biceps","secondary":[],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/00311201-Barbell-Curl_Upper-Arms_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00311201-Barbell-Curl_Upper-Arms.mp4","howto":["Pick the bar up and hold it with a grip slightly wider than your hips. Your arms should be straight, with your palms facing forward.","Straighten your back, bring your chest out, take a breath, and curl the barbell, exhaling at the top. Don’t use body swinging and momentum to lift the bar; only your bicep strength.","Lower the bar slowly as you breathe in, extending your arms and stretching your biceps.","Repeat."]},{"id":"ADA8623C","name":"Bicep Curl (Cable)","primary":"biceps","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/59221201-Cable-SZ-bar-Close-Grip-Curl_Upper-Arms_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/59221201-Cable-SZ-bar-Close-Grip-Curl_Upper-Arms_.mp4","howto":["Attach a straight bar to a low cable pulley.","Set the load on the weight stack at the appropriate amount.","Lean forward and grab the straight bar evenly with your palms facing up.","Stand up and step back (if necessary) to lift the weight from its stack.","Bring your shoulders back, engage your abs, and have your elbows to your sides.","Take a breath and curl the weight, keeping your elbows steady.","Lift the weight until your wrists are slightly higher than your elbows and exhale.","Lower the weight slowly, breathing in on the way down."]},{"id":"37FCC2BB","name":"Bicep Curl (Dumbbell)","primary":"biceps","secondary":[],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/02941201-Dumbbell-Biceps-Curl_Upper-Arms_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/02941201-Dumbbell-Biceps-Curl_Upper-Arms.mp4","howto":["Grab a pair of dumbbells and stand tall with your feet in a comfortable stance and shoulders retracted.","Have your wrists pointing forward and your arms extended.","Take a breath and curl both dumbbells simultaneously. Lift the weights until your wrists are slightly higher than your elbows and exhale.","Extend your arms slowly and breathe in on the way down."]},{"id":"AF328E3D","name":"Bicep Curl (Machine)","primary":"biceps","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/10321101-Lever-Alternate-Biceps-Curl_Upper-Arms_small_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/10321201-Lever-Alternate-Biceps-Curl_Upper-Arms_.mp4","howto":["Select the correct load on the machine and adjust your seat’s height.","Sit down and grab the handles by your sides.","Bring your shoulders back, engage your abs, and take a breath.","Bend one arm to lift the handle. Curl until your hand is slightly higher than your elbow, and breathe out.","Extend your arm slowly as you breathe in.","Bend your opposite arm in the same way.","Keep alternating until you finish the set."]},{"id":"0B4C1902","name":"Bicep Curl (Suspension)","primary":"biceps","secondary":[],"equipment":"suspension","type":"reps_only","thumb":"assets/thumbs/59261201-Suspender-Arm-Curl-(male)_Upper-Arms_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/59261201-Suspender-Arm-Curl-(male)_Upper-Arms_.mp4","howto":["Grab the pair of handles attached to a suspension training kit.","Walk your feet forward to lean your body back to some degree.","Extend your body, squeeze your glutes, and bring your shoulders back.","Take a breath and bend your arms to lift your body.","Bend your arms until your elbows are at slightly more than a 90-degree angle, and breathe out.","Extend your arms slowly, lowering your body to the starting position as you breathe in."]},{"id":"A41C7261","name":"Bicycle Crunch","primary":"abdominals","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/00031201-air-bike-m_waist_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00031201-air-bike-m_waist.mp4","howto":["Lie on the floor, lift your legs off the floor, and bend your knees at a 90-degree angle.","Place your fingertips behind your head or neck.","Take a breath, engage your midsection, and crunch, bringing your right elbow to your left knee. Exhale.","Extend your body as you breathe in.","Crunch again, taking your left elbow to your right knee. Exhale again.","Keep alternating until you complete the set."]},{"id":"594450D2","name":"Bicycle Crunch Raised Legs","primary":"abdominals","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/62111201-Bicycle-Crunch-(male)_Waist_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/62111201-Bicycle-Crunch-(male)_Waist_.mp4","howto":["Lie on the floor, lift your legs off the ground, and extend them in the air.","Place your fingertips behind your head or neck.","Take a breath, engage your midsection, and crunch your upper body.","Twist your upper body, bringing your right elbow to your left leg. Simultaneously bend your left knee and get it closer to the opposite elbow.","Hold for a moment as you breathe out.","Extend your body and breathe in.","Take your left elbow to your right knee.","Keep alternating until you complete the set."]},{"id":"BD0AD077","name":"Bird Dog","primary":"glutes","secondary":["hamstrings","shoulders"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/12411201-Bird-Dog-male_Back_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/12411201-Bird-Dog-male_Back.mp4","howto":["Get down on all fours. Have your shoulders, elbows, and wrists aligned and your knees directly under your hips. Keep your hands flat on the floor.","Engage your abs and take a breath.","Extend your right leg back and up, aligning it with your torso. At the same time, extend your left arm and raise it forward. Exhale.","Bring your arm and leg to the starting position as you breathe in.","Extend your opposite limbs.","Keep alternating between opposite limbs until you complete the set."]},{"id":"56092DD1","name":"Box Jump","primary":"quadriceps","secondary":["hamstrings","glutes","calves"],"equipment":"other","type":"reps_only","thumb":"assets/thumbs/49651201-Jump-Box-(male)_Plyometrics-FIX_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/49651201-Jump-Box-(male)_Plyometrics-FIX_.mp4","howto":["Stand in front of a plyometric box or a flat gym bench.","Have your feet close and your spine neutral.","Take a breath and descend into a quarter squat as you bring your arms back.","Immediately jump by pushing through your heels and swinging your arms forward.","Exhale as you land on the bench or box.","Step off and breathe in."]},{"id":"38FC1AB9","name":"Box Squat (Barbell)","primary":"quadriceps","secondary":["hamstrings","glutes"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/49621201-Barbell-Box-Squat_Hips_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/49621201-Barbell-Box-Squat_Hips_.mp4","howto":["Set the barbell at the appropriate height and position a plyometric box behind you.","Unrack the bar as you would for standard squats and take a couple of steps back. The box should be a few inches away from your heels.","Take a breath and descend into a squat.","Move down until your buttocks touch the box.","Hold the position for a moment and push through your heels to squat up. Exhale."]},{"id":"A0D8FA1B","name":"Boxing","primary":"cardio","secondary":[],"equipment":"none","type":"duration","thumb":"assets/thumbs/102961201-Boxing-Cross-(with-bag-and-gloves)_Plyometrics_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/102961201-Boxing-Cross-(with-bag-and-gloves)_Plyometrics_.mp4","howto":[]},{"id":"0F24286A","name":"Bulgarian Split Squat (Barbell)","primary":"quadriceps","secondary":["glutes","hamstrings"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/00991201-Barbell-Single-Leg-Split-Squat_Hips_1_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00991201-Barbell-Single-Leg-Split-Squat_Hips_.mp4","howto":["Face away from a flat gym bench or plyometric box.","Grab the barbell, lift it overhead, and position it behind your neck, on top of your trapezius muscle.","Extend one leg back, placing the foot on the bench.","Bring your shoulders back, engage your midsection, and take a breath.","Descend by bending your front knee.","Go down until your front thigh is almost parallel to the floor.","Hold the bottom position for a moment and push through your heel to extend your leg as you exhale.","Do the desired number of reps, switch legs, and match the rep count for your other leg."]},{"id":"B5D3A742","name":"Bulgarian Split Squat (Dumbbell)","primary":"quadriceps","secondary":["glutes","hamstrings"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/04101201-Dumbbell-Single-Leg-Split-Squat_Thighs_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/04101201-Dumbbell-Single-Leg-Split-Squat_Thighs_.mp4","howto":["Face away from a flat gym bench.","Grab a pair of dumbbells and extend one leg back, placing the foot on the bench.","Bring your shoulders back, engage your midsection, and take a breath.","Squat by bending your front leg.","Descend until your front thigh is almost parallel to the floor.","Hold the bottom position for a moment and push through your heel to extend your leg as you exhale.","Do the desired number of reps, switch legs, and match the rep count for your other leg."]},{"id":"BB792A36","name":"Burpee","primary":"full_body","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/11601201-Burpee_Cardio_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/11601201-Burpee_Cardio.mp4","howto":["Stand tall with your feet in a comfortable stance, arms to your sides, and gaze directed forward.","Take a breath, lean forward and bend your knees to place your hands flat on the floor, just in front of your feet.","Kick your legs back to extend your body into a push-up position. Your shoulders, hips, knees, and ankles should be aligned.","Inhale and perform a push-up, descending until your face is an inch or two from the floor (optional). Exhale as you extend your arms.","Kick your legs forward to bring your feet just behind your hands as you breathe in.","Extend your body and perform a vertical jump as you raise your arms above your head. Exhale."]},{"id":"115CC72C","name":"Burpee Broad Jumps","primary":"full_body","secondary":[],"equipment":"none","type":"distance_duration","thumb":"assets/thumbs/51871201-Burpee-Long-Jump-with-Push-up-(male)_Cardio_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/51871201-Burpee-Long-Jump-with-Push-up-(male)_Cardio_.mp4","howto":["Stand tall with your feet shoulder-width apart.","Breathe in, lean forward, place your hands in a comfortable push-up position, and kick your legs back to extend your body.","Perform a push-up, touching your chest to the floor.","Push yourself up and kick your feet forward, landing them close to your hands.","Stand up and perform a double-leg jump as you breathe out.","Immediately take another breath and drop down for the next push-up."]},{"id":"86B00DDE","name":"Burpee Over the Bar","primary":"full_body","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/101811201-Burpee-Over-the-Bar-(male)_Plyometrics_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/101811201-Burpee-Over-the-Bar-(male)_Plyometrics_.mp4","howto":["Place a barbell on the ground and stand perpendicular to it.","Get down into a high plank position.","With your body straight and shoulders, elbows, and wrists aligned, take a breath and do a push-up. Push yourself back to the high plank position as you exhale.","Kick your feet forward and stand up.","Jump laterally over the barbell as you breathe out again.","Get down to a high plank position again, breathe in, and perform another push-up.","Stand up and jump laterally over the barbell again, repeating the sequence.","Keep jumping over the bar until you're finished."]},{"id":"9DCE2D64","name":"Butterfly (Pec Deck)","primary":"chest","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/10301201-Lever-Pec-Deck-Fly_Chest_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/10301201-Lever-Pec-Deck-Fly_Chest.mp4","howto":["Select the load on the pec deck machine.","Adjust the seat height so you can grab the handles and have the pads in front of your chest.","Sit down, grab the handles, and bring your shoulders back.","Engage your abs and take a breath.","Flex your chest muscles to bring the handles from your sides to in front of your torso as you breathe out.","Bring your arms to your sides as you breathe in."]},{"id":"CC55119B","name":"Cable Core Pallof Press","primary":"abdominals","secondary":["chest","shoulders","triceps"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/12021201-Cable-horizontal-Pallof-Press_waist_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/12021201-Cable-horizontal-Pallof-Press_waist.mp4","howto":["Select the load on the cable machine.","Place the pulley at chest height and attach a handle.","Grab the handle with both hands and stand sideways.","Bring your shoulders back, squeeze your glutes, and engage your midsection.","Take a breath and press the handle forward, fully extending your arms and exhaling.","Pause for a moment and bring the handle to your body as you breathe in."]},{"id":"23A48484","name":"Cable Crunch","primary":"abdominals","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/01751201-Cable-Kneeling-Crunch_Waist_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/01751201-Cable-Kneeling-Crunch_Waist.mp4","howto":["Grab a rope attachment with both hands and have your thumbs facing up.","Kneel, lean forward, and position the rope behind your head. Keep your hands close to your neck.","Once in position, engage your midsection.","Initiate the crunch by taking a breath and flexing your abs. Focus on crunching your torso instead of simply moving at the hips.","Hold for a moment as you exhale.","Slowly raise your torso to bring yourself to the starting position as you breathe in."]},{"id":"651F844C","name":"Cable Fly Crossovers","primary":"chest","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/12691201-Cable-Standing-Up-Straight-Crossovers_Chest_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/12691201-Cable-Standing-Up-Straight-Crossovers_Chest.mp4","howto":["Adjust the load on the pair of weight stacks inside the cable crossover machine.","Set the pulleys in the highest position and attach handles on both.","Grab the handles one at a time and position yourself in the middle between the two pillars.","Bring your arms to your sides and take a half step forward to lift the weights from their stacks.","Engage your abs, bring your shoulders back, and inhale.","Bring your arms in and down, meeting your knuckles in front of your hips. Exhale.","Hold for a moment and bring your arms to your sides as you breathe in."]},{"id":"8C331CD8","name":"Cable Pull Through","primary":"glutes","secondary":["hamstrings","lower_back"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/12061201-Cable-pull-through_hips_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/12061201-Cable-pull-through_hips.mp4","howto":["Select the appropriate load on a single or double cable machine station.","Set the pulley in the lowest position and attach a handle or rope.","Face away from the cable machine, lean forward, grab the attachment, and hold it between your legs.","Take a step or two forward to lift the weight from its stack.","Engage your abs and take a breath.","Hinge at the hips, leaning your torso forward while keeping your back neutral.","Lean forward until your torso is roughly parallel to the floor and extend your body by driving your hips forward. Exhale as you stand tall."]},{"id":"92D858EA","name":"Cable Twist (Down to up)","primary":"abdominals","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/81931201-Cable-Reverse-Woodchop-(male)_Waist_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/81931201-Cable-Reverse-Woodchop-(male)_Waist_.mp4","howto":["Select the appropriate load on the cable machine.","Place the pulley in the lowest position and attach a handle to it.","Grab the handle with both hands, keeping your wrists neutral (facing one another).","Take a step away from the cable machine and stand sideways with your feet wide enough to create a stable base.","With the handle at your waist and arms straight, engage your abs and take a breath.","Pull the cable diagonally and upward across your body, twisting your torso and exhaling.","Hold for a second and rotate your torso to the starting position as you breathe in.","Once finished training one side, turn your body 180 degrees and do the same number of reps for the other side."]},{"id":"A2D838BD","name":"Cable Twist (Up to down)","primary":"abdominals","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/08621201-Cable-twist-(up-down)_Waist_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/08621201-Cable-twist-(up-down)_Waist.mp4","howto":["Select the appropriate load on the cable machine.","Place the pulley in the highest position and attach a handle to it.","Grab the handle with both hands, keeping your wrists neutral (facing one another).","Take a step away from the cable machine and stand sideways.","With the handle at shoulder level and arms straight, engage your abs and breathe in.","Pull the cable diagonally across your body, twisting your torso and exhaling.","Rotate your body to the starting position as you breathe in.","Once finished, turn your body 180 degrees and do the same number of reps for the other side."]},{"id":"47B9DF13","name":"Calf Extension (Machine)","primary":"calves","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/23151201-Lever-Rotary-Calf_Calves_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/23151201-Lever-Rotary-Calf_Calves.mp4","howto":["Select the appropriate load on the calf extension machine.","Sit down and grab the handles by your sides.","Place the balls of your feet on the footplate. Your legs should be straight.","Take a breath and flex your ankles to push the plate away as you exhale.","Hold for a moment and allow your ankles to bend as you breathe in."]},{"id":"91237BDD","name":"Calf Press (Machine)","primary":"calves","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/07381201-Sled-45-Calf-Press_Calves_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/07381201-Sled-45-Calf-Press_Calves.mp4","howto":["Load a leg press machine and sit down.","Raise your legs and place the balls of your feet at the edge of the footplate.","Bring your shoulders back and grab the handles by your sides.","Extend your knees to unrack the weight.","Flex your ankles to press the platform away from yourself and hold for a moment as you breathe out.","Allow your ankles to bend and stretch your calves as you breathe in.","Once finished, turn the handles you’re holding to secure the weight."]},{"id":"6FCD7755","name":"Chest Dip","primary":"chest","secondary":["shoulders","triceps"],"equipment":"machine","type":"reps_only","thumb":"assets/thumbs/02511201-Chest-Dip_Chest_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/02511201-Chest-Dip_Chest.mp4","howto":["Grip a parallel bar slightly outside shoulder-width level.","Bring your shoulders back and engage your abs.","Raise yourself and stand over the dip bar with your elbows fully extended.","Tilt your body forward.","Take a breath and dip by bending at the elbows. Maintain your body’s position as you move down.","Lower yourself until you feel a good pectoral stretch (generally to the point where your elbows are at a 90-degree angle).","Push yourself back to the top, exhaling at the top."]},{"id":"E9E4089F","name":"Chest Dip (Assisted)","primary":"chest","secondary":["triceps","shoulders"],"equipment":"machine","type":"bodyweight_assisted_reps","thumb":"assets/thumbs/00091201-Assisted-Chest-Dip-(kneeling)_Chest_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00091201-Assisted-Chest-Dip-(kneeling)_Chest.mp4","howto":["Select the correct weight on the chest dip machine.","Grab the pair of handles and place your knees over the pads.","Extend your arms, bring your shoulders back, and squeeze your abs.","Take a breath and lower yourself by bending your elbows.","Descend until your elbows are at roughly 90 degrees, and push yourself back to the top as you exhale."]},{"id":"29472BE1","name":"Chest Dip (Weighted)","primary":"chest","secondary":["triceps","shoulders"],"equipment":"machine","type":"bodyweight_reps","thumb":"assets/thumbs/17551201-Weighted-Tricep-Dips_Upper-Arms_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/17551201-Weighted-Tricep-Dips_Upper-Arms_.mp4","howto":["Attach a weight plate to yourself via a special belt.","Step on the platform and grab the parallel bars while keeping your arms straight and close to your body.","Bring your shoulders back and down, engage your abs, and squeeze your glutes.","Take your feet off the platform to suspend yourself in the air.","Lean forward slightly.","Take a breath and lower yourself by bending your elbows. Keep your shoulder blades retracted and your body steady.","Descend until your elbows form a 90-degree angle and hold for a moment.","Press yourself back to the top, extending your arms fully and exhaling.","Take another breath and repeat."]},{"id":"DDB7C19F","name":"Chest Fly (Band)","primary":"chest","secondary":[],"equipment":"resistance_band","type":"weight_reps","thumb":"assets/thumbs/40751201-Band-Chest-Fly-(male)_Chest-FIX_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/40751201-Band-Chest-Fly-(male)_Chest-FIX_.mp4","howto":["Take an open-ended resistance band with handles on both ends.","Anchor the band on something sturdy (e.g., a squat rack).","Turn away from the anchor point and grab both handles, keeping them close to your body.","Take a couple of steps forward to lengthen the band and bring your arms to your sides without flaring your elbows.","Bring your shoulders back, engage your abs, and take a breath.","Move your arms forward and tap your knuckles in front of your chest while keeping your elbows slightly bent. Breathe out.","Bring your arms to the sides as you breathe in."]},{"id":"12017185","name":"Chest Fly (Dumbbell)","primary":"chest","secondary":[],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/03081201-Dumbbell-Fly_Chest_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/03081201-Dumbbell-Fly_Chest.mp4","howto":["Grab a pair of light dumbbells and sit on the edge of a flat gym bench.","Place the weights on your thighs and lie back, keeping the dumbbells close to your body.","Extend your arms and position the dumbbells over your chest with your palms facing one another.","Plant your feet on the floor and bring your shoulders back.","Take a breath.","Lower your arms to your sides until they align with your torso.","Bring your arms in, tapping the dumbbells over your chest as you exhale."]},{"id":"78683336","name":"Chest Fly (Machine)","primary":"chest","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/05961201-Lever-Seated-Fly_Chest_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/05961201-Lever-Seated-Fly_Chest.mp4","howto":["Select the appropriate load and adjust the seat height. The machine’s handles should be at chest level when you sit.","Sit down, bring your shoulders back, and reach to the sides to grab the handles.","Engage your abs and take a breath.","Squeeze your chest and bring your arms in, tapping your knuckles lightly in front of your chest as you breathe out.","Bring your arms to your sides, feeling your chest muscles stretch. Breathe in."]},{"id":"720B0D70","name":"Chest Fly (Suspension)","primary":"chest","secondary":[],"equipment":"suspension","type":"reps_only","thumb":"assets/thumbs/57371201-Suspension-Fly_Chest-FIX_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/57371201-Suspension-Fly_Chest-FIX_.mp4","howto":["Face away from the anchor point of your suspension kit and grab both handles.","Straighten your arms, raise them in front of your body, and engage your abs.","Walk your feet back enough to lean your body forward. Support yourself with your arms.","Take a breath and slowly bring your arms to your sides, lowering yourself and stretching your pectorals.","Extend your arms to your sides as much as your strength allows, hold for a moment, and bring them in, raising yourself in the process.","Tap your knuckles at the top position and exhale."]},{"id":"EAC7D9C5","name":"Chest Press (Band)","primary":"chest","secondary":["shoulders","triceps"],"equipment":"resistance_band","type":"weight_reps","thumb":"assets/thumbs/37801201-Band-Standing-Chest-Press-(male)_Chest_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/37801201-Band-Standing-Chest-Press-(male)_Chest.mp4","howto":["Take an open-ended resistance band with handle attachments.","Anchor the band on something sturdy at chest height. A squat rack can work.","Face away from the anchor point and grab both handles, raising your arms high and keeping your elbows tucked.","Take a couple of steps forward to stretch the band and create some tension.","Bring your shoulders back, stagger your stance, engage your midsection, and take a breath.","Press the band forward and extend your arms fully as you exhale.","Bend your arms, bringing your knuckles to the sides of your chest, as you breathe in."]},{"id":"7EB3F7C3","name":"Chest Press (Machine)","primary":"chest","secondary":["shoulders","triceps"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/05771201-Lever-Chest-Press_Chest_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/05771201-Lever-Chest-Press_Chest.mp4","howto":["Select the appropriate load on the machine.","Adjust the seat height. The handles should be slightly below your lower chest when you sit down.","Sit down, grab the handles, bring your shoulders back, and engage your abs. Have your feet flat on the floor.","Take a breath and press until your arms extend fully. Exhale.","Bend your arms slowly as you breathe in."]},{"id":"914F3A96","name":"Chest Supported Incline Row (Dumbbell)","primary":"upper_back","secondary":["lats","biceps","forearms"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/03271201-Dumbbell-Incline-Row_Back_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/03271201-Dumbbell-Incline-Row_Back.mp4","howto":["Set an adjustable gym bench at an incline of 30 to 45 degrees.","Grab a pair of dumbbells and position yourself on the bench with your stomach and chest on the back support.","Have your arms extended and hanging straight down.","Bring your shoulders back, squeeze your glutes, and engage your abs.","Rotate your wrists out so your knuckles face forward.","Take a breath and row the dumbbells as high as possible in one fluid motion. Exhale at the top.","Lower the weights slowly, breathing in on the way down."]},{"id":"B582299E","name":"Chest Supported Reverse Fly (Dumbbell)","primary":"shoulders","secondary":["upper_back"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/03831201-Dumbbell-Reverse-Fly_Shoulders_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/03831201-Dumbbell-Reverse-Fly_Shoulders.mp4","howto":["Grab a pair of light dumbbells and position yourself face down on an incline gym bench.","Keep your body straight and support yourself on the balls of your feet.","Your arms should be straight and vertical, with your palms facing one another.","Bring your shoulders back and take a breath.","Lift the dumbbells to your sides and back, stopping when you feel tension in the posterior of your shoulders. Exhale.","Hold for a moment and bring your arms down slowly as you breathe in."]},{"id":"6A8D3193","name":"Chest Supported T Bar Row","primary":"upper_back","secondary":["lats","biceps","forearms"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/11941201-Lever-Lying-T-bar-Row_Back_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/11941201-Lever-Lying-T-bar-Row_Back.mp4","howto":["Add weight to the bar.","Get on the machine and position your chest and stomach on the pad, and your feet on the platform.","Reach forward and grab both handles with an overhand grip - palms facing down.","Unrack the bar and bring it to the middle.","Breathe in and pull the bar in one fluid motion, squeezing your upper back and breathing out.","Slowly extend your arms as you breathe in.","Repeat."]},{"id":"F21D5693","name":"Chest Supported Y Raise (Dumbbell)","primary":"shoulders","secondary":["upper_back"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/35411201-Dumbbell-Incline-Y-Raise_Shoulders__thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/35411201-Dumbbell-Incline-Y-Raise_Shoulders_.mp4","howto":["Set a gym bench at a 45-degree incline.","Grab a pair of light dumbbells and sit down with your chest and stomach against the back support and arms hanging straight down.","Take a deep breath and lift the dumbbells forward and up in one fluid motion, exhaling at the top.","Lower the weights to the starting position as you breathe in."]},{"id":"29083183","name":"Chin Up","primary":"lats","secondary":["upper_back","biceps","forearms"],"equipment":"machine","type":"reps_only","thumb":"assets/thumbs/13261201-Chin-Up_Back_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/13261201-Chin-Up_Back.mp4","howto":["Reach up and grab a pull-up bar with a double underhand grip (palms facing back). Your hands should be shoulder-width apart or slightly closer.","Retract your shoulders, engage your abs, squeeze your glutes, and cross your lower legs, lifting your feet off the floor.","Take a breath and pull yourself up in one fluid motion. Aim to have your chin over the bar at the top. Exhale.","Lower yourself slowly and breathe in. Don’t rest your feet on the floor."]},{"id":"D23C609B","name":"Chin Up (Assisted)","primary":"lats","secondary":["upper_back","biceps","forearms"],"equipment":"machine","type":"bodyweight_assisted_reps","thumb":"assets/thumbs/05721301-assisted-chin-up_small_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/05721201-Lever-Assisted-Chin-Up_Back_.mp4","howto":["Select the appropriate load on the machine.","Reach up and grab the bar with a double underhand grip (palms facing back). Have your hands shoulder-width apart.","Place your knees on top of the machine pad.","Bring your shoulders back, squeeze your glutes, and engage your abs.","Take a breath and pull yourself up in one fluid motion, exhaling at the top.","Lower yourself slowly, extending your arms fully. Breathe in."]},{"id":"023943F1","name":"Chin Up (Weighted)","primary":"lats","secondary":["upper_back","biceps","forearms"],"equipment":"machine","type":"bodyweight_reps","thumb":"assets/thumbs/29871101-Weighted-Close-Grip-Chin-up-on-Dip-Cage_Back_small_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/41811201-Weighted-Hang-Chin-Up_Back_.mp4","howto":["Attach a weight plate to yourself with a special weight belt.","Reach up and grab a pull-up bar with a double underhand grip (palms facing back).","Retract your shoulders, engage your abs, squeeze your glutes, and cross your lower legs, lifting your feet off the floor.","Take a breath and pull yourself up in one fluid motion as you breathe out.","Lower yourself slowly, extending your arms fully, and breathe in. Don’t rest your feet on the floor."]},{"id":"CC016611","name":"Clamshell","primary":"glutes","secondary":[],"equipment":"resistance_band","type":"reps_only","thumb":"assets/thumbs/98571201-Resistance-Band-Side-Plank-Clamshell-(male)_Hips_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/98571201-Resistance-Band-Side-Plank-Clamshell-(male)_Hips_.mp4","howto":["Lie on one side with your legs stacked, knees bent, bottom shoulder at 90 degrees, and the forearm flat on the floor for balance. You can wrap a mini looped resistance band over your thighs for additional resistance.","Maintain a neutral spine and breathe in.","Raise your top knee while keeping your feet together. The movement should resemble a clamshell opening.","Lift your knee as much as possible in one fluid motion and exhale.","Lower your knee to the bottom as you breathe in.","Once finished, flip to your other side and do the same number of reps."]},{"id":"10D76E8F","name":"Clap Push Ups","primary":"chest","secondary":["triceps","shoulders"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/12731101-Clap-Push-Up_Plyometrics_Chest_small_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/12731201-Clap-Push-Up_Plyometrics_Chest.mp4","howto":["Get down on all fours and extend your body into a push-up position. Your body should be straight, and your shoulders, elbows, and wrists should be aligned.","Bring your shoulders back and squeeze your buttocks.","Take a breath and lower yourself by bending your elbows.","Descend until your face is an inch or two from the floor and hold for a moment.","Push yourself as explosively as possible, lifting your hands off the floor. Breathe out.","Immediately bring your hands together and clap before planting them on the floor.","Breathe in as you lower yourself."]},{"id":"ABB00838","name":"Clean","primary":"full_body","secondary":[],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/52871201-Barbell-Full-Clean_Weightlifting-FIX_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/52871201-Barbell-Full-Clean_Weightlifting-FIX_.mp4","howto":["Stand in front of a loaded barbell with your shins a couple of inches away. Your feet should be hip-width apart with toes pointed slightly out.","Bend down and grab the barbell with an even, overhand grip. Have your knees against the crease of your elbows.","Bring your chest out to put your back in a neutral position. Your hips should be slightly higher than your knees.","Initiate the first pull by deadlifting the barbell off the floor as you press your heels into the ground. Make the initial pull powerful to generate momentum for the next part of the lift.","Once the barbell travels above your knees, keep driving your hips forward as you begin pulling the weight in a straight vertical line. The entire sequence should happen in one smooth motion.","As the barbell travels up, squat, catch it, and have it land over your shoulders and upper chest. Maintain a firm grip on the barbell, and keep your elbows pointing forward.","As the barbell lands in a front rack position, dip a few extra inches until your thighs are parallel to the floor and squat to the top, straightening your knees fully and exhaling.","Lower the barbell slowly and hinge at the hip to maintain a neutral spine. Breathe in as the bar moves down or before initiating the next rep."]},{"id":"9E09CEC3","name":"Clean and Jerk","primary":"full_body","secondary":[],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/00281201-Barbell-Clean-and-Press_Shoulders_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00281201-Barbell-Clean-and-Press_Shoulders.mp4","howto":["Stand in front of a loaded barbell with your shins a couple of inches away. Your feet should be hip-width apart, with toes pointed slightly out.","Bend down and grab the barbell with an even, overhand grip. Have your knees against the crease of your elbows.","Bring your chest out to put your back in a neutral position. Your hips should be slightly higher than your knees.","Initiate the first pull by deadlifting the barbell off the floor as you press your heels into the ground. Make the initial pull powerful to generate momentum for the next part of the lift.","Once the barbell travels above your knees, keep driving your hips forward as you begin pulling the weight in a straight vertical line. The entire sequence should happen in one smooth motion.","As the barbell travels up, squat, catch it, and have it land over your shoulders and upper chest. Maintain a firm grip on the barbell, and keep your elbows pointing forward.","As the barbell lands in a front rack position, dip a few extra inches until your thighs are parallel to the floor and squat to the top, straightening your knees fully and breathing out.","Take another breath, dip slightly, and jerk the bar, bringing it over your head, extending your elbows and knees.","Lower the barbell to your shoulders and breathe out.","Bring the bar to the floor while keeping your back neutral. Breathe in on the way down or before initiating the next rep."]},{"id":"D3095577","name":"Clean and Press","primary":"full_body","secondary":[],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/00281201-Barbell-Clean-and-Press_Shoulders_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00281201-Barbell-Clean-and-Press_Shoulders.mp4","howto":["Stand in front of a loaded barbell with your shins a couple of inches away. Your feet should be hip-width apart, with toes pointed slightly out.","Lean forward and grab the barbell with an even, overhand grip. Have your knees against the crease of your elbows.","Bring your chest out to put your back in a neutral position. Your hips should be slightly higher than your knees.","Initiate the first pull by deadlifting the barbell off the floor as you press your heels into the ground. Make the initial pull powerful to generate momentum for the next part of the lift.","Once the barbell travels above your knees, keep driving your hips forward as you begin pulling the weight in a straight vertical line. The entire sequence should happen in one smooth motion.","As the barbell travels up, squat, catch it, and have it land over your shoulders and upper chest. Maintain a firm grip on the barbell and keep your elbows pointing forward.","As the barbell lands in a front rack position, dip a few extra inches until your thighs are parallel to the floor and squat to the top, straightening your knees fully and exhaling.","Take another breath and press the bar straight up, bringing your head back to avoid bumping your nose or chin. Exhale again.","Lower the bar to your shoulders before returning it to the starting position."]},{"id":"652FEA39","name":"Clean Pull","primary":"full_body","secondary":[],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/15171101-Barbell-Clean-Pull_Weightlifts_small_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/15171201-Barbell-Clean-Pull_Weightlifts_.mp4","howto":["Stand in front of a barbell. Your feet should be hip-width apart and the barbell should be over the mid-foot.","Lean forward and grab the barbell with an even overhand grip.","Bring your shoulders back to straighten your back, lower yourself to the bar, and pull the slack off the barbell.","Take a breath and initiate the pull by digging your heels into the floor.","Extend your hips and knees while maintaining a neutral back position.","As the barbell travels up, extend your knees and hips.","Once the barbell goes over your knees, initiate the second stage by forcefully pressing your heels into the floor as if you were trying to do a vertical jump.","As the barbell continues moving up, drive your hips forward, fully extending your knees and hips.","Immediately shrug your shoulders and pull upward until the bar goes slightly above your waist. Exhale forcefully.","Lower the barbell slowly by first bringing your glutes back. Keep your chest out and back straight. Breathe in on the way down or before initiating the next rep."]},{"id":"E23F1F2B","name":"Climbing","primary":"cardio","secondary":[],"equipment":"none","type":"duration","thumb":"","video":"","howto":[]},{"id":"724CDE60","name":"Concentration Curl","primary":"biceps","secondary":[],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/02971201-Dumbbell-Concentration-Curl_Upper-Arms_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/02971201-Dumbbell-Concentration-Curl_Upper-Arms.mp4","howto":["Take a light dumbbell and sit on a flat gym bench.","Spread your legs wide and place the dumbbell between your legs.","Reach down and grab the weight with your right hand.","Lift the weight off the floor and place the right tricep (upper arm) against your inner leg.","Keep your chest out and body stable, take a breath, and straighten your arm.","Curl the dumbbell until your wrist is higher than your elbow. Keep your upper arm in the same position against your inner leg. Squeeze your muscle at the top as you breathe out.","Lower the dumbbell slowly and extend your elbow entirely as you breathe in.","Once finished, do the same number of reps for your other arm."]},{"id":"32C4D4A2","name":"Cross Body Hammer Curl","primary":"biceps","secondary":["forearms"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/02981101-Dumbbell-Cross-Body-Hammer-Curl_Forearms_small_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/16571201-Dumbbell-Cross-Body-Hammer-Curl-(Version-2)_Upper-Arms-FIX.mp4","howto":["Grab a pair of dumbbells and stand tall.","Have your feet in a normal stance, arms to your sides, and palms facing your body.","Bring your shoulders back, squeeze your buttocks, and take a breath.","Curl one dumbbell across your body and in front of your chest as you breathe out.","Extend your arm as you breathe in.","Curl the other dumbbell and alternate until you finish the set."]},{"id":"DCF3B31B","name":"Crunch","primary":"abdominals","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/02741201-Crunch-Floor-m_waist_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/02741201-Crunch-Floor-m_waist.mp4","howto":["Lie on the floor, bend your knees, and place your feet flat on the floor.","Bring your arms up and place your fingertips behind your head.","Engage your abs and take a breath.","Crunch by bending your torso, lifting your shoulder blades several inches off the floor. Exhale at the top.","Lower yourself slowly and breathe in."]},{"id":"EB43ADD4","name":"Crunch (Machine)","primary":"abdominals","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/05951201-Lever-Seated-Crunch-(chest-pad)_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/05951201-Lever-Seated-Crunch-(chest-pad).mp4","howto":["Select the appropriate load.","Sit down on the machine. Secure your ankles on the bottom pads, have the middle pad against your lower back, and position your chest on the top pad.","Grab the handles for support.","Take a breath and flex your abs to push the top pad forward. Exhale.","Release as you breathe in."]},{"id":"D928C232","name":"Crunch (Weighted)","primary":"abdominals","secondary":[],"equipment":"none","type":"bodyweight_reps","thumb":"assets/thumbs/66031201-Weighted-Plate-Lying-Crunch-(male)_Waist_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/66031201-Weighted-Plate-Lying-Crunch-(male)_Waist_.mp4","howto":["Grab a weight plate and lie on the floor.","Position the weight over your chest.","Bring your legs together, bend your knees, and plant your feet on the floor.","Take a breath and engage your abs to crunch your torso, lifting your shoulder blades several inches off the floor. Breathe out.","Lower your torso to the floor as you breathe in."]},{"id":"D39EC9EB","name":"Curtsy Lunge (Dumbbell)","primary":"quadriceps","secondary":["glutes","hamstrings","adductors"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/86641201-Dumbbell-Curtsey-Lunge-(male)_Thighs_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/86641201-Dumbbell-Curtsey-Lunge-(male)_Thighs_.mp4","howto":["Stand tall with a dumbbell in each hand.","Engage your abs, bring your shoulders back, and take a breath.","Bring your right leg back in a semi-circle, crossing your left leg.","Plant the ball of the foot on the floor and descend into a lunge.","Descend until your back knee almost touches the floor.","Push through your front heel to extend your leg and bring the right leg to its starting position as you exhale.","Inhale again and perform the same motion with the opposite leg.","Alternate between the left and right leg until you’re done."]},{"id":"D8F7F851","name":"Cycling","primary":"cardio","secondary":[],"equipment":"machine","type":"distance_duration","thumb":"assets/thumbs/21381201-Stationary-Bike-Run-(version-3)-(male)_Cardio_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/21381201-Stationary-Bike-Run-(version-3)-(male)_Cardio_.mp4","howto":[]},{"id":"D8911FC4","name":"Dead Bug","primary":"abdominals","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/02761201-Dead-Bug_Waist_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/02761201-Dead-Bug_Waist_.mp4","howto":["Place an exercise mat on the ground and lie down.","Lift your feet off the floor and bend your knees at a 90-degree angle.","Lift your arms over your chest.","Engage your abs to maintain a spinal curve, and take a breath.","Extend your left leg, bringing the foot an inch or two away from the floor.","Simultaneously extend your right arm back, bringing the hand close to the floor (optional). Breathe out.","Bring your arm and leg to the starting position as you breathe in.","Extend your opposite arm and leg."]},{"id":"B9380898","name":"Dead Hang","primary":"upper_back","secondary":["lats","forearms"],"equipment":"none","type":"duration","thumb":"assets/thumbs/50551201-Dead-Hang-Stretch_Stretching_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/50551201-Dead-Hang-Stretch_Stretching_.mp4","howto":["Stand underneath a pull-up bar.","Reach up and grab the bar with an even overhand grip.","Lift your feet off the floor and keep your legs together.","Relax your shoulders and midsection, supporting yourself on grip strength.","Hang for as long as possible, breathing regularly as you do."]},{"id":"99507114","name":"Deadlift (Band)","primary":"glutes","secondary":["hamstrings","quadriceps","lower_back","upper_back","lats","traps"],"equipment":"resistance_band","type":"weight_reps","thumb":"assets/thumbs/46181201-Band-Deadlift_Hips_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/46181201-Band-Deadlift_Hips.mp4","howto":["Grab an open-ended resistance band with handles on both sides.","Step over the band, keeping your feet a few inches apart.","Straighten your body, bring your shoulders back, and engage your abs.","Take a breath and hinge at the hip to lean forward.","As you move down, bend your knees to maintain a neutral spine position.","Move down as much as you can––ideally, until your hands are several inches off the floor.","Hold for a moment and extend your body by driving your hips forward.","Exhale near the top."]},{"id":"C6272009","name":"Deadlift (Barbell)","primary":"glutes","secondary":["hamstrings","quadriceps","lower_back","upper_back","lats","traps"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/00321201-Barbell-Deadlift_Hips-FIX_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00321201-Barbell-Deadlift_Hips-FIX.mp4","howto":["Stand in front of a loaded barbell.","The bar should be over mid-foot, your shins should be an inch or two from the bar, and your feet should be hip-width apart, with toes pointing slightly out.","Lean forward and grab the bar with a double overhand grip.","Bend your knees to position your shins against the bar. Simultaneously, retract your shoulders to straighten your back.","Take a breath.","Initiate the pull by digging your heels into the floor.","Lift the bar in a straight vertical line, keeping it close to your body.","As the bar passes your knees, begin to extend your legs and drive your hips forward to complete the repetition.","Begin the descent by driving your buttocks back and keeping your back neutral.","Lower the barbell in the same vertical line, exhaling near the bottom."]},{"id":"5F4E6DD3","name":"Deadlift (Dumbbell)","primary":"glutes","secondary":["hamstrings","quadriceps","lower_back","upper_back","lats","traps"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/03001201-Dumbbell-Deadlift_Hips_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/03001201-Dumbbell-Deadlift_Hips.mp4","howto":["Have your feet hip-width apart, and position a pair of dumbbells parallel to them. When seen from the top, the front weight plate of each dumbbell should align with your mid-foot.","Bend forward and grab the dumbbells while keeping your arms straight.","Bring your chest out without lifting the dumbbells to put your back into a neutral position.","Take a breath and initiate the lift by pressing through your heels as you engage your upper body and legs.","Lift the dumbbells in a straight vertical line, moving them to your sides.","Extend your hips and knees simultaneously, especially as the dumbbells pass the knees, and continue up until you’re standing. Breathe out at the top.","Begin the descent by breaking at the hips and pushing your buttocks back—lower the weights in the same straight line.","Breathe in as the weights move down or before initiating the next rep."]},{"id":"20870ED5","name":"Deadlift (Smith Machine)","primary":"glutes","secondary":["hamstrings","quadriceps","lower_back","upper_back","lats","traps"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/07521201-Smith-Deadlift_Hips-FIX_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/07521201-Smith-Deadlift_Hips-FIX_.mp4","howto":["Set the Smith machine bar in the lowest position and add weight.","Stand facing the bar with your shins a couple of inches away.","Lean forward and grab the bar with a double overhand grip.","Bend your knees slightly and bring your chest out to put your back in a neutral position.","Take a breath and pull the bar up, extending your hips near the top as you breathe out.","Pause briefly at the top and lower the bar by bringing your buttocks back.","As the bar reaches lower-thigh level, bend your knees. Maintain a neutral spine.","Breathe in on the way down or before initiating the next rep."]},{"id":"B923B230","name":"Deadlift (Trap bar)","primary":"glutes","secondary":["hamstrings","quadriceps","lower_back","upper_back","lats","traps"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/08111201-Trap-Bar-Deadlift_Thighs_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/08111201-Trap-Bar-Deadlift_Thighs.mp4","howto":["Load a trap bar and stand inside it. Your feet should be hip-width apart, with the toes pointing slightly out.","Squat down and grab the handles on both sides.","Bring your shoulders back to straighten your back.","Take a breath and initiate the pull by digging your heels into the floor.","As the bar moves up, gradually extend your hips and knees until you’re upright. Breathe out.","Lower the trap bar slowly. Bring your buttocks back first and gradually bend your knees until you’re at the starting position.","Breathe in as the bar moves down or before initiating the next rep."]},{"id":"FA5D0DE1","name":"Deadlift High Pull","primary":"full_body","secondary":[],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/11991201-Sumo-Deadlift-High-Pull_Thighs_Shoulders_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/11991201-Sumo-Deadlift-High-Pull_Thighs_Shoulders.mp4","howto":["Stand in front of a loaded barbell.","Spread your feet wide and point your toes out. Have your shins an inch or two from the bar.","Lean forward and grab the bar with a double overhand grip. Your hands should be several inches apart.","Bend your knees and bring your chest out to position yourself against the bar, and straighten your back.","Initiate the pull by digging your heels into the floor and flexing your legs.","Extend your hips and knees until you’re upright.","Immediately pull the barbell in a straight vertical line as you extend your body.","Lift the bar until it reaches chest level and breathe out.","Lower the bar and hinge at the hips as the weight reaches your upper thighs.","Lower the bar in the same straight vertical line.","Breathe in on the way down or before initiating the next rep."]},{"id":"DA0F0470","name":"Decline Bench Press (Barbell)","primary":"chest","secondary":["shoulders","triceps"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/00331201-Barbell-Decline-Bench-Press_Chest_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00331201-Barbell-Decline-Bench-Press_Chest.mp4","howto":["Lie down on the bench, positioning your forehead directly under the bar.","Grab the barbell with a double overhand grip. Your arms should be more than shoulder-width apart.","Bring your shoulders back, engage your abs, and take a breath.","Unrack the bar carefully and bring it in over your chest.","Take another breath and lower the barbell to your lower chest.","Tap your torso lightly and press the barbell straight up, exhaling near the top.","Once finished, bring the barbell over your head and rack it before relaxing your body."]},{"id":"18487FA7","name":"Decline Bench Press (Dumbbell)","primary":"chest","secondary":["shoulders","triceps"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/03011201-Dumbbell-Decline-Bench-Press_Chest_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/03011201-Dumbbell-Decline-Bench-Press_Chest.mp4","howto":["Position yourself on a decline bench and secure your feet.","Lie back and retract your shoulder blades.","Have a friend hand you the dumbbells one by one. Alternatively, hold the dumbbell and lie back carefully.","Keep your arms extended, midsection engaged, and weights over your chest.","Take a breath.","Lower the dumbbells to your sides while keeping your elbows somewhat tucked in.","Lower the weights until your elbows are at torso level.","Press the weights straight up, exhaling on the way up.","Once finished, have someone take at least one dumbbell from your hand so you can sit up."]},{"id":"FAF31231","name":"Decline Bench Press (Machine)","primary":"chest","secondary":["shoulders","triceps"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/13001201-Lever-Decline-Chest-Press_Chest-FIX__thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/13001201-Lever-Decline-Chest-Press_Chest-FIX_.mp4","howto":["Load the machine appropriately.","Set the seat height for the handles to be just below chest level when you sit down.","Sit down and grab the handles. Keep your elbows tucked at your sides.","Retract your shoulder blades, plant your feet on the floor, squeeze your abs, and inhale.","Press the handles forward and down, fully extending your elbows and exhaling. Pause briefly and squeeze your chest.","Slowly bend your arms as you breathe in."]},{"id":"FFC106CB","name":"Decline Bench Press (Smith Machine)","primary":"chest","secondary":["shoulders","triceps"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/07531201-Smith-Decline-Bench-Press_Chest_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/07531201-Smith-Decline-Bench-Press_Chest.mp4","howto":["Position a decline bench underneath a Smith machine. The bench should be positioned so that the bar is above your lower chest when you lie back.","Load the bar appropriately and have it at a height where you can reach it from a lying position.","Lie back, grab the bar with a double overhand grip, and retract your shoulders.","Unrack the bar by extending your arms.","Take a breath and lower the bar to your chest.","Press the bar to the top position and exhale.","Once finished, rack the bar carefully and stand up."]},{"id":"A351AED7","name":"Decline Chest Fly (Dumbbell)","primary":"chest","secondary":[],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/03021201-Dumbbell-Decline-Fly_Chest_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/03021201-Dumbbell-Decline-Fly_Chest.mp4","howto":["Set the bench at a decline.","Grab a pair of light dumbbells and sit on the bench, securing your feet.","Keep the dumbbells close to your chest and lie back carefully.","Extend your arms, position the dumbbells over your chest, and retract your shoulder blades. Keep your wrists neutral (hands facing one another).","Take a breath and bring your arms to your sides, stretching your chest muscles. Keep your elbows slightly bent from start to finish.","Bring your arms in, squeeze your chest, and tap the dumbbells at the top as you exhale."]},{"id":"BC10A922","name":"Decline Crunch","primary":"abdominals","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/02771201-Decline-Crunch_Waist_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/02771201-Decline-Crunch_Waist.mp4","howto":["Position yourself on a decline bench and secure your feet.","Lie back carefully, keeping your spine in contact with the back support.","Bring your hands behind your head.","Take a breath and crunch your torso by squeezing your rectus abdominis muscle. Lift your shoulder blades several inches off the bench and exhale.","Lower your torso as you breathe in."]},{"id":"B2398CD1","name":"Decline Crunch (Weighted)","primary":"abdominals","secondary":[],"equipment":"none","type":"bodyweight_reps","thumb":"assets/thumbs/21301201-Weighted-decline-crunch_Waist_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/21301201-Weighted-decline-crunch_Waist.mp4","howto":["Grab a weight plate, position yourself on a decline bench, and secure your legs.","Lie back carefully while keeping the plate against your chest.","Take a breath and crunch your torso by engaging your abs.","Lift your shoulder blades several inches off the floor and exhale.","Hold for a moment and lower your torso slowly as you breathe in."]},{"id":"C43825EA","name":"Decline Push Up","primary":"chest","secondary":["shoulders","triceps"],"equipment":"other","type":"reps_only","thumb":"assets/thumbs/02791201-Decline-Push-Up_Chest_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/02791201-Decline-Push-Up_Chest.mp4","howto":["Get down on all fours and position your feet on a gym bench, plyo box, or another sturdy object.","Extend your body into a push-up position with your hands wider than shoulder-width apart and rotated slightly out.","Have your arms straight and shoulder blades retracted.","Engage your abs and take a breath.","Lower your body by bending your elbows.","Move down until your face is close to the floor.","Press yourself back by extending your arms. Exhale near the top."]},{"id":"6575F52D","name":"Diamond Push Up","primary":"triceps","secondary":["chest","shoulders"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/02831101-Diamond-Push-up_Upper-Arms_small_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/02831201-Diamond-Push-up_Upper-Arms.mp4","howto":["Get down on all fours and bring your hands together. Your thumbs and index fingers should be in contact or just a couple of inches apart.","Extend your body into a push-up position, bringing your shoulders, hips, and knees into alignment.","Bring your shoulders back, squeeze your glutes, and take a breath.","Lower yourself by bending your elbows.","Descend as low as possible and hold the bottom for a moment.","Press yourself back to the top, exhaling as you straighten your arms."]},{"id":"7DA843A3","name":"Downward Dog","primary":"full_body","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/34691201-Downward-Facing-Dog_Stretching_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/34691201-Downward-Facing-Dog_Stretching_.mp4","howto":["Get down on all fours with your knees underneath your hips. Have your shoulders, elbows, and wrists in vertical alignment.","Take a breath and push your buttocks back as you extend your arms.","Transition into the high position by elevating your glutes and straightening your legs as you maintain a rigid upper body.","Hold the position and release by first bending your knees and then bringing your torso forward."]},{"id":"D950429E","name":"Drag Curl","primary":"biceps","secondary":[],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/00381201-Barbell-Drag-Curl_Upper-Arms_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00381201-Barbell-Drag-Curl_Upper-Arms.mp4","howto":["Grab a loaded straight bar with your palms facing forward and stand tall.","Your hands should be just outside your thighs.","Bring your shoulders back and take a breath.","Curl the bar by bending your elbows, dragging the weight against your body.","Lift the bar as high as possible, squeezing your biceps at the top and exhaling.","Lower the bar in the same straight line as you breathe in."]},{"id":"AFC29472","name":"Dragon Flag","primary":"abdominals","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/40581201-Leg-Raise-Dragon-Flag_Waist_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/40581201-Leg-Raise-Dragon-Flag_Waist_.mp4","howto":["Lie on a flat gym bench and grab the back support with both hands.","Extend your body and engage your abs.","Take a breath and lift your body off the bench using your midsection musculature.","Elevate your body as high as possible and hold for a moment as you exhale.","Lower your body slowly and breathe in."]},{"id":"B7192800","name":"Dragonfly","primary":"abdominals","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/40581201-Leg-Raise-Dragon-Flag_Waist_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/40581201-Leg-Raise-Dragon-Flag_Waist_.mp4","howto":["Lie on a flat gym bench and grab the back support with both hands.","Extend your body and engage your abs.","Take a breath and lift your body off the bench by engaging your midsection musculature.","Elevate your body as high as possible and hold for a moment before exhaling.","Lower your body slowly and breathe in."]},{"id":"F1E57334","name":"Dumbbell Row","primary":"lats","secondary":["upper_back","biceps","forearms"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/02921201-Dumbbell-Bent-over-Row_Back_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/02921201-Dumbbell-Bent-over-Row_Back.mp4","howto":["Grab a dumbbell.","Place your right knee and right hand on a flat gym bench. Keep your left leg and arm straight with the dumbbell in your hand.","Bring your shoulders back and engage your abs.","Row the dumbbell until your elbow is at torso level and squeeze for a moment as you exhale.","Lower the weight while keeping your shoulders in position. Breathe in on the way down.","Once finished, grab the dumbbell with the opposite hand, position your left hand and knee on the bench, and repeat."]},{"id":"F3717B0E","name":"Dumbbell Snatch","primary":"full_body","secondary":[],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/38881101-Dumbbell-One-Arm-Snatch_small_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/38881201-Dumbbell-One-Arm-Snatch_Weightlifting_.mp4","howto":["Place a dumbbell on the floor.","Lean forward and grab the dumbbell with one hand.","Bring your shoulders back, engage your abs, and take a breath.","Thrust the dumbbell up in one powerful swing.","Simultaneously dip slightly (bend your knees) to receive the weight overhead.","Extend your arm and straighten your legs as you exhale.","Lower the dumbbell slowly, breathing in on the way down.","Repeat.","Grab the dumbbell with the opposite hand and repeat for the same number of reps."]},{"id":"F72FA239","name":"Dumbbell Squeeze Press","primary":"chest","secondary":["shoulders","triceps"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/36811201-Dumbbell-Squeeze-Bench-Press_Chest-FIX__thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/36811201-Dumbbell-Squeeze-Bench-Press_Chest-FIX_.mp4","howto":["Grab a pair of dumbbells, sit on a flat gym bench, and place the weights on top of your thighs.","Lie back slowly while keeping your arms bent and dumbbells against your body.","Extend your arms, position the dumbbells over your chest, have your wrists neutral (palms facing one another), and squeeze the weights together.","Bring your shoulders back and inhale.","Lower the dumbbells to your chest, hold for a moment, and press them back to the top as you breathe out."]},{"id":"BF6ECE89","name":"Dumbbell Step Up","primary":"quadriceps","secondary":["glutes","hamstrings"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/04311101-Dumbbell-Step-up_Hips_small_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/58261201-Dumbbell-Step-up-(VERSION-2)-(male)_Thighs_.mp4","howto":["Grab a pair of dumbbells and stand in front of a flat gym bench or plyo box.","Bring your shoulders back and take a breath.","Extend one leg forward and plant the foot on the elevated object.","Press through your front foot and step up, positioning yourself on the bench or box as you exhale.","Step back to the starting position and breathe in.","Extend the opposite leg forward.","Keep alternating between left and right."]},{"id":"A01BE509","name":"Elbow to Knee","primary":"abdominals","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/23121201-Lying-Elbow-to-Knee_Waist_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/23121201-Lying-Elbow-to-Knee_Waist.mp4","howto":["Lie on the floor, bend your knees, rotate your right leg, and position the outer portion of your ankle against your left thigh.","Bring your left hand behind your head.","Take a breath and engage your abs.","Crunch and rotate your torso, bringing your left elbow to your right knee. Exhale.","Lower your torso and breathe in.","Once finished, place your left ankle against your right thigh and position your right hand behind your head. Repeat for the same number of reps."]},{"id":"3303376C","name":"Elliptical Trainer","primary":"cardio","secondary":[],"equipment":"machine","type":"distance_duration","thumb":"assets/thumbs/21921201-Elliptical-Machine-Walk_Cardio_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/21921201-Elliptical-Machine-Walk_Cardio.mp4","howto":["Select the correct resistance and position yourself on the elliptical machine.","Bring your shoulders back, engage your abs, and take a breath.","Initiate the movement by driving your right leg forward as you pull the right handle back.","Maintain a steady tempo and move your arms and legs alternatingly."]},{"id":"01A35BF9","name":"EZ Bar Biceps Curl","primary":"biceps","secondary":[],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/04471201-EZ-Barbell-Curl_Upper-Arms_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/04471201-EZ-Barbell-Curl_Upper-Arms.mp4","howto":["Load an EZ (curved) bar and grab it with an even underhand grip (palms facing forward).","Stand tall with your feet in a comfortable stance, knees bent slightly, and shoulders retracted.","Take a breath and lift the bar by engaging your biceps.","Move the weight up until your wrists are slightly higher than your elbows and breathe out.","Pause for a moment and extend your arms as you breathe in."]},{"id":"BE640BA0","name":"Face Pull","primary":"shoulders","secondary":["biceps"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/77441201-Cable-Standing-Supinated-Face-Pull-(with-rope)_Sho_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/77441201-Cable-Standing-Supinated-Face-Pull-(with-rope)_Sho.mp4","howto":["Select a light load, set the pulley to a high position, and attach a rope.","Grab the rope with your thumbs facing the ceiling.","Take a step back to lift the weight off its stack, bring your shoulders back, and stagger your stance for extra support.","Take a breath and pull the rope to your face, splitting it by bringing your arms to your sides. Breathe out.","Extend your arms as you breathe in."]},{"id":"50C613D0","name":"Farmers Walk","primary":"full_body","secondary":[],"equipment":"other","type":"short_distance_weight","thumb":"assets/thumbs/21331201-Farmers-walk_Cardio_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/21331201-Farmers-walk_Cardio.mp4","howto":["Grab a pair of heavy dumbbells, kettlebells, or weight plates.","Stand tall with your shoulders back, your abs tight, and your gaze directed a few feet forward.","Walk forward slowly, breathing steadily as you do.","Go for as long as possible and bend your knees to set the weights on the floor."]},{"id":"867AC3B6","name":"Feet Up Bench Press (Barbell)","primary":"chest","secondary":["shoulders","triceps"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/62701201-Barbell-Larsen-Press-(male)_Chest_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/62701201-Barbell-Larsen-Press-(male)_Chest_.mp4","howto":["Set the bar at a height where you can unrack it without fully extending your arms.","Add the appropriate weight and lie on the bench with your forehead directly underneath the bar.","Grab the bar evenly with your hands slightly wider than your shoulders.","Bring your shoulder blades back and into the bench, and extend your legs. Depending on your height, the back of your thighs, knees, or calves should rest against the edge of the bench.","Engage your abs, unrack the bar, and bring it over your mid-chest.","Breathe in and lower the barbell to your chest.","Pause for a moment and press the bar to the top as you exhale.","Breathe in and repeat for the recommended number of reps."]},{"id":"2AF8B552","name":"Fire Hydrants","primary":"glutes","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/30351201-Bent-Leg-Side-Kick-(kneeling)-(male)_Hips-FIX_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/30351201-Bent-Leg-Side-Kick-(kneeling)-(male)_Hips-FIX_.mp4","howto":["Get down on your hands and knees. Have your knees below your hips and your shoulders, elbows, and wrists in line.","Plant your hands flat on the floor and engage your abs to put your back in a neutral position.","Flex your right leg without extending the knee.","Take a breath and raise your right leg, bringing it to your side. Lift your leg as high as your mobility and strength allow, exhaling at the top. Don’t let your torso rotate with your knee; keep your hips squared.","Bring your right leg back to the starting position as you breathe in.","Once you’re done, do the same number of reps with the other leg."]},{"id":"D53F2886","name":"Floor Press (Barbell)","primary":"chest","secondary":["shoulders","triceps"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/37241201-Barbell-Floor-Chest-Press_Chest_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/37241201-Barbell-Floor-Chest-Press_Chest_.mp4","howto":["Set the barbell on a squat rack at roughly one foot above the floor.","Set the squat rack safety bars at torso level (while lying on the floor).","Lie flat on the floor with the bar above your forehead.","Reach up and grab the bar with an even overhand grip.","Retract your shoulder blades, squeeze your abs, and take a breath.","Unrack the bar by locking out your elbows.","Position the bar over your chest and take another breath.","Lower the bar until your elbows come in contact with the floor.","Press the bar up, exhaling near the top."]},{"id":"756EE329","name":"Floor Press (Dumbbell)","primary":"chest","secondary":["shoulders","triceps"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/36681201-Dumbbell-Lying-on-Floor-Chest-Press_Chest_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/36681201-Dumbbell-Lying-on-Floor-Chest-Press_Chest.mp4","howto":["Grab a pair of dumbbells and sit on the floor.","Bend your arms to bring the weights close to your torso, and lie back.","Keep your knees bent and your feet flat on the floor.","Position the dumbbells to your sides, engage your abs, and retract your shoulder blades.","Take a breath and press the dumbbells up and in, breathing out at the top.","Slowly lower the dumbbells to your sides as you breathe in."]},{"id":"A57D38D5","name":"Floor Triceps Dip","primary":"triceps","secondary":["shoulders"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/08151201-Triceps-Dips-Floor_Upper-Arms_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/08151201-Triceps-Dips-Floor_Upper-Arms.mp4","howto":["Sit down, bend your knees, and place your feet flat on the floor.","Lean your torso back and place your hands flat on the floor and behind your body.","Engage your abs and take a breath.","Press through your palms to extend your arms, lifting your buttocks several inches off the floor. Exhale.","Slowly bend your arms, bringing your butt back to the floor as you breathe in."]},{"id":"2FA77B28","name":"Flutter Kicks","primary":"abdominals","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/12441201-Flutter-Kicks-(version-3)_Hips_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/12441201-Flutter-Kicks-(version-3)_Hips.mp4","howto":["Lie on the floor with your arms to your sides and hands flat on the floor.","Engage your abs and raise your feet a couple of inches off the ground.","Breathe in and begin moving your feet up and down alternatingly, several inches in each direction.","Maintain a steady exercise tempo and breathing."]},{"id":"207DC636","name":"Frog Jumps","primary":"quadriceps","secondary":["glutes","hamstrings","calves"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/101651201-Frog-Jump_Plyometrics_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/101651201-Frog-Jump_Plyometrics_.mp4","howto":["Stand tall with your feet wider than your hips and toes pointing slightly out.","Engage your abs and extend your arms with your hands in front of your hips.","Take a breath and descend into a squat, keeping your heels in contact with the floor.","Descend until your hands brush the floor.","Immediately press through your heels as powerfully as possible, propelling yourself in the air and exhaling at the top. Keep your arms pointing to the floor.","Take another breath as you land, descend into the next repetition, and repeat."]},{"id":"F6948F17","name":"Frog Pumps (Dumbbell)","primary":"glutes","secondary":["hamstrings"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/61601201-Dumbbell-Frog-Hip-Thrust-(male)_Hips_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/61601201-Dumbbell-Frog-Hip-Thrust-(male)_Hips_.mp4","howto":["Grab a dumbbell and lie on the floor.","Carefully place the weight on your groin and hold it with both hands.","Bring your feet together and have your knees pointed out.","Engage your abs and take a breath.","Press through your feet to extend your hips toward the ceiling, squeezing your glutes at the top and breathing out.","Slowly lower your buttocks to the floor as you breathe in."]},{"id":"0E608350","name":"Front Lever Hold","primary":"full_body","secondary":[],"equipment":"none","type":"duration","thumb":"assets/thumbs/72511201-Hanging-Front-Lever-Raise-(male)_Waist_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/72511201-Hanging-Front-Lever-Raise-(male)_Waist_.mp4","howto":["Reach up and grab a bar with an even, overhand grip. Your hands should be shoulder-width apart and elbows extended.","Bring your feet together and extend your knees by flexing your quadriceps.","Maintain a neutral spine by flexing your midsection muscles. Avoid arching your lower back during any part of the front lever.","Flex your entire upper body and take a breath.","With your body rigid, initiate the front lever by leaning back as you engage your lats and midsection.","Raise your entire body horizontally by engaging your back, shoulders, and midsection musculature.","Lift your body until you reach a horizontal position and hold, breathing steadily.","Slowly move back to the starting position as you relax your body."]},{"id":"30F03BF0","name":"Front Lever Raise","primary":"full_body","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/72511201-Hanging-Front-Lever-Raise-(male)_Waist_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/72511201-Hanging-Front-Lever-Raise-(male)_Waist_.mp4","howto":["Reach up and grab a bar with an even, overhand grip. Your hands should be shoulder-width apart, and your elbows should be extended.","Bring your feet together and extend your knees by flexing your quadriceps.","Maintain a neutral spine by flexing your midsection muscles. Don't arch your lower back during any part of the front lever.","Flex your entire upper body and take a breath.","With your body rigid, initiate the front lever by leaning back as you engage your lats and midsection.","Raise your entire body in a horizontal position by engaging your back, shoulders, and midsection musculature.","Lift your body until you reach a horizontal position, and hold for a moment as you exhale.","Slowly move back to the starting position as you breathe in."]},{"id":"47B036EF","name":"Front Raise (Band)","primary":"shoulders","secondary":[],"equipment":"resistance_band","type":"weight_reps","thumb":"assets/thumbs/09781201-Band-front-raise_Shoulders_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/09781201-Band-front-raise_Shoulders_.mp4","howto":["Take an open-ended resistance band with handles on both sides.","Step over the middle of the band, grab both ends, and position your arms to your sides.","Bring your shoulders back, engage your abs, and take a breath.","Raise your arms in front of your body in one smooth motion, exhaling at the top.","Slowly lower your arms to your sides as you breathe in."]},{"id":"BD86EFD5","name":"Front Raise (Barbell)","primary":"shoulders","secondary":[],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/00411101-Barbell-Front-Raise_Shoulders_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00411101-Barbell-Front-Raise_Shoulders.mp4","howto":["Grab the bar with a double overhand grip (palms facing back). Your hands should be shoulder-width apart.","Stand tall, bring your shoulders back, and squeeze your abs.","Take a breath and lift the barbell in front of your body, keeping your elbows extended. Lift until the weight is at shoulder level and exhale.","Lower the barbell to the starting position, breathing in on the way down."]},{"id":"DBB91A3C","name":"Front Raise (Cable)","primary":"shoulders","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/01621201-Cable-Front-Raise_Shoulders_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/01621201-Cable-Front-Raise_Shoulders.mp4","howto":["Set the pulley in the lowest position and attach a straight bar.","Face away from the cable machine with the bar between your legs.","Grab the straight bar with an overhand grip (palms facing back), and have the rope between your legs. Your arms should be straight.","Bring your shoulders back, engage your upper body, and bend your knees slightly.","Inhale and raise the bar away from your body in one fluid motion.","Lift until the bar is at shoulder level and breathe out. Keep your arms straight.","Lower your arms to the starting position as you breathe in."]},{"id":"8293E554","name":"Front Raise (Dumbbell)","primary":"shoulders","secondary":[],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/03101201-Dumbbell-Front-Raise_Shoulders_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/03101201-Dumbbell-Front-Raise_Shoulders.mp4","howto":["Grab a pair of dumbbells and stand tall.","Position the dumbbells in front of your thighs with your palms facing back.","Bring your shoulders back and inhale.","Raise both dumbbells until they are at shoulder level. Exhale at the top.","Lower the dumbbells to your upper thighs as you breathe in."]},{"id":"796E8E2C","name":"Front Raise (Suspension)","primary":"shoulders","secondary":[],"equipment":"suspension","type":"reps_only","thumb":"assets/thumbs/108051201-Suspender-Front-Raise-(male)_Shoulders_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/108051201-Suspender-Front-Raise-(male)_Shoulders_.mp4","howto":["Grab the handles of a suspension trainer with your arms straight and in front of your chest.","Lean your body back several degrees, have your feet together, and engage your abs.","Take a breath and raise your arms overhead, pulling your body into a vertical position. Exhale.","Slowly lower your arms in front of your chest as you lean back and breathe in."]},{"id":"5046D0A9","name":"Front Squat","primary":"quadriceps","secondary":["hamstrings","glutes"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/00421201-Barbell-Front-Squat_Hips_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00421201-Barbell-Front-Squat_Hips.mp4","howto":["Position the barbell at collarbone height.","Dip by bending your knees slightly, pressing your upper chest against the bar, and extending your arms forward.","Bend your right elbow and bring your forearm over the bar with the hand resting atop your collarbone.","Bend your left elbow and position your left hand on top of your collarbone, right over the bar.","Position the barbell on your shoulders, bring your chest out, take a breath, and extend your knees to unrack the bar.","Take two steps back to clear enough room.","Inhale and descend by bending your knees while keeping your torso upright.","Go down as comfortably as possible––ideally, until your thighs are parallel to the floor.","Push through your heels to squat up and exhale near the top."]},{"id":"1283BBA6","name":"Full Squat","primary":"quadriceps","secondary":["hamstrings","glutes"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/00431201-Barbell-Full-Squat_Thighs_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00431201-Barbell-Full-Squat_Thighs.mp4","howto":["Position a barbell behind your neck and place it on your upper back muscles.","Grab the bar evenly for support.","Bring your shoulders back and position your feet in a comfortable stance with your toes pointing slightly out.","Engage your abs and take a breath.","Squat down and keep your heels in contact with the floor.","Descend as much as your mobility allows, hold for a moment, and press through your heels to move up.","Exhale near the top."]},{"id":"CDA23948","name":"Glute Bridge","primary":"glutes","secondary":["hamstrings","quadriceps"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/06681201-Rear-Decline-Bridge_Waist-FIX_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/06681201-Rear-Decline-Bridge_Waist-FIX_.mp4","howto":["Lie flat on the ground.","Bend your knees and plant your feet on the floor.","Position your arms to your sides for balance.","Take a breath and press through your heels to extend your hips toward the ceiling.","Squeeze your glutes at the top and hold the position for a moment as you exhale.","Lower your buttocks to the floor as you breathe in."]},{"id":"49C922A1","name":"Glute Bridge (Barbell)","primary":"glutes","secondary":["hamstrings","adductors","quadriceps"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/29641201-Barbell-Glute-Bridge-(hands-on-bar)_Hips_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/29641201-Barbell-Glute-Bridge-(hands-on-bar)_Hips_.mp4","howto":["Sit on the floor, roll a loaded barbell over your hips, and lie back.","Bring your shoulders back, bend your knees, and plant your feet flat on the ground, having them roughly hip-width apart.","Grab the bar with both hands and push your hips against it.","Breathe in and engage your abs.","Push through your heels and engage your glutes to drive your hips toward the ceiling as you exhale.","Pause briefly at the top and slowly lower your hips to the starting position as you breathe in. Grip the bar to keep it in position.","Repeat."]},{"id":"68B83EE0","name":"Glute Ham Raise","primary":"hamstrings","secondary":["glutes"],"equipment":"machine","type":"reps_only","thumb":"assets/thumbs/44561201-Glute-Ham-Raise-(VERSION-2)_Thighs-FIX_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/44561201-Glute-Ham-Raise-(VERSION-2)_Thighs-FIX_.mp4","howto":["Set yourself up on a glute ham raise machine. The ankle pad should be against your Achilles heel, and your knees should be on the platform supporting your hips. Push the balls of your feet against the foot platform if your machine has one.","With your torso upright, knees bent, and ankles secure, cross your arms in front of your chest, retract your shoulder blades, and inhale.","Slowly extend your legs and bring your torso forward and down while keeping your back and hips rigid.","Descend as much as possible––ideally, until your knees are almost entirely straight.","Engage your posterior chain to bend your knees and raise your torso to the starting position. Exhale near the top."]},{"id":"CBA02382","name":"Glute Kickback (Machine)","primary":"glutes","secondary":["hamstrings"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/10371201-Lever-Standing-Rear-Kick_Hips_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/10371201-Lever-Standing-Rear-Kick_Hips.mp4","howto":["Select the appropriate load.","Position your right side to the machine and grab the horizontal support bar.","Place the back of your right thigh against the pad, just above the crease of the knee.","Bring your shoulders back, engage your abs, and extend your leg back in one fluid motion as you exhale.","Slowly bring your leg to the starting position as you breathe in.","Once finished, rotate your body 180 degrees, and do the same number of reps for your left leg."]},{"id":"987234AB","name":"Glute Kickback on Floor","primary":"glutes","secondary":["hamstrings"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/30341201-Bent-Leg-Kickback-(kneeling)-(male)_Hips-FIX_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/30341201-Bent-Leg-Kickback-(kneeling)-(male)_Hips-FIX_.mp4","howto":["Get down on all fours with your hands flat and knees supporting your lower body.","Your knees should be underneath your hips, and your wrists, elbows, and shoulders should be aligned.","Engage your abs and take a breath.","Kick your right leg back and up, squeezing your glutes at the top and exhale. Keep your knee bent.","Slowly bring the leg to the starting position and breathe in.","Once finished training one side, do the same number of reps with your other leg."]},{"id":"3D0C7C75","name":"Goblet Squat","primary":"quadriceps","secondary":["hamstrings","glutes"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/17601201-Dumbbell-Goblet-Squat_Thighs-FIX_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/17601201-Dumbbell-Goblet-Squat_Thighs-FIX_.mp4","howto":["Grab a dumbbell and raise it in front of your torso with both arms while keeping it vertical (with one side up).","Position your hands to the sides of it with your palms placed firmly against the top weight plate.","Straighten your back, engage your abs, and inhale.","Descend into a squat while keeping your torso upright.","Squat as low as you comfortably can – ideally until your thighs are parallel with the floor.","Push through your heels to raise yourself back to the starting position and exhale near the top of the repetition."]},{"id":"4180C405","name":"Good Morning (Barbell)","primary":"hamstrings","secondary":["glutes","lower_back","upper_back","lats"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/00441201-Barbell-Good-Morning_Thighs_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00441201-Barbell-Good-Morning_Thighs.mp4","howto":["Set the bar up at around armpit height, and grip it evenly, slightly outside shoulder-width level.","Tuck yourself under the bar and position it on your lower traps, around the level of your rear deltoids.","Extend your upper back and press the bar against it with both hands. Keep your wrist straight and don't rest the bar on your hands.","With your feet hip-width apart and firmly planted on the ground, push your hips forward and unrack the bar. Take a few steps back to clear enough space for the lift.","With the bar firmly pressed against your upper back and your feet planted into the ground, take a breath and push your hips straight back.","As you lean forward, keep your back in a neutral position and think about pushing your butt back.","Lean your torso forward as much as possible while keeping your back straight. You should feel an intense stretch in your posterior chain muscles. Allow for a slight bend in your knees at the bottom.","Initiate the upward movement by pushing your hips forward and stand tall. Exhale at the top."]},{"id":"05487216","name":"Gorilla Row (Kettlebell)","primary":"upper_back","secondary":["lats","biceps","forearms"],"equipment":"kettlebell","type":"weight_reps","thumb":"assets/thumbs/72301201-Kettlebell-Gorilla-Row-(male)_Back__thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/72301201-Kettlebell-Gorilla-Row-(male)_Back_.mp4","howto":["Place two kettlebells of equal weight on the floor and stand before them.","Lean forward and grab the two kettlebell handles.","Bend your knees to some degree and retract your shoulder blades to straighten your back.","Take a deep breath, engage your abs, and row one kettlebell until your elbow is at torso level. Exhale.","Lower the weight to the floor as you breathe in.","Immediately row the other kettlebell and breathe out.","Alternate between left and right until you’re done."]},{"id":"AC5A4C58","name":"Hack Squat","primary":"quadriceps","secondary":["hamstrings","glutes"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/00461201-Barbell-Hack-Squat_Hips_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00461201-Barbell-Hack-Squat_Hips.mp4","howto":["Place a barbell on the floor and stand in front of it. Your calves should almost be in contact with it.","Bring your chest out and descend into a squat.","Grab the barbell with your palms facing back, and keep your shoulders retracted.","While holding the barbell firmly, take a deep breath and push through your heels to move up.","Drag the barbell against your legs and buttocks. Exhale near the top.","With your shoulders back and gaze directed forward, bend at the knees and hips to descend."]},{"id":"1E42FD5F","name":"Hack Squat (Machine)","primary":"quadriceps","secondary":["glutes","hamstrings"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/07431201-Sled-Hack-Squat_Hips_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/07431201-Sled-Hack-Squat_Hips.mp4","howto":["Add weight to the machine.","Position yourself inside the machine with your shoulders against the pad.","Have your feet in a comfortable squatting stance on the platform below.","Bring your shoulders back and engage your abs.","Extend your knees to unrack the weight and remove the safety latch.","Inhale and descend by bending your knees.","Move down until your knees form a 90-degree angle.","Press through your heels and straighten your legs, exhaling near the top.","Once finished, put the safety on, rack the weight, and relax your body."]},{"id":"1D4B3D6B","name":"Hammer Curl (Band)","primary":"biceps","secondary":["forearms"],"equipment":"resistance_band","type":"weight_reps","thumb":"assets/thumbs/46191201-Band-Standing-Hammer-Curl_Upper-Arms_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/46191201-Band-Standing-Hammer-Curl_Upper-Arms.mp4","howto":["Take a looped or open-ended resistance band, step over the middle, and grab both ends.","Stand tall with your arms straight and your wrists neutral (facing your body).","Take a breath and slowly bend your arms.","Curl the band until your wrists are slightly higher than your elbows, and breathe out. Keep your elbows to your sides.","Fully extend your arms as you breathe in."]},{"id":"36E8F14E","name":"Hammer Curl (Cable)","primary":"biceps","secondary":["forearms"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/01651201-Cable-Hammer-Curl-(with-rope)-(male)_Forearms_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/01651201-Cable-Hammer-Curl-(with-rope)-(male)_Forearms_.mp4","howto":["Select the appropriate weight and set the pulley to the lowest position.","Attach a rope to the pulley.","Lean forward and grab both ends of the rope attachment. Keep your hands neutral (palms facing one another).","Stand up and step back to lift the weight off its stack, engage your abs, and retract your shoulder blades.","Take a breath and lift the rope to your chest by bending your arms. Keep your elbows at your sides.","Bend your arms until your wrists are slightly higher than your elbows, and breathe out.","Slowly extend your arms and breathe in."]},{"id":"7E3BC8B6","name":"Hammer Curl (Dumbbell)","primary":"biceps","secondary":["forearms"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/03121201-Dumbbell-Hammer-Curl-(version-2)_Upper-Arms_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/03121201-Dumbbell-Hammer-Curl-(version-2)_Upper-Arms.mp4","howto":["Grab a pair of dumbbells and stand tall.","Position your arms to your sides with your wrists neutral (palms facing your body).","Bring your shoulders back and take a breath.","Curl both dumbbells simultaneously, lifting them until your wrists are slightly higher than your elbows. Exhale.","Extend your arms fully as you breathe in."]},{"id":"BE3615CF","name":"Handstand Hold","primary":"full_body","secondary":[],"equipment":"none","type":"duration","thumb":"assets/thumbs/33021101-Handstand_Upper-arms_small_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/33021201-Handstand_Upper-arms_.mp4","howto":["Stand tall with your arms overhead and core engaged.","Take a breath and lean forward, planting your hands on the floor.","Use the momentum you generate to extend your legs to the ceiling.","Hold the handstand position."]},{"id":"90B04F96","name":"Handstand Push Up","primary":"shoulders","secondary":["chest","triceps"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/04711201-Handstand-Push-Up_Shoulders_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/04711201-Handstand-Push-Up_Shoulders_.mp4","howto":["Assume a handstand position by placing your hands flat on the floor and lifting your legs to the ceiling. You can support yourself against a wall for extra balance.","Once in position, take a breath and lower yourself by bending your elbows.","Move down slowly and stop when your head is a couple of inches from the floor.","Press by extending your elbows and exhale."]},{"id":"BD4E7E53","name":"Hang Clean","primary":"full_body","secondary":[],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/15201201-Barbell-Hang-Clean_Weightlifts-FIX_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/15201201-Barbell-Hang-Clean_Weightlifts-FIX_.mp4","howto":["Stand tall and hold a barbell with an overhand grip (palms facing back). Your hands should be more than shoulder-width apart.","Bring your shoulders back, engage your abs, and position your feet comfortably.","Take a breath and thrust the barbell forward and up.","Immediately sink into a squat and receive the barbell in a front rack position. Your elbows should be bent, and your fingertips should support the barbell as it lies on your shoulders.","Press through your heels and extend your knees to stand up, exhaling at the top.","Grab hold of the barbell and carefully lower it to the starting position as you breathe in."]},{"id":"F4E77594","name":"Hang Snatch","primary":"full_body","secondary":[],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/15221101-Barbell-Hang-Snatch_Weightlifts_small_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/15231201-Barbell-Hang-Snatch-Below-the-Knees_Weightlifts_.mp4","howto":["Grab a loaded barbell with an overhand grip (palms facing back).","Stand tall and straighten your arms.","Engage your abs and take a breath.","Hinge at the hips until the barbell is just above knee level.","Drive your hips forward as you thrust the weight overhead, bending your knees and sinking into a squat.","Catch the bar overhead with your elbows extended.","Push through your heels and squat up while keeping your arms straight. Exhale at the top."]},{"id":"08590920","name":"Hanging Knee Raise","primary":"abdominals","secondary":["forearms"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/98191201-Hanging-Knee-Raise-(male)_Waist_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/98191201-Hanging-Knee-Raise-(male)_Waist_.mp4","howto":["Reach up and grab a pull-up bar with an overhand grip (palms facing forward). Your hands should be shoulder-width apart.","Bring your legs together, engage your abs, and retract your shoulders.","Take a breath and lift your legs, bending your knees.","Raise your legs as high as possible in one fluid motion and exhale.","Slowly extend your legs as you breathe in. Don’t let your lower back arch."]},{"id":"F8356514","name":"Hanging Leg Raise","primary":"abdominals","secondary":["forearms"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/04751201-Hanging-Straight-Leg-Raise_Hips-FIX_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/04751201-Hanging-Straight-Leg-Raise_Hips-FIX_.mp4","howto":["Reach up and grab a pull-up bar with an even overhand grip (palms facing forward).","Take a breath, engage your abs, and lift your feet off the floor, suspending yourself in the air.","Raise your legs while keeping them straight.","Pause briefly at the top as you exhale.","Slowly lower your legs while keeping your body stable as you breathe in."]},{"id":"567FB505","name":"Heel Taps","primary":"abdominals","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/00061101-Alternate-Heel-Touchers_waist-FIX_small_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00061201-Alternate-Heel-Touchers_waist.mp4","howto":["Lie on the floor, bend your knees, bring your feet together, and plant them flat.","Position your arms to your sides and take a breath.","Crunch your torso to the left, tapping your left ankle with your hand.","Extend your upper body, take another breath, and crunch to the right.","Alternate between left and right until you’re done."]},{"id":"BE89C631","name":"Hex Press (Dumbbell)","primary":"chest","secondary":["shoulders","triceps"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/36811201-Dumbbell-Squeeze-Bench-Press_Chest-FIX__thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/36811201-Dumbbell-Squeeze-Bench-Press_Chest-FIX_.mp4","howto":["Grab a pair of dumbbells, preferably hexagonal ones.","Sit on a flat gym bench and place the weights on your thighs.","Lie back while keeping the weights close to your torso.","As you lie down, extend your arms and squeeze the dumbbells together.","Retract your shoulder blades, take a deep breath, and squeeze your abs.","Lower the dumbbells to your upper stomach and pause briefly.","Press the weights to extend your arms and exhale."]},{"id":"C9CCB878","name":"High Knee Skips","primary":"full_body","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/30911201-High-Knee-Skips-(male)_Cardio-FIX_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/30911201-High-Knee-Skips-(male)_Cardio-FIX_.mp4","howto":["Stand tall with your arms to your sides, legs straight, and feet a few inches apart.","Bring your shoulders back, engage your abs, and inhale.","Raise your left knee toward your chest as you bring your left arm back. Simultaneously bend your right arm, positioning your hand to the side of your face.","Lower your left foot to the floor as you exhale, and bring your right arm to your side.","Inhale and immediately bring the opposite knee to your chest, bending your left arm.","Alternate and maintain a steady tempo from start to finish."]},{"id":"150E076B","name":"High Knees","primary":"full_body","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/30911201-High-Knee-Skips-(male)_Cardio-FIX_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/30911201-High-Knee-Skips-(male)_Cardio-FIX_.mp4","howto":["Stand tall with your shoulders back, abs engaged, and gaze forward.","Take a breath and raise your right knee to your chest while simultaneously bringing your right arm behind your body.","Lower your knee and immediately lift the opposite one, bringing your left arm behind your body.","Raise your knees to your chest alternatingly, maintaining a steady tempo as you do."]},{"id":"023947AB","name":"HIIT","primary":"cardio","secondary":[],"equipment":"none","type":"duration","thumb":"assets/thumbs/51681201-Double-Under-Jump-Rope-(male)_Cardio_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/51681201-Double-Under-Jump-Rope-(male)_Cardio_.mp4","howto":[]},{"id":"1C34A172","name":"Hiking","primary":"cardio","secondary":[],"equipment":"none","type":"distance_duration","thumb":"assets/thumbs/22581201-Walking_Cardio-FIX_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/22581201-Walking_Cardio-FIX_.mp4","howto":[]},{"id":"C469EA70","name":"Hip Abduction (Cable)","primary":"abductors","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/112661201-Cable-Standing-Hip-Abduction-(VERSION-3)_Hips_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/112661201-Cable-Standing-Hip-Abduction-(VERSION-3)_Hips_.mp4","howto":["Set the cable pulley to the lowest position, attach an ankle cuff, and select the weight.","Wrap the cuff around your right ankle and stand up with your left shoulder pointing toward the machine.","Bring your shoulders back and step slightly away from the machine to unrack the weight. You can hold onto the machine for balance.","Engage your abs and slightly raise your right foot off the ground.","Breathe in and raise your right leg to the side in one smooth motion, exhaling at the top of the rep.","Slowly bring your leg in as you breathe in and repeat.","Once finished, wrap the cuff around your left ankle, stand up with your right shoulder pointing toward the pulley, and repeat for the same number of reps."]},{"id":"F4B4C6EE","name":"Hip Abduction (Machine)","primary":"abductors","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/05971201-Lever-Seated-Hip-Abduction_Hips_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/05971201-Lever-Seated-Hip-Abduction_Hips.mp4","howto":["Select the appropriate load and sit down.","Bring your shoulders back and grab the handles to your sides.","Step on the foot platforms and position the outer part of your lower thighs against the pads.","Take a breath and spread your legs out as much as possible in one fluid motion, breathing out.","Bring your knees together as you breathe in."]},{"id":"22578A94","name":"Hip Adduction (Cable)","primary":"adductors","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/112671201-Cable-Standing-Hip-Adduction-(VERSION-3)_Hips_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/112671201-Cable-Standing-Hip-Adduction-(VERSION-3)_Hips_.mp4","howto":["Set the cable pulley to the lowest position, attach an ankle cuff, and select the weight.","Wrap the cuff around your right ankle and stand up with your right shoulder pointing toward the machine.","Take a step away from the machine. The goal is for the weight to be unracked while your right leg is at your side. You can hold onto the machine for balance.","Engage your abs and slightly raise your right foot off the ground.","Inhale and bring your right leg in until the right foot is in front of the left one. Exhale.","Let your right leg return to the side as you breathe in.","Repeat.","Once finished, wrap the cuff around your left ankle, stand up with your left shoulder pointing toward the pulley, step away, and repeat for the same number of reps."]},{"id":"8BEBFED6","name":"Hip Adduction (Machine)","primary":"adductors","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/05981201-Lever-Seated-Hip-Adduction_Thighs_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/05981201-Lever-Seated-Hip-Adduction_Thighs.mp4","howto":["Select the appropriate load.","Sit down and place your inner thighs against the machine pads. Position your feet on the foot platforms below.","Grab the handles to your sides, retract your shoulder blades, and take a breath.","Squeeze your inner thigh muscles to bring the pads together as you breathe out.","Move your legs to the starting position as you breathe in."]},{"id":"92B8C7E1","name":"Hip Thrust","primary":"glutes","secondary":["hamstrings","quadriceps"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/80151201-Glute-Bridge-from-Bench-(male)_Hips_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/80151201-Glute-Bridge-from-Bench-(male)_Hips_.mp4","howto":["Sit on the floor and position your upper back against the edge of a bench.","Bend your arms and place your hands on your chest.","Bend your knees and plant your feet flat on the floor. Your knees should point forward, not to the sides.","Bring your shoulders back and take a breath.","Engage your glutes and push through your heels to raise your butt until your hips align with your shoulders.","Hold the contraction for a moment and exhale.","Lower your butt to the floor as you breathe in."]},{"id":"D57C2EC7","name":"Hip Thrust (Barbell)","primary":"glutes","secondary":["hamstrings","quadriceps","adductors"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/10601101-Barbell-Hip-Thrust_Hips_small_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/10601201-Barbell-Hip-Thrust_Hips-FIX_.mp4","howto":["Sit on the floor and position a loaded barbell over your hips.","Place your upper back against the edge of a flat gym bench.","Bend your knees and plant your feet flat on the floor.","Place your hands over the barbell and grab it firmly.","Engage your abs and take a breath.","Thrust the barbell toward the ceiling by squeezing your buttocks and pushing through your heels. Exhale at the top.","Lower your hips to the floor and breathe in."]},{"id":"DA5430FC","name":"Hip Thrust (Dumbbell)","primary":"glutes","secondary":["hamstrings","quadriceps","adductors"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/53291201-Dumbbell-Hip-Thrust-(VERSION-2)_Hips_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/53291201-Dumbbell-Hip-Thrust-(VERSION-2)_Hips_.mp4","howto":["Sit on the ground with a flat gym bench behind you and a dumbbell at your side.","Lean back and place your upper back against the edge of the bench.","Position your feet roughly hip-width apart and plant them flat on the ground.","Grab the dumbbell and place it over your hips. Hold it in position with both hands.","Breathe in, engage your abs, and push through your heels to drive your hips to the ceiling.","Pause when your knees, hips, and upper body align. Exhale.","Slowly lower your hips while keeping your abs engaged. Breathe in on the way down.","Repeat."]},{"id":"68CE0B9B","name":"Hip Thrust (Machine)","primary":"glutes","secondary":["hamstrings","quadriceps","adductors"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/107891201-Lever-Hip-Thrust-(male)_Hips_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/107891201-Lever-Hip-Thrust-(male)_Hips_.mp4","howto":["Select or load the appropriate weight.","Lie back on the machine with your arms to your sides and your upper back in contact with the pad.","Secure the strap or belt over your hips.","Take a deep breath and engage your abs.","Press through your heels to extend your hips toward the ceiling. Squeeze your glutes at the top and hold for a moment as you exhale.","Slowly lower your buttocks to the starting position as you breathe in."]},{"id":"291ABA92","name":"Hip Thrust (Smith Machine)","primary":"glutes","secondary":["hamstrings","quadriceps","adductors"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/31101201-Smith-Hip-Thrust_Hips-FIX_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/31101201-Smith-Hip-Thrust_Hips-FIX_.mp4","howto":["Set the Smith machine bar to a low position, enough to be able to tuck underneath.","Load the bar appropriately and place a pad to prevent hip discomfort.","Position a flat gym bench parallel or perpendicular to the bar at an approximately one-foot distance (tweak the setup to find your ideal position).","Sit on the floor and lean back to position your shoulder blades on the bench. The bar should be directly over your hips.","Bend your knees and plant your feet on the floor.","Grab the bar, push your hips against the pad, and engage your abs.","Breathe in and push through your heels to raise your hips toward the ceiling until they align with your knees and upper body. Exhale at the top.","Slowly lower your buttocks to the floor as you breathe in."]},{"id":"970ADF87","name":"Hollow Rock","primary":"abdominals","secondary":[],"equipment":"none","type":"duration","thumb":"assets/thumbs/56491201-Hollow-Rock-(male)_Waist_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/56491201-Hollow-Rock-(male)_Waist_.mp4","howto":["Lie down on an exercise mat. Have your hands at your sides, feet together, and legs straight.","Contract your abs as if trying to initiate a crunch. Doing so will put your lower back against the exercise mat.","Squeeze your thigh muscles as your legs are together, and lift your feet a couple of inches off the floor. Keep your legs straight.","Lift your head a couple of inches off the floor and extend your arms back behind your head.","Hold the position for as long as possible and breathe steadily."]},{"id":"50DFDFAB","name":"Incline Bench Press (Barbell)","primary":"chest","secondary":["triceps","shoulders"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/00471201-Barbell-Incline-Bench-Press_Chest_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00471201-Barbell-Incline-Bench-Press_Chest.mp4","howto":["Lie back on the incline bench and grab the bar with an even overhand grip. The bar should be close enough to unrack without overextending your body.","Bring your shoulders back, engage your abs, and plant your feet on the floor.","Take a breath and unrack the bar by locking out your elbows.","Bring the barbell over your chest and take another breath.","Lower the weight to your mid chest and pause for a moment.","Press the bar in a straight line and exhale near the top.","Once finished, carefully bring the bar over your head and rack it before relaxing."]},{"id":"07B38369","name":"Incline Bench Press (Dumbbell)","primary":"chest","secondary":["triceps","shoulders"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/03141201-Dumbbell-Incline-Bench-Press_Chest_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/03141201-Dumbbell-Incline-Bench-Press_Chest.mp4","howto":["Set the incline of a bench at 45 degrees, grab a pair of dumbbells, and sit down.","Place the dumbbells on top of your thighs, and lie back as you kick the weights up and over your torso.","Bring the dumbbells to your sides, plant your feet on the floor, retract your shoulders, and take a breath. Keep your elbows somewhat tucked in.","Press both dumbbells toward the ceiling, tapping them lightly at the top. Breathe out.","Lower the weights to your sides, breathing in on the way down."]},{"id":"3A6FA3D1","name":"Incline Bench Press (Smith Machine)","primary":"chest","secondary":["shoulders","triceps"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/07571201-Smith-Incline-Bench-Press_Chest_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/07571201-Smith-Incline-Bench-Press_Chest.mp4","howto":["Place an incline bench under the Smith machine. The bar should be directly over your mid-chest when you lie down.","Set the bar at a height you can reach without fully extending your arms.","Lie down, grab the bar with an overhand grip (palms facing forward), and dig your shoulder blades into the bench.","Engage your abs and press the bar up, rotating it to remove the safety.","Take a breath and lower the bar to your chest.","Press it back to the top and exhale.","Once finished, rack the bar."]},{"id":"D3E2AB55","name":"Incline Chest Fly (Dumbbell)","primary":"chest","secondary":[],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/03191201-Dumbbell-Incline-Fly_Chest_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/03191201-Dumbbell-Incline-Fly_Chest.mp4","howto":["Grab a pair of dumbbells and sit at the base of an incline gym bench.","Place the weights on top of your thighs and lie back slowly.","Lift the dumbbells over your chest and extend your arms.","Bring your shoulders back and take a breath.","Extend your arms to your sides until your elbows are at torso level. Keep your elbows slightly bent.","Bring your arms in, squeezing your chest, and tap the dumbbells at the top. Exhale."]},{"id":"FBF92739","name":"Incline Chest Press (Machine)","primary":"chest","secondary":["shoulders","triceps"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/14791201-Lever-Incline-Chest-Press_Chest_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/14791201-Lever-Incline-Chest-Press_Chest.mp4","howto":["Add the appropriate amount of weight.","Adjust the seat height so you can comfortably grab the handles and keep your elbows tucked as you sit down.","Sit down, plant your feet on the floor, and grab the handles.","Retract your shoulder blades, engage your abs, and take a breath.","Press the handles up and overhead in one fluid motion, exhaling at the top.","Slowly bend your arms as you breathe in."]},{"id":"39C99849","name":"Incline Push Ups","primary":"chest","secondary":["shoulders","triceps"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/37851201-Incline-Push-Up-(on-box)_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/37851201-Incline-Push-Up-(on-box).mp4","howto":["Place your hands on the edge of a sturdy object (plyo box, gym bench, or a chair).","Straighten your body as you would for a regular push-up.","Bring your shoulders back and squeeze your glutes.","Take a breath and lower yourself to the object you’re using, tapping your chest at the bottom position.","Press yourself back to the top and fully extend your arms as you exhale."]},{"id":"425805F4","name":"Inverted Row","primary":"upper_back","secondary":["lats","biceps","forearms"],"equipment":"machine","type":"reps_only","thumb":"assets/thumbs/04991201-Inverted-Row_Back_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/04991201-Inverted-Row_Back.mp4","howto":["Set a bar for the rows at around hip height. You can use a Smith machine.","Grab the bar with an overhand grip and tuck yourself underneath.","With your arms straight and bar over your chest, extend your body and balance your lower half on your heels.","Engage your glutes and abs, bring your chest out, and take a breath. Your body should be as straight as an arrow.","Pull through your elbows to bring your body toward the bar. Touch the bar to your chest without flaring your elbows. Breathe out.","Slowly lower yourself to the starting position as you breathe in."]},{"id":"24706DCD","name":"Iso-Lateral Chest Press (Machine)","primary":"chest","secondary":["shoulders","triceps"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/05761201-Lever-Chest-Press-(plate-loaded)_Chest_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/05761201-Lever-Chest-Press-(plate-loaded)_Chest.mp4","howto":["Add the appropriate weight to the machine.","Adjust the seat height. You should be able to press without flaring your elbows.","Sit down and grab the handles with an overhand grip (palms facing down).","Bring your shoulders back, plant your feet on the floor, and take a breath.","Press the handles forward and up, exhaling as your arms straighten.","Bend your elbows as you breathe in."]},{"id":"BC3492DA","name":"Iso-Lateral High Row (Machine)","primary":"lats","secondary":["upper_back","biceps","forearms"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/05811101-Lever-High-Row-(plate-loaded)_Back_small_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/43781201-Lever-Reverse-Grip-High-Row-(plate-loaded)_Back_.mp4","howto":["Load the machine and set the thigh pad for your legs to fit snugly.","Sit down and grab the handles.","Bring your shoulders back, engage your abs, and take a breath.","Pull the handles to your torso, squeezing your back muscles, and breathe out.","Slowly extend your arms as you breathe in."]},{"id":"91FAFBA3","name":"Iso-Lateral Low Row","primary":"upper_back","secondary":["lats","biceps","forearms"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/42141201-Lever-Low-Row-(plate-loaded)_Back__thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/42141201-Lever-Low-Row-(plate-loaded)_Back_.mp4","howto":["Add the appropriate amount of weight.","Sit down with your stomach and chest against the pad.","Reach forward and grab the two handles.","Retract your shoulder blades, take a deep breath, and engage your abs.","Pull both handles until your elbows are at your sides, and squeeze your back muscles as you exhale.","Slowly extend your arms as you breathe in."]},{"id":"AA1EB7D8","name":"Iso-Lateral Row (Machine)","primary":"upper_back","secondary":["lats","biceps","forearms"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/05881201-Lever-Neutral-Grip-Seated-Row-(plate-loaded)_Back-_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/05881201-Lever-Neutral-Grip-Seated-Row-(plate-loaded)_Back-.mp4","howto":["Add the appropriate weight to the machine.","Adjust the seat height to have your torso against the front pad when you sit down.","Sit down, plant your feet flat, position your torso against the pad, and grab the handles.","Bring your shoulders back and take a breath.","Pull the handles to your sides, squeezing your back at the top of the repetition and exhaling.","Slowly extend your arms while keeping your shoulders retracted and breathe in."]},{"id":"D410F649","name":"Jack Knife (Suspension)","primary":"abdominals","secondary":[],"equipment":"suspension","type":"reps_only","thumb":"assets/thumbs/103441201-Suspender-Hip-Lift-Knee-Tuck-(male)_Hips_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/103441201-Suspender-Hip-Lift-Knee-Tuck-(male)_Hips_.mp4","howto":["Secure your feet on the handles of a suspension kit.","Extend your body into a push-up position with your arms straight or bent, shoulders back, and abs tight.","Take a breath and tuck your knees, bringing them close to your elbows. Breathe out.","Slowly extend your knees as you breathe in."]},{"id":"32B0B590","name":"Jackknife Sit Up","primary":"abdominals","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/107121201-Jack-knife-Sit-up-(male)_Waist_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/107121201-Jack-knife-Sit-up-(male)_Waist_.mp4","howto":["Lie flat on the floor with your legs straight and arms at your sides. Your heels, legs, butt, upper back, head, and arms should be in contact with the floor.","Engage your abs and raise your legs as you bend your knees.","Simultaneously lift your torso, bringing your arms toward your lower body. Exhale.","Extend your body back to the starting position and breathe in on the way down."]},{"id":"74103F24","name":"JM Press (Barbell)","primary":"triceps","secondary":["chest","shoulders"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/00521201-Barbell-JM-Bench-Press_Upper-Arms-FIX_-2_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00521201-Barbell-JM-Bench-Press_Upper-Arms-FIX_.mp4","howto":["Set the barbell at a height where you can reach it without fully extending your arms.","Lie on the bench, reach up, grab the bar with a shoulder-width grip, and unrack it.","Position the bar over your chest with your arms straight, just as you would during a standard bench press.","Plant your feet on the floor, retract your shoulder blades, take a deep breath, and engage your abs.","Slowly bend your elbows, lowering the barbell to your upper chest.","Pause briefly and fully extend your arms as you exhale."]},{"id":"040BA2E3","name":"Jump Rope","primary":"cardio","secondary":[],"equipment":"other","type":"duration","thumb":"assets/thumbs/26121201-Jump-Rope-(male)_Cardio_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/26121201-Jump-Rope-(male)_Cardio.mp4","howto":[]},{"id":"BA3DE542","name":"Jump Shrug","primary":"full_body","secondary":[],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/49641201-Jump-Shrug_Thighs_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/49641201-Jump-Shrug_Thighs_.mp4","howto":["Grab a barbell with an overhand grip (palms facing back) and stand tall. Your hands should be just outside your thighs.","Bring your shoulders back and engage your abs.","Lean your torso forward slightly by hinging at the hip.","Take a breath, bend your knees slightly, and press through your heels to jump.","Immediately shrug your shoulders as high as possible and exhale."]},{"id":"70D4EBBF","name":"Jump Squat","primary":"quadriceps","secondary":["hamstrings","glutes","calves"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/05141201-Jump-Squat_Thighs_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/05141201-Jump-Squat_Thighs.mp4","howto":["Stand tall with your feet shoulder-width apart and toes pointing slightly out.","Bring your shoulders back, engage your abs, and position your hands in front of your torso.","Take a breath and descend halfway into a squat.","Press through your heels to move up and immediately jump as high as possible, swinging your arms to your sides and behind your body as you exhale.","Take another breath as you land and descend into another squat."]},{"id":"991833C2","name":"Jumping Jack","primary":"full_body","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/30941201-Jumping-Jack-(male)_Cardio_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/30941201-Jumping-Jack-(male)_Cardio.mp4","howto":["Stand tall with your arms to your sides, legs straight, and feet together.","Engage your abs and take a breath.","Hop and bring your feet out as you extend your arms to your sides and over your head.","Jump again and bring your feet together and arms to your sides. Exhale.","Keep repeating rhythmically, hopping just a couple of inches off the floor, and breathing regularly."]},{"id":"5CC07A1F","name":"Jumping Lunge","primary":"quadriceps","secondary":["hamstrings","glutes","calves"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/11661201-Jump-Split-m_Plyometrics_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/11661201-Jump-Split-m_Plyometrics.mp4","howto":["Stand tall with your feet a few inches apart, arms to your sides, and shoulders back.","Engage your abs and take a breath.","Jump vertically and immediately bring your right leg forward and your left leg back.","As you land on your front foot and the ball of your left foot, immediately sink into a lunge.","Descend until your front thigh is almost parallel to the floor.","Press through your front heels to move up and immediately jump. Exhale as you start moving up.","Switch leg positions while in the air, breathe in, and sink into another lunge.","Keep jumping and switching leg positions, doing a lunge in between."]},{"id":"55BA475A","name":"Kettlebell Around the World","primary":"shoulders","secondary":["traps","chest","abdominals"],"equipment":"kettlebell","type":"weight_reps","thumb":"assets/thumbs/108311201-Kettlebell-Standing-Slingshots-(male)_Shoulders_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/108311201-Kettlebell-Standing-Slingshots-(male)_Shoulders_.mp4","howto":["Hold a kettlebell in your right hand and stand tall with your feet hip-width apart and shoulders back.","Engage your abs and breathe in.","Move the kettlebell to the left in front of your body and switch hands, grabbing the weight with your left hand.","Continue the rotation by moving the kettlebell back and around your body.","As the kettlebell gets to your buttocks, reach back with your right hand and grab it, continuing the rotation in the same direction.","Continue switching hands as the kettlebell rotates around your waist and breathe steadily. Maintain a consistent tempo and keep your abs tense.","Once finished rotating the weight in one direction, do the same number of reps in the opposite direction."]},{"id":"F99C211D","name":"Kettlebell Clean","primary":"full_body","secondary":[],"equipment":"kettlebell","type":"weight_reps","thumb":"assets/thumbs/05351201-Kettlebell-Hang-Clean_thighs_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/05351201-Kettlebell-Hang-Clean_thighs.mp4","howto":["Position the kettlebell on the floor.","Stand in front of the weight with your feet hip-width apart.","Bend your knees and lean your torso forward, grabbing the kettlebell with your right hand.","Engage your abs and take a breath.","Press through your heels to straighten your knees as you simultaneously pull the weight in a straight vertical line close to your body.","As the kettlebell reaches hip level, drive your hips forward and thrust the weight up.","Bend your arm and have the kettlebell land on your shoulder, lying against the top of your forearm and biceps. Exhale.","Lower the weight to the floor and breathe in on the way down or before initiating the next rep..","Once finished, grab the kettlebell with your left hand and do the same number of reps."]},{"id":"4E239ED8","name":"Kettlebell Curl","primary":"biceps","secondary":[],"equipment":"kettlebell","type":"weight_reps","thumb":"assets/thumbs/58571201-Kettlebell-Biceps-Curl_Upper-Arms_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/58571201-Kettlebell-Biceps-Curl_Upper-Arms_.mp4","howto":["Grab a pair of kettlebells and position them to your sides with your arms straight and palms facing forward.","Bring your shoulders back and engage your abs.","Take a breath and curl the kettlebells, bending your arms until your wrists are slightly higher than your elbows. Breathe out at the top.","Slowly extend your arms, breathing in as you lower them.","Repeat."]},{"id":"A127DA73","name":"Kettlebell Goblet Squat","primary":"quadriceps","secondary":["glutes","hamstrings"],"equipment":"kettlebell","type":"weight_reps","thumb":"assets/thumbs/05341201-Kettlebell-Goblet-Squat_Thighs-FIX_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/05341201-Kettlebell-Goblet-Squat_Thighs-FIX_.mp4","howto":["Grab a kettlebell by the horns or have your palms against the bell with the handle pointing down.","Lift the weight in front of your chest with your elbows bent.","Bring your shoulders back and position your feet in a comfortable stance, with your toes slightly pointed out.","Take a breath and engage your abs.","Descend by bending your knees and maintaining an upright torso as you move down.","Squat until your thighs are parallel to the floor and your elbows are between your thighs.","Hold the bottom position for a moment.","Push through your heels to move up, keeping the kettlebell close to your body.","Exhale as you straighten your legs."]},{"id":"4288G454","name":"Kettlebell Halo","primary":"shoulders","secondary":["traps","upper_back"],"equipment":"kettlebell","type":"weight_reps","thumb":"assets/thumbs/29391201-Kettlebell-Around-Head-Rotation_Back_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/29391201-Kettlebell-Around-Head-Rotation_Back.mp4","howto":["Grab a kettlebell by the horns with your wrists neutral and thumbs facing forward.","Stand up and turn the kettlebell bottoms up with your palms now facing your body and your elbows bent at roughly 90 degrees.","Assume a comfortable stance, bring your chest out, and engage your abs.","Breathe in and pull the kettlebell back and around the right side of your head. This will cause your left forearm to travel over your head.","As the kettlebell moves behind your head, continue the rotation by raising your right forearm above your head.","Complete the rep by bringing the kettlebell to the starting position in front of your chest. Exhale.","Breathe in and rotate the kettlebell around your head, this time in the opposite direction."]},{"id":"9B13BA4B","name":"Kettlebell High Pull","primary":"full_body","secondary":["traps"],"equipment":"kettlebell","type":"weight_reps","thumb":"assets/thumbs/05481101-Kettlebell-Sumo-High-Pull_back_small_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/05481201-Kettlebell-Sumo-High-Pull_Back_.mp4","howto":["Position a kettlebell on the floor.","Spread your feet wider than shoulder-width apart, with your toes pointing out.","Bend your knees and grab the kettlebell handle with both hands. Keep your back neutral.","Take a breath and press through your heels to extend your arms.","As the kettlebell reaches hip level, use the momentum and pull the weight vertically into an upright row, exhaling at the top.","Slowly extend your arms and bend your knees and hips to set the weight on the floor, inhaling on the way down or before initiating the next rep."]},{"id":"6433CD93","name":"Kettlebell Shoulder Press","primary":"shoulders","secondary":["triceps"],"equipment":"kettlebell","type":"weight_reps","thumb":"assets/thumbs/99571201-Kettlebell-Single-Arm-Shoulder-Press-(male)_Should_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/99571201-Kettlebell-Single-Arm-Shoulder-Press-(male)_Should.mp4","howto":["Grab a kettlebell and lift it to shoulder level. Keep your elbow bent and the weight positioned against the top of your forearm and bicep.","Bring your shoulders back, engage your abs, and have your feet in a comfortable position.","Take a breath and press the weight straight up, fully extending your arm and exhaling.","Slowly lower it to your side as you breathe in.","Repeat.","Once finished, grab the kettlebell with your opposite hand, performing the same number of reps."]},{"id":"89304423","name":"Kettlebell Snatch","primary":"full_body","secondary":[],"equipment":"kettlebell","type":"weight_reps","thumb":"assets/thumbs/05421101-Kettlebell-One-Arm-Snatch_Shoulders_small_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/05421201-Kettlebell-One-Arm-Snatch_Shoulders_.mp4","howto":["Position a kettlebell in front of your body.","Have your feet shoulder-width apart, with your toes pointing slightly out.","Bend your knees and lean forward to grab the kettlebell.","Stand tall and hold the weight in front of your body.","Bring your shoulders back, engage your abs, and breathe in.","Hinge at the hips as you bring the kettlebell back and between your legs.","Extend your knees and hips to generate momentum and raise the weight forward and up, lifting it overhead in one smooth motion.","Fully straighten your arm as you lift the kettlebell overhead and exhale.","Lower the kettlebell in a straight line as you breathe in.","Repeat.","Once finished, do the same number of reps with your opposite arm."]},{"id":"F8A0FCCA","name":"Kettlebell Swing","primary":"full_body","secondary":[],"equipment":"kettlebell","type":"weight_reps","thumb":"assets/thumbs/05491201-Kettlebell-Swing_Hips-FIX_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/05491201-Kettlebell-Swing_Hips-FIX_.mp4","howto":["Grab a kettlebell by its handle with your wrists neutral (palms facing one another).","Stand tall and have the weight in front of your hips. Your feet should be shoulder-width apart or slightly wider.","Bring your shoulders back, engage your abs, and take a breath.","Hinge at the hip, bringing your buttocks back. The kettlebell should end up between your thighs.","Extend your hips forcefully, thrusting the kettlebell in front of your body until it ends up at shoulder height, and exhale.","Lower the kettlebell and immediately hinge at the hips again for the weight to end up between your thighs."]},{"id":"5F8903BF","name":"Kettlebell Turkish Get Up","primary":"full_body","secondary":[],"equipment":"kettlebell","type":"weight_reps","thumb":"assets/thumbs/05511101-Kettlebell-Turkish-Get-Up-(Squat-style)_Thighs_small_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/05511201-Kettlebell-Turkish-Get-Up-(Squat-style)_Thighs.mp4","howto":["Lie on the floor with your right knee bent and your right foot flat on the ground. Have your left leg straight.","Hold a kettlebell in your right hand and keep your wrist, elbow, and shoulder in vertical alignment.","Move your left arm to the side with the hand flat on the floor.","Engage your abs, take a breath, and raise your torso off the floor. Keep your right arm straight and the kettlebell over your shoulder joint. Push yourself with your left arm until your torso is vertical and you're seated.","With the kettlebell still over your right shoulder and left hand supporting you, bend your left leg and place the knee on the floor, raising yourself.","Raise your torso higher and remove your left hand from the floor.","Square your hips to create a solid lunge position, take another breath, and lift your left knee, stepping on the left foot.","Get up to the standing position by extending your knees and hips. Keep the kettlebell over your shoulder, and don’t bend your elbow.","Reverse the motion by lunging back, lifting your left foot off the floor, landing on your left knee, and rotating the left leg behind your body.","Place your left hand on the floor, extend your left leg in front of you, and get into the seated position without extending the right knee.","Bend your left arm to lower your torso and lie on your back and into the starting position."]},{"id":"A91838C0","name":"Kipping Pull Up","primary":"lats","secondary":["upper_back","biceps","forearms"],"equipment":"machine","type":"reps_only","thumb":"assets/thumbs/51491201-Butterfly-Pull-Up_Back_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/51491201-Butterfly-Pull-Up_Back_.mp4","howto":["Reach up and grab the pull-up bar with an overhand grip (palms facing forward).","Raise your legs slightly and bring your buttocks back to swing your body slightly and generate momentum.","Use the momentum you generate by allowing your legs to swing back, bringing your back into hyperextension.","Continue building momentum by allowing your legs to swing forward.","Bend your elbows to pull yourself up. Bring your chin over the bar, straighten your body, and allow the momentum to til you slightly back, similar to an inverted row.","Lower yourself immediately and keep your body in the tilted position.","Once your arms are almost entirely straight, allow your legs to drop and swing back as your buttocks travel back, causing an arch in your spine.","Swing your legs forward again and use the momentum to pull yourself up a second time.","Keep moving up and down, using momentum to go from back flexion to hyperextension on each repetition."]},{"id":"98237BA2","name":"Knee Raise Parallel Bars","primary":"abdominals","secondary":[],"equipment":"machine","type":"reps_only","thumb":"assets/thumbs/21261201-Captains-chair-leg-raise_Hips_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/21261201-Captains-chair-leg-raise_Hips.mp4","howto":["Position yourself inside a captain’s chair with your feet on a platform or steps, back against the pad, and forearms flat on the pair of padded parallel bars.","Bring your shoulders back and contract your abs.","Step off the platform or steps and support yourself with your upper body musculature. Keep your shoulders in position and avoid slumping.","Take a breath and engage your abs to raise your knees as high as possible in one fluid motion. Breathe out at the top.","Lower your knees to the starting position, extending them on the way down, and stop before your lower back begins to arch. Breathe in on the way down."]},{"id":"D82EA543","name":"Kneeling Pulldown (band)","primary":"lats","secondary":["upper_back","biceps","forearms"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/43581201-Band-Knelling-Lat-Pulldown_Back_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/43581201-Band-Knelling-Lat-Pulldown_Back_.mp4","howto":["Attach a resistance band overhead.","Grab both resistance band handles, step back, and kneel.","Lean your torso forward in the direction of the resistance band anchor point.","Bring your shoulders back and take a breath.","Pull the band to your shoulders while keeping your elbows tucked in and in line with your torso. Exhale.","Extend your arms slowly as you breathe in."]},{"id":"B74A95BB","name":"Kneeling Push Up","primary":"chest","secondary":["triceps","shoulders"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/32111101-Kneeling-Push-up-(male)_small_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/32111201-Kneeling-Push-up-(male)_Chest.mp4","howto":["Get down on your hands and knees.","Lean forward and position your hands in a comfortable stance.","Engage your abs and take a breath.","Descend by bending your elbows.","Move down until your face is an inch from the floor and pause.","Press yourself back to the top and exhale."]},{"id":"6D54A050","name":"L-Sit Hold","primary":"abdominals","secondary":["triceps"],"equipment":"none","type":"duration","thumb":"assets/thumbs/107951201-L-Sit-(male)_Waist_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/107951201-L-Sit-(male)_Waist_.mp4","howto":["Position yourself on a captain’s chair or parallel dip bars.","Grab the handles evenly and straighten your arms.","Suspend yourself in the air and engage your abs.","Take a breath and raise your legs until they are parallel to the floor.","Hold the position for 15 to 60 seconds and release."]},{"id":"923874CA","name":"Landmine 180","primary":"abdominals","secondary":["shoulders","chest","upper_back","traps","biceps","forearms"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/05621201-Landmine-180_waist_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/05621201-Landmine-180_waist.mp4","howto":["Secure one end of a barbell on a landmine attachment and put a weight plate on the other.","Grab the barbell sleeve with your palms supporting the bottom end.","Stand tall and position the barbell to your right with your arms straight and abs flexed.","Take a breath and raise the barbell to your face by bending your elbows.","Immediately lower the weight to your left, extending your arms. Exhale.","Take another breath and lift the barbell in the opposite direction."]},{"id":"D7D7FCCE","name":"Landmine Row","primary":"upper_back","secondary":["lats","biceps","forearms"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/32001201-Lever-Bent-over-Row-with-V-bar-(plate-loaded)_Back_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/32001201-Lever-Bent-over-Row-with-V-bar-(plate-loaded)_Back.mp4","howto":["Secure one end of a barbell to a landmine attachment.","Add the appropriate amount of weight to the other side of the bar.","Take a V-handle and position it underneath the barbell.","Grab the handle with both hands, placing it securely against the end of the barbell shaft (just before the sleeve begins).","Bend your knees, retract your shoulder blades, and squeeze your abs.","Lift the barbell a couple of inches off the floor and take another breath.","Row the bar to your upper stomach and pause briefly as you exhale.","Lower the barbell by extending your arms and breathe in. Don’t rest the bar on the floor."]},{"id":"983274DD","name":"Landmine Squat and Press","primary":"full_body","secondary":[],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/29761301-Landmine-Squat-and-Press_360_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/29761201-Landmine-Squat-and-Press_.mp4","howto":["Anchor one end of a barbell on a landmine and add a weight plate on the other.","Reach down and grab the free barbell end with both hands.","Straighten your body and have your hands together and in front of your chest.","Position your feet in a comfortable stance for squats.","Engage your abs, take a breath, and descend into a squat.","Go down until your thighs are parallel to the floor, and press through your heels to move back up.","As you straighten your legs, immediately press the bar overhead and exhale at the top.","Slowly lower the bar to your chest, inhale, and squat."]},{"id":"D2FE7B2E","name":"Lat Pulldown (Band)","primary":"lats","secondary":["upper_back","biceps","forearms"],"equipment":"resistance_band","type":"weight_reps","thumb":"assets/thumbs/09741101-Band-close-grip-pulldown_Back_small_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/31161201-Band-Fixed-Back-Underhand-Pulldown_Back_.mp4","howto":["Anchor a resistance band overhead - for example, on a pull-up bar.","Grab both ends of the resistance band, straighten your arms, step back to lengthen the band, and sit on a plyo box or gym bench. You can also kneel.","Lean slightly in the direction of the band anchor point.","Take a breath and pull the band to your upper chest, squeezing your lats at the bottom and breathing out.","Extend your arms slowly and breathe in."]},{"id":"6A6C31A5","name":"Lat Pulldown (Cable)","primary":"lats","secondary":["upper_back","biceps","forearms"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/01501201-Cable-Bar-Lateral-Pulldown_Back_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/01501201-Cable-Bar-Lateral-Pulldown_Back.mp4","howto":["Adjust the knee pad on the machine to be right against your thighs.","Select a weight you can lift for at least ten smooth reps.","Grab the bar with your hands slightly wider than shoulder-width apart. Your palms should face forward.","Sit down and secure your legs underneath the pad.","With your arms extended, bring your shoulders back and down.","Take a breath and pull the weight down through your elbows. As you pull, keep your elbows tucked and in line with your torso. Breathe out.","Hold for a moment and extend your arms fully as you breathe in."]},{"id":"473CF5B8","name":"Lat Pulldown (Machine)","primary":"lats","secondary":["upper_back","biceps","forearms"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/05791201-Lever-Front-Pulldown_Back_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/05791201-Lever-Front-Pulldown_Back.mp4","howto":["Select the appropriate load.","Adjust the thigh pad. Your legs should fit snugly.","Stand up and grab the handles with an even overhand grip (palms facing forward).","Keep your arms straight and sit down, securing your legs under the pad.","Bring your shoulders back and take a breath.","Pull the handles down, tucking your elbows and bringing them in line with your torso. Breathe out.","Extend your arms slowly and breathe in."]},{"id":"4E5257DE","name":"Lat Pulldown - Close Grip (Cable)","primary":"lats","secondary":["upper_back","biceps","forearms"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/63921201-Cable-Lateral-Pulldown-with-Mag-Grip_Back_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/63921201-Cable-Lateral-Pulldown-with-Mag-Grip_Back_.mp4","howto":["Attach a V handle to a lat pulldown machine.","Select the appropriate load.","Adjust the thigh pad for your legs to fit snugly underneath.","Grab the V handle with a neutral grip (palms facing one another), sit down, and position your thighs underneath the pad.","Bring your shoulders back and lean your torso slightly back.","Inhale and pull the V handle to your chest, squeezing your back muscles and exhaling.","Slowly extend your arms as you breathe in."]},{"id":"EC02979E","name":"Lateral Band Walks","primary":"glutes","secondary":["abductors"],"equipment":"resistance_band","type":"reps_only","thumb":"assets/thumbs/66071201-Resistance-Band-Lateral-Walk-(male)_Hips_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/66071201-Resistance-Band-Lateral-Walk-(male)_Hips_.mp4","howto":["Wrap a looped resistance band around your ankles or thighs, just above the knees.","Lean your torso forward a bit and bend your knees slightly.","Engage your abs and take a breath.","Take a lateral step to the right and exhale.","Inhale again and take another step in the same direction.","Once finished walking in one direction, take the same number of steps to the left, breathing steadily as you do."]},{"id":"07EBC4DC","name":"Lateral Box Jump","primary":"quadriceps","secondary":["hamstrings","glutes","calves"],"equipment":"other","type":"reps_only","thumb":"assets/thumbs/108271201-Lateral-Box-Jump-(male)_Plyometrics_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/108271201-Lateral-Box-Jump-(male)_Plyometrics_.mp4","howto":["Stand sideways to a plyometric box or flat gym bench.","Have your feet close, arms to your sides, and your body straight.","Take a breath, descend into a quarter squat, and swing your arms back.","Press through your heels to extend your legs and drive your arms forward, jumping laterally and up. Breathe out.","Land on the elevated platform and carefully get down on the opposite side as you breathe in.","Jump laterally in the opposite direction.","Keep alternating."]},{"id":"DC59D143","name":"Lateral Leg Raises","primary":"glutes","secondary":["abductors"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/84191201-Sideway-Leg-Lift-with-a-Chair-(male)_Hips_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/84191201-Sideway-Leg-Lift-with-a-Chair-(male)_Hips_.mp4","howto":["Stand tall with your feet together, legs straight, and shoulders back.","Grab onto something for balance––for example, a squat rack or chair.","Engage your abs and take a breath.","Raise your right leg laterally as high as possible in one fluid motion and exhale.","Lower your leg to the starting position and breathe in.","Once finished, do the same number of reps with the opposite leg."]},{"id":"F2A37357","name":"Lateral Lunge","primary":"quadriceps","secondary":["hamstrings","glutes","abductors"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/29721201-Side-Lunge_Thighs_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/29721201-Side-Lunge_Thighs.mp4","howto":["Stand tall with your feet a few inches apart and your toes pointing slightly out.","Bring your shoulders back, engage your abs, and position your hands in front of your chest.","Take a breath and bring your left leg to the side, planting the foot flat on the floor.","Immediately sink into a lunge by bending the knee. Keep your opposite leg straight and your foot on the ground.","Descend until your left thigh is almost parallel to the floor and hold for a moment.","Press through your left heel to extend your knee and bring your leg to the starting position as you exhale.","Inhale again as you bring your right leg out, performing the same movement.","Keep alternating."]},{"id":"DF200976","name":"Lateral Raise (Band)","primary":"shoulders","secondary":[],"equipment":"resistance_band","type":"weight_reps","thumb":"assets/thumbs/15081201-Band-Lateral-Raise-(Version-2)_Shoulders_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/15081201-Band-Lateral-Raise-(Version-2)_Shoulders.mp4","howto":["Take an open-ended resistance band with handles on both ends.","Step over the middle of the band and hold the handles to your sides.","Bring your shoulders back, engage your abs, and lean your torso slightly forward. Your hands should be in front of your hips.","Raise your arms to your sides in one fluid motion. Go up until your shoulders, elbows, and wrists align, exhaling at the top.","Lower your arms to the starting position as you breathe in."]},{"id":"BE289E45","name":"Lateral Raise (Cable)","primary":"shoulders","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/01781201-Cable-Lateral-Raise_shoulder_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/01781201-Cable-Lateral-Raise_shoulder.mp4","howto":["Set the pulleys of a double cable machine in the lowest position and attach handles.","Select the appropriate weight on both stacks.","Walk to the left and grab the handle with your right hand.","Walk to the right and grab the other handle with your left hand.","Stand in the middle with your arms straight and your hands in front of your hips.","Engage your abs, retract your shoulder blades, and breathe in.","Raise both arms to your sides in one fluid motion, going up until your shoulders, elbows, and wrists align. Exhale at the top.","Lower your arms as you breathe in."]},{"id":"422B08F1","name":"Lateral Raise (Dumbbell)","primary":"shoulders","secondary":[],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/03341201-Dumbbell-Lateral-Raise_shoulder_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/03341201-Dumbbell-Lateral-Raise_shoulder.mp4","howto":["Grab a pair of light dumbbells and stand tall.","Bring your shoulders back, engage your abs, and take a breath.","Lift both arms laterally until your elbows and wrists align with your shoulders. Exhale at the top.","Lower the dumbbells to your sides as you breathe in."]},{"id":"D5D0354D","name":"Lateral Raise (Machine)","primary":"shoulders","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/05841201-Lever-Lateral-Raise_shoulder_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/05841201-Lever-Lateral-Raise_shoulder.mp4","howto":["Select the appropriate load and adjust the seat’s height.","Sit down and bring your shoulders back and into the back support.","Grab the handles on your sides and position your forearms flat against the pads.","Take a breath and bring your arms to your sides smoothly, going up until your elbows are at shoulder level. Breathe out.","Lower your arms to your sides and breathe in."]},{"id":"D731CCA8","name":"Lateral Squat","primary":"quadriceps","secondary":["hamstrings","glutes","abductors"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/69241201-Side-Step-Deep-Squat-(male)_Plyometrics_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/69241201-Side-Step-Deep-Squat-(male)_Plyometrics_.mp4","howto":["Stand with your feet hip-width apart, and point your toes slightly out.","Raise your arms in front of your body for balance.","Breathe in, bring your left leg out several inches, plant your foot, and squat.","Go down as low as your strength and mobility allow.","Hold for a moment and forcefully push through your heels to bring yourself to the top as you exhale.","Breathe in, bring your right leg out, plant your foot, and squat.","Keep alternating."]},{"id":"75A4F6C4","name":"Leg Extension (Machine)","primary":"quadriceps","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/05851201-Lever-Leg-Extension_Thighs_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/05851201-Lever-Leg-Extension_Thighs.mp4","howto":["Select the appropriate load.","Adjust the pad to be against your lower legs, just above your feet when seated.","Sit down, grab the handles by your sides, place your lower shins against the pad, and retract your shoulders.","Take a breath and straighten your legs by engaging your quadriceps.","Lift the weight until your knees straighten, and breathe out.","Hold for a moment and bend your knees slowly as you breathe in."]},{"id":"C7973E0E","name":"Leg Press (Machine)","primary":"quadriceps","secondary":["glutes","hamstrings"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/07391201-Sled-45-Leg-Press_Hips_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/07391201-Sled-45-Leg-Press_Hips.mp4","howto":["Add the appropriate weight to the leg press machine and sit down.","Lift your legs and plant your feet flat on the platform. Have your feet in a comfortable position with your toes pointing slightly out.","Grab the handles to your sides, bring your shoulders back, and engage your abs.","Press the platform and straighten your legs while rotating the handles to remove the safety pins.","Take another breath and lower the platform by bending your knees.","Hold the bottom position for a moment and press the platform away as you exhale.","Once finished, straighten your legs, rotate the handles to put the safety pins on, and rest."]},{"id":"0EB695C9","name":"Leg Press Horizontal (Machine)","primary":"quadriceps","secondary":["hamstrings","glutes"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/22671201-Lever-Seated-Leg-Press_Thighs_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/22671201-Lever-Seated-Leg-Press_Thighs.mp4","howto":["Select the appropriate load and sit down.","Place your feet flat on the platform at a comfortable width.","Bring your shoulders back, engage your abs, and grab the handles by your sides.","Take a breath and press the platform forward until you straighten your legs. Exhale.","Bend your legs slowly as you breathe in."]},{"id":"0482DA98","name":"Leg Raise Parallel Bars","primary":"abdominals","secondary":[],"equipment":"machine","type":"reps_only","thumb":"assets/thumbs/29631101-Captains-Chair-Straight-Leg-Raise_Waist_small_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/29631201-Captains-Chair-Straight-Leg-Raise_Waist-FIX_.mp4","howto":["Position yourself on a captain’s chair. Have your forearms flat against the horizontal pads and grab the handles for support.","Bring your feet together and engage your abs to position your lower back against the back support.","Take a breath and raise your legs in one fluid motion, going as high as possible. Exhale at the top.","Slowly lower your legs to the starting position and keep the tension on your abs. Breathe in on the way down, and don’t let your lower back arch."]},{"id":"293483AD","name":"Low Cable Fly Crossovers","primary":"chest","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/01791201-Cable-Low-Fly_Chest_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/01791201-Cable-Low-Fly_Chest.mp4","howto":["Select the appropriate load.","Set the pulleys in the lowest position and attach handles.","Grab both handles one at a time and stand in the middle with your arms to your sides.","Stagger your stance, bring your shoulders back, and squeeze your abs.","Take a breath and bring your arms up and in, tapping the handles lightly as you squeeze your chest and breathe out.","Slowly bring your arms to your sides as you breathe in."]},{"id":"8A2E6481","name":"Low Row (Suspension)","primary":"upper_back","secondary":["lats","biceps","forearms"],"equipment":"suspension","type":"reps_only","thumb":"assets/thumbs/62201201-Suspender-Row-(male)_Back_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/62201201-Suspender-Row-(male)_Back_.mp4","howto":["Grab the handles of a suspension kit and extend your arms in front of your body.","Step forward a bit to lean your body at a comfortable angle.","Bring your shoulders back, engage your abs, and squeeze your glutes.","Take a breath and pull yourself up, squeezing your back muscles at the top and exhaling.","Slowly extend your arms and breathe in."]},{"id":"5E1A7777","name":"Lunge","primary":"quadriceps","secondary":["hamstrings","glutes"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/14601201-Walking-Lunge-Male_Hips_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/14601201-Walking-Lunge-Male_Hips.mp4","howto":["Stand tall with your shoulders back, hands on your hips, and gaze directed forward.","Take a breath and engage your abs.","Lunge forward, bringing your right leg in front of your body, and plant the foot on the floor.","Immediately descend by bending your knee and going down until your back knee taps the floor.","Press through your front heel to stand up and exhale.","Bring your back foot forward, plant it on the floor, and lunge again."]},{"id":"6E6EE645","name":"Lunge (Barbell)","primary":"quadriceps","secondary":["hamstrings","glutes"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/00541201-Barbell-Lunge_Thighs_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00541201-Barbell-Lunge_Thighs.mp4","howto":["Position a barbell on your upper back and grab it for support.","Have your feet hip-width apart with your toes pointing slightly out.","Take a breath, lunge forward, and plant your foot flat on the floor.","Immediately sink into a lunge while keeping your torso stable and upright.","Descend until your back knee is an inch or two from the floor.","Press through your front heel to extend your knee and bring the leg to the starting position as you exhale.","Take another breath and lunge forward, extending the opposite leg.","Keep alternating."]},{"id":"B537D09F","name":"Lunge (Dumbbell)","primary":"quadriceps","secondary":["hamstrings","glutes"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/03361201-Dumbbell-Lunge_Hips_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/03361201-Dumbbell-Lunge_Hips.mp4","howto":["Grab a pair of dumbbells, hold them to your sides, and stand tall.","Bring your shoulders back, engage your abs, and have your feet in a comfortable stance.","Take a breath and lunge forward, plating one foot in front of your body.","Immediately sink into a lunge and descend until your front thigh is almost parallel to the floor. Your back knee should be an inch or two from the floor.","Press through your front heel to extend your leg and bring it back to the starting position as you exhale.","Take another breath and lunge again, bringing your opposite leg forward.","Keep alternating."]},{"id":"BD5935CF","name":"Lying Knee Raise","primary":"abdominals","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/81941201-Lying-Knee-Raise-(male)_Waist_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/81941201-Lying-Knee-Raise-(male)_Waist_.mp4","howto":["Lie on the floor with your feet together, arms to your sides, and your body straight.","Engage your abs and lift your feet an inch or two from the floor. Your lower back should be in contact with the floor.","Take a breath and lift your legs, bending your knees at a 90-degree angle. Breathe out.","Slowly lower your legs to the starting position as you straighten your knees. Breathe in and keep your feet off the floor."]},{"id":"B8127AD1","name":"Lying Leg Curl (Machine)","primary":"hamstrings","secondary":["calves"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/05861201-Lever-Lying-Leg-Curl_Thighs_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/05861201-Lever-Lying-Leg-Curl_Thighs.mp4","howto":["Select the appropriate load and adjust the pad to be over your Achilles tendon (above the heel) when you lie down.","Lie down, grab the handles, and place the back of your lower legs against the pad.","Take a breath and engage your hamstrings to curl your legs, lifting the weight.","Curl until your lower legs are almost vertical and exhale at the top.","Hold for a moment and extend your knees slowly as you inhale."]},{"id":"09C9F635","name":"Lying Leg Raise","primary":"abdominals","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/11631201-Lying-Leg-Raise_Waist_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/11631201-Lying-Leg-Raise_Waist.mp4","howto":["Lie on the floor with your legs straight, arms to your sides, and palms flat on the floor.","Engage your abs, take a breath, and bring your legs together.","Lift your legs in the air until your heels point at the ceiling. Breathe out.","Lower your legs slowly without resting your feet on the floor and breathe in. Maintain slight roundness in your lower back throughout each repetition."]},{"id":"22FEDCA4","name":"Lying Neck Curls","primary":"neck","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/101661201-Lying-Neck-Flexion_Neck_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/101661201-Lying-Neck-Flexion_Neck_.mp4","howto":["Lie face up on a flat gym bench with your head over the edge.","Breathe in and lower your head to a comfortable level.","Flex the muscles on the front of your neck to perform a repetition as you exhale.","Lower your head again as you breathe in."]},{"id":"31B8DA0F","name":"Lying Neck Curls (Weighted)","primary":"neck","secondary":[],"equipment":"plate","type":"weight_reps","thumb":"assets/thumbs/10431201-Weighted-Lying-Neck-Flexion_neck_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/10431201-Weighted-Lying-Neck-Flexion_neck.mp4","howto":["Grab a weight plate and lie face up on a flat gym bench with your head over the edge.","Position the weight plate against your forehead and hold it with both hands.","Breathe in and lower your head to a comfortable level.","Flex the muscles on the front of your neck to raise your head as you exhale."]},{"id":"0910BD28","name":"Lying Neck Extension","primary":"neck","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/101671201-Lying-Neck-Extension_Neck_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/101671201-Lying-Neck-Extension_Neck_.mp4","howto":["Lie face down on a flat gym bench with your head over the edge.","Grab the back support for balance or place your hands on the ground.","Inhale and extend your neck back in one fluid motion. Exhale.","Lower your head as you breathe in, and repeat."]},{"id":"D6A73CF2","name":"Lying Neck Extension (Weighted)","primary":"neck","secondary":[],"equipment":"plate","type":"weight_reps","thumb":"assets/thumbs/10421101-Weighted-Lying-Neck-Extension_neck_small_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/10421201-Weighted-Lying-Neck-Extension_Neck_.mp4","howto":["Grab a weight plate and lie face down on a flat gym bench with your head over the edge.","Position the weight behind your head and hold it with both hands.","Inhale and lower your head until you feel a stretch at the back of your neck.","Extend your neck in one fluid motion to lift your head and exhale."]},{"id":"C732C341","name":"Meadows Rows (Barbell)","primary":"upper_back","secondary":["lats","biceps","forearms"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/40381201-Landmine-One-Arm-Bent-Over-Row_Back_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/40381201-Landmine-One-Arm-Bent-Over-Row_Back_.mp4","howto":["Set a barbell on a landmine attachment or place one end of the bar at a wall angle to serve as an anchor point.","Load the opposite side of the barbell with some weight.","Stand perpendicular to the loaded side of the bar (one side facing it).","Assume a staggered stance, bend forward, and grab the barbell sleeve with the hand closer to the bar.","Raise your torso enough for the loaded side of the barbell to lift an inch or two off the floor while your arm is straight.","Bring your shoulders back, take a breath, and pull the bar up and close to your side, squeezing your lat. Pull the weight until your elbow is at a 90-degree angle and the barbell sleeve is at torso level as you exhale.","Extend your arm slowly, breathing in on the way down. Don’t protract your shoulder (roll it forward) as you reach the bottom of each rep.","Once finished training one side, turn your body 180 degrees and do the same number of reps with your opposite arm."]},{"id":"F49E31D6","name":"Mountain Climber","primary":"full_body","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/06301201-Mountain-Climber_Cardio-FIX_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/06301201-Mountain-Climber_Cardio-FIX_.mp4","howto":["Get down on all fours. Have your hands and knees flat on the floor.","Straighten your leg to support your lower body on your toes.","Engage your abs and lift your buttocks several inches toward the ceiling.","Take a breath and tuck your right knee to your chest in one fluid motion. Exhale.","Extend the right leg as you breathe in.","Tuck your left knee to your chest and exhale.","Keep alternating and maintain a steady tempo from start to finish."]},{"id":"9F9C164B","name":"Muscle Up","primary":"full_body","secondary":[],"equipment":"machine","type":"reps_only","thumb":"assets/thumbs/51941201-Bodyweight-Muscle-Up-(VERSION-2)_Back_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/51941201-Bodyweight-Muscle-Up-(VERSION-2)_Back_.mp4","howto":["Stand underneath a pull-up bar, reach up, jump, and grab it with a double overhand grip (palms facing forward).","As you grab the bar, engage your abs, have your shoulder blades back, and keep your hips slightly flexed, legs straight, and feet together.","As your body beings to swing back, pull yourself up as powerfully as possible, aiming to bring your body back and around the pull-up bar. The momentum should carry you high enough for your chest to end up slightly above the bar.","Perform a straight bar dip to extend your elbows, exhaling near the top.","Lower yourself by bending your elbows and moving your body down from the bar.","Swing back and forth to create momentum and begin the next repetition just as your body starts swinging back."]},{"id":"F60BDDF8","name":"Negative Pull Up","primary":"lats","secondary":["upper_back","biceps","forearms"],"equipment":"none","type":"bodyweight_reps","thumb":"assets/thumbs/73851201-Pull-up-(negative)-(male)_Back_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/73851201-Pull-up-(negative)-(male)_Back_.mp4","howto":["Place a stool, gym bench, or plyo box underneath a pull-up bar.","Step on the object and grab the pull-up bar with an overhand grip (palms facing forward). Your elbows should be bent at roughly 90 degrees.","Take a deep breath and engage your abs.","Step off the object to suspend yourself in the air and slowly extend your arms against the force of gravity.","Once done, step on the sturdy object again and repeat."]},{"id":"108D7A14","name":"Nordic Hamstrings Curls","primary":"hamstrings","secondary":["glutes"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/77461201-Nordic-Hamstring-Curl-(male)_Thighs_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/77461201-Nordic-Hamstring-Curl-(male)_Thighs_.mp4","howto":["Get down on your knees and secure your feet underneath a loaded barbell or another sturdy object.","Bring your shoulders back, engage your abs, and squeeze your glutes.","You can have your arms to your sides or position your hands in front of your torso for support.","Take a breath and lower your torso to the floor by slowly extending your knees. Keep your hips stable and your glutes engaged.","Lower yourself as much as your strength allows and engage your posterior muscles to lift your torso to an upright position. Exhale near the top."]},{"id":"DBE341AA","name":"Oblique Crunch","primary":"abdominals","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/06351201-Oblique-Crunches-Floor_Waist_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/06351201-Oblique-Crunches-Floor_Waist.mp4","howto":["Lie on your right side, bend your knees, and stack your legs.","Place your left hand behind your head.","Take a breath and engage your top obliques to crunch your torso, lifting your right shoulder off the floor. Breathe out.","Lower your shoulder to the floor as you breathe in.","Repeat.","Once finished, lie on your left side and repeat for the same number of reps."]},{"id":"B140095E","name":"One Arm Push Up","primary":"chest","secondary":["shoulders","triceps"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/07251201-Single-Arm-Push-up_Chest_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/07251201-Single-Arm-Push-up_Chest.mp4","howto":["Get down on all fours.","Extend your legs and support your lower body on your toes. Spread your feet wider than hip-width distance.","Have your hands shoulder-width apart or slightly wider.","Engage your abs.","With your body tense and in position, lift one hand off the floor and bring it back behind your back.","Take a breath and lower yourself by bending your supporting arm. Go down as much as you can––ideally, until your chest is a couple of inches from the floor.","Extend your arm to get back to the starting position and exhale.","Once finished on one side, support your body on your other hand and do the same number of reps."]},{"id":"582ADA23","name":"Overhead Curl (Cable)","primary":"biceps","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/16361201-Cable-Overhead-Curl_Upper-Arms_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/16361201-Cable-Overhead-Curl_Upper-Arms.mp4","howto":["Set the pulleys of a double cable machine in the highest position.","Select the appropriate weight on both stacks and attach handles to the pulleys.","Grab the two handles and stand in the middle of the cable machine with your arms straight and to your sides.","Bring your shoulders back and engage your abs.","Simultaneously bend your arms, bringing the handles to the sides of your head as you breathe out.","Slowly extend your arms as you inhale."]},{"id":"4C6721B9","name":"Overhead Dumbbell Lunge","primary":"quadriceps","secondary":["hamstrings","glutes","shoulders","triceps","upper_back"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/50761201-Dumbbell-Overhead-Lunge_Thighs_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/50761201-Dumbbell-Overhead-Lunge_Thighs_.mp4","howto":["Grab a pair of dumbbells and stand tall.","Raise the weights overhead and straighten your arms.","Bring your shoulders back, engage your abs, and take a breath.","Extend your right leg forward, planting your foot on the floor.","Descend into a lunge until your front thigh is almost parallel to the floor.","Press through your front heel to extend your knee and bring your leg to the starting position as you exhale.","Take another breath and extend the opposite leg forward.","Alternate between left and right until you’re done."]},{"id":"54E60954","name":"Overhead Plate Raise","primary":"shoulders","secondary":["traps"],"equipment":"plate","type":"weight_reps","thumb":"assets/thumbs/101141201-Weighted-Plate-LU-Raise-(male)_Shoulders_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/101141201-Weighted-Plate-LU-Raise-(male)_Shoulders_.mp4","howto":["Put your middle and ring fingers through the center hole of a weight plate and curl them against the plate. Have your thumb, index finger, and pinky pressed firmly on the other side.","Grab a second weight plate in the same way with your other hand.","Stand tall, extend your arms, and have the weight plates at your sides with your wrists neutral (palms facing your body).","Bring your chest out, engage your abs, and breathe in.","Raise the plates to your sides and overhead in a smooth arc motion with your knuckles facing one another at the top. Exhale.","Slowly lower the plates to your sides in the same arc motion, breathing in on the way down.","Repeat."]},{"id":"7B8D84E8","name":"Overhead Press (Barbell)","primary":"shoulders","secondary":["triceps","abdominals"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/11651201-Barbell-Standing-Military-Press-(without-rack)_Shoulders_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/11651201-Barbell-Standing-Military-Press-(without-rack)_Shoulders.mp4","howto":["Position the barbell at collarbone height on a rack or stand.","Grab the bar with an overhand grip (palms facing down), keeping your hands roughly shoulder-width apart.","Tuck yourself underneath the bar, retract your shoulders, engage your abs, and take a breath.","Unrack the barbell and take a couple of steps back.","Have your feet hip-width apart and the barbell at upper chest level.","Take another breath and press the bar in a straight vertical line, moving your head slightly back.","Press until your arms are straight and exhale.","Lower the bar in the same straight line until it ends up at neck level. Breathe in on the way down.","Once finished, move forward and carefully rack the barbell."]},{"id":"6AC96645","name":"Overhead Press (Dumbbell)","primary":"shoulders","secondary":["triceps"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/04261201-Dumbbell-Standing-Overhead-Press_shoulder_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/04261201-Dumbbell-Standing-Overhead-Press_shoulder.mp4","howto":["Grab a pair of dumbbells and stand tall.","Bring your shoulders back, engage your abs, and squeeze your glutes.","Take a breath and lift the dumbbells to your sides. Bend your elbows at 90 degrees.","Inhale again and press the weights up and in, tapping them lightly at the top. Breathe out.","Lower the dumbbells to your sides and breathe in.","Stop when your elbows are slightly lower than your shoulders and initiate the next rep."]},{"id":"B09A1304","name":"Overhead Press (Smith Machine)","primary":"shoulders","secondary":["triceps"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/12241201-Smith-Standing-Shoulder-Press_Shoulders_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/12241201-Smith-Standing-Shoulder-Press_Shoulders.mp4","howto":["Position the Smith machine bar at collarbone height and add weight plates.","Stand in front of the bar and grab it with an even overhand grip. Your hands should be shoulder-width apart.","Bring your shoulders back, engage your abs, and take a breath.","Unrack the bar.","Take another breath and press the bar overhead, exhaling at the top.","Slowly lower the bar, breathing in on the way down."]},{"id":"2CFED196","name":"Overhead Squat","primary":"full_body","secondary":[],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/00691201-Barbell-Overhead-Squat_Thighs-FIX_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00691201-Barbell-Overhead-Squat_Thighs-FIX_.mp4","howto":["Grab a barbell with a double overhand grip. Use a wider grip, but not to the point of shoulder discomfort.","Raise the barbell overhead and straighten your arms.","Bring your shoulders back, engage your abs, and position your feet in a comfortable stance for squatting.","Take a breath and descend.","Keep your heels in contact with the floor and move down until your thighs are parallel to the floor.","Pause for a moment and press through your heels to drive yourself up.","Extend your knees and hips fully, exhaling near the top and keeping the barbell directly overhead."]},{"id":"B5EFBF9C","name":"Overhead Triceps Extension (Cable)","primary":"triceps","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/01941201-Cable-Overhead-Triceps-Extension-(rope-attachment)_Upper-Arms-FIX_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/01941201-Cable-Overhead-Triceps-Extension-(rope-attachment)_Upper-Arms-FIX_.mp4","howto":["Set the pulley at mid-thigh height, attach a rope, and select the correct load.","Grab both ends of the rope with an overhand grip (palms facing your body).","In one motion, turn away from the machine and dip slightly to raise the rope over your shoulders, positioning it behind your head. Your elbows should be bent and to the sides of your head.","With your chest out, lean forward slightly, bring one foot forward for balance, and brace your abs.","Breathe in and extend your elbows, spreading the rope at the top. Exhale.","Slowly bend your elbows as you breathe in."]},{"id":"FBEE8279","name":"Partial Glute Bridge (Barbell)","primary":"glutes","secondary":["hamstrings","adductors"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/108321201-Barbell-KAS-Glute-Bridge-(male)_Hips_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/108321201-Barbell-KAS-Glute-Bridge-(male)_Hips_.mp4","howto":["Sit down with a loaded barbell over your hips and your upper back positioned against the edge of a flat gym bench.","Grab the bar evenly for support and plant your feet flat on the floor with toes pointing slightly out.","Brace your abs, breathe in, and press your hips against the barbell.","Push through your heels and engage your glutes to raise the bar and your hips toward the ceiling.","Pause when your hips align with your upper body. Squeeze your glutes at the top and exhale.","Slowly lower your buttocks several inches as you breathe in. Keep your abs tense and stop when you notice that your knees begin to move back toward your hips.","Extend your hips again and exhale.","Do the required number of reps in this partial range of motion and lower your buttocks to the floor."]},{"id":"CE1054CE","name":"Pause Squat (Barbell)","primary":"quadriceps","secondary":["glutes","hamstrings"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/50161201-Barbell-Pause-Full-Squat_Thighs__thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/50161201-Barbell-Pause-Full-Squat_Thighs_.mp4","howto":["Set the barbell at collarbone height and add the appropriate amount of weight to it.","Place both hands evenly on the bar and grab it.","Tuck your head underneath and position your trapezius against the bar.","Engage your entire body and extend your knees to unrack the bar.","Take a couple of careful steps back, assume a comfortable squatting stance, take a deep breath, and engage your abs.","Squat to a comfortable depth and pause for two to three seconds.","Press through your heels to return to the top as you exhale."]},{"id":"018ADC12","name":"Pendlay Row (Barbell)","primary":"upper_back","secondary":["lats","biceps","forearms"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/30171201-Barbell-Pendlay-Row_Back_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/30171201-Barbell-Pendlay-Row_Back_.mp4","howto":["Stand in front of a barbell with your feet in a comfortable stance and your toes pointing slightly out.","Lean forward and grab the bar with a double overhand grip.","Bring your shoulders back to straighten your back. Your shoulders should be slightly in front of the barbell and higher than your hips.","Take a breath and row the barbell to your chest as you exhale.","Lower the barbell slowly and rest it on the floor as you breathe in.","Row the barbell from a dead stop."]},{"id":"30E293E3","name":"Pendulum Squat (Machine)","primary":"quadriceps","secondary":["glutes","hamstrings"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/49511201-Lever-Pendulum-Squat-(plate-loaded)_Thighs__thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/49511201-Lever-Pendulum-Squat-(plate-loaded)_Thighs_.mp4","howto":["Load the appropriate amount of weight plates.","Position yourself inside the machine, stepping on the platform with your upper back against the pads.","Have your feet in a comfortable squatting stance with your toes pointing slightly out.","Grab the handles at the sides of your head (or before you).","Retract your shoulder blades, engage your abs, and take a deep breath.","Fully extend your knees to lift the weight and use the handles to unrack it.","Squat slowly until your knees form a 90-degree angle, and pause briefly.","Press through your heels to return to the top position as you exhale."]},{"id":"0EFE8162","name":"Pike Pushup","primary":"shoulders","secondary":["triceps","chest"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/29211101-Pike-Push-up_Chest_small_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/29211201-Pike-Push-up_Chest.mp4","howto":["Get down on all fours. Have your knees and hands on the floor.","Straighten your legs and support your lower body on your toes.","Bring your buttocks back toward the ceiling to fold your body for the starting position.","Keep your shoulders back to maintain a neutral spine.","Take a breath and lower your body to the floor by bending your elbows.","Go down until your forehead is close to the floor, and press yourself back to the top as you exhale."]},{"id":"EC2510CD","name":"Pilates","primary":"full_body","secondary":[],"equipment":"none","type":"duration","thumb":"assets/thumbs/05071201-Jackknife-Sit-Up_Waist_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/05071201-Jackknife-Sit-Up_Waist_.mp4","howto":[]},{"id":"942BAD12","name":"Pinwheel Curl (Dumbbell)","primary":"biceps","secondary":["forearms"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/16571201-Dumbbell-Cross-Body-Hammer-Curl-(Version-2)_Upper-Arms-FIX_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/16571201-Dumbbell-Cross-Body-Hammer-Curl-(Version-2)_Upper-Arms-FIX.mp4","howto":["Grab a pair of dumbbells and stand tall with your shoulders back and chest out.","Position both dumbbells slightly in front of your thighs with your palms facing in and back.","Take a breath and curl one dumbbell in toward your chest until it comes slightly higher than your elbow. Breathe out.","Lower the dumbbell to the starting position, fully extending your arm. Breathe in on the way down.","Repeat with your other arm.","Keep alternating."]},{"id":"3FF6A22E","name":"Pistol Squat","primary":"quadriceps","secondary":["hamstrings","glutes"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/17591101-Single-Leg-Squat-(pistol)-male_Thighs_small_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/17591201-Single-Leg-Squat-(pistol)-(male)_Thighs-FIX2_.mp4","howto":["Stand tall with your arms extended forward, feet flat on the floor, shoulders back, and abs engaged.","Lift your left foot a few inches off the floor and take a breath.","Descend into a squat by bending your right knee. Allow your left leg to travel in front of your body.","Go down as low as possible––ideally, until your thigh is parallel to the floor.","Press through your right heel and move back to the top as you exhale.","Once finished training one side, plant your left foot on the floor, and do the same number of reps."]},{"id":"C6C9B8A0","name":"Plank","primary":"abdominals","secondary":[],"equipment":"none","type":"duration","thumb":"assets/thumbs/04631201-Front-Plank-m_waist_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/04631201-Front-Plank-m_waist.mp4","howto":["Get down on the floor.","Extend your body. Support your lower body on your toes and your upper body on your forearms.","Keep your shoulders neutral and abs engaged.","Hold the position for as long as possible, breathing steadily as you do."]},{"id":"31436F5D","name":"Plank Pushup","primary":"chest","secondary":["shoulders","triceps","abdominals"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/29781201-Elbow-Up-and-Down-Dynamic-Plank_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/29781201-Elbow-Up-and-Down-Dynamic-Plank.mp4","howto":["Get down on all fours.","Extend your legs and support your lower body on your toes.","Place your forearms flat on the floor with your elbows underneath your shoulders.","Engage your abs and take a breath.","Extend your arms one at a time by placing your hands flat on the floor and pushing yourself up, exhaling as you extend both arms.","Reverse the motion by placing your forearms flat on the floor as you breathe in.","Keep alternating between the two positions."]},{"id":"9283ABD5","name":"Plate Curl","primary":"biceps","secondary":["forearms"],"equipment":"plate","type":"weight_reps","thumb":"assets/thumbs/66981201-Weighted-Plate-Standing-Biceps-Curl-(male)_Forearm_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/66981201-Weighted-Plate-Standing-Biceps-Curl-(male)_Forearm.mp4","howto":["Grab the sides of a weight plate and position it in front of your hips.","Bring your shoulders back and engage your abs.","Take a breath and curl the plate until your wrists are slightly higher than your elbows. Exhale at the top.","Slowly extend your arms as you breathe in."]},{"id":"DBF9273A","name":"Plate Front Raise","primary":"shoulders","secondary":[],"equipment":"plate","type":"weight_reps","thumb":"assets/thumbs/08341201-Weighted-Front-Raise_Shoulders_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/08341201-Weighted-Front-Raise_Shoulders.mp4","howto":["Grab a weight plate and position your hands on the sides with your arms straight.","Bring your shoulders back, have your feet in a comfortable stance, look forward, and take a breath.","Engage your abs and lift the plate in front of your body while keeping your arms straight. Breathe out.","Slowly lower the plate to your hips as you breathe in."]},{"id":"982734D4","name":"Plate Press","primary":"chest","secondary":["shoulders","triceps"],"equipment":"plate","type":"weight_reps","thumb":"assets/thumbs/12251101-Standing-Plate-Presses_Shoulders_small_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/12251201-Standing-Plate-Press_Chest_.mp4","howto":["Grab a weight plate by its sides and lift it in front of your chest.","Have your feet in a comfortable stance, engage your abs, and retract your shoulder blades.","Take a breath and press the plate forward, fully extending your arms and exhaling.","Slowly bend your arms, bringing the plate to your chest as you breathe in."]},{"id":"9373FSD1","name":"Plate Squeeze (Svend Press)","primary":"chest","secondary":["shoulders","triceps"],"equipment":"plate","type":"weight_reps","thumb":"assets/thumbs/08561201-Weighted-Svend-Press_Chest_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/08561201-Weighted-Svend-Press_Chest.mp4","howto":["Grab a weight plate and stand tall.","Squeeze the plate flat between your hands and lift it to your chest.","Bring your shoulders back, engage your abs, and have your feet in a comfortable position.","Take a breath and press the plate forward until your arms are straight. Exhale.","Slowly bring the plate to your chest as you breathe in."]},{"id":"C628D768","name":"Power Clean","primary":"full_body","secondary":[],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/06481201-Power-Clean_Thighs_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/06481201-Power-Clean_Thighs.mp4","howto":["Stand in front of a loaded barbell with your feet underneath it and shins a couple of inches away.","Bend down and grab the barbell with an even, overhand grip.","Bring your chest out as much as possible. Your hips should be slightly higher than your knees in this position.","Initiate the first pull by deadlifting the barbell off the floor as you press your heels into the ground. Make the initial pull powerful.","Once the barbell travels above your knees, keep driving your hips forward as you begin pulling the weight in a straight vertical line. The sequence should happen in one smooth motion.","As the barbell travels up, squat, catch it, and have it land over your shoulders and upper chest.","As the barbell lands in a front rack position, squat up to the top, straightening your knees fully. Breathe out at the top.","Lower the barbell to the floor while keeping your back neutral."]},{"id":"E22F9358","name":"Power Snatch","primary":"full_body","secondary":[],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/15301101-Barbell-Power-Snatch_Weightlifts_small_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/15301201-Barbell-Power-Snatch_Weightlifts_.mp4","howto":["Stand in front of a loaded barbell.","Position your feet underneath the bar with your shins a couple of inches away.","Lean forward and grab the bar with a double overhand grip. Use a wide grip, but not to the point of shoulder discomfort.","Lower your hips to position your shins against the barbell and bring your chest out to straighten your back.","Take a breath and engage your abs.","Pull the bar in a straight line, keeping it close to your shins.","As soon as the bar passes your knees, initiate the second, more aggressive pull and simultaneously extend your hips.","With the bar traveling in a straight vertical line, engage your upper body to continue pulling the bar to chest level.","As soon as the bar is high enough, bend your knees to tuck under the weight and receive it in an overhead position with your arms straight.","Complete the repetition by extending your legs and exhaling.","Slowly lower the barbell to the floor while keeping it close to your body."]},{"id":"4F942934","name":"Preacher Curl (Barbell)","primary":"biceps","secondary":[],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/00701201-Barbell-Preacher-Curl_Upper-Arms_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00701201-Barbell-Preacher-Curl_Upper-Arms.mp4","howto":["Load the bar and adjust the seat height of the preacher bench. You should be able to place your upper arms on the pad and maintain an upright torso.","Position yourself over the machine, grab the bar with an even underhand grip (palms facing the ceiling), lift the bar, and sit down.","Bring your shoulders back, engage your abs, and breathe in.","Lower the bar until your arms are almost straight.","Lift the bar until your forearms are almost upright, and breathe out.","Extend your arms slowly as you breathe in."]},{"id":"FAB6EB2F","name":"Preacher Curl (Dumbbell)","primary":"biceps","secondary":[],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/04021201-Dumbbell-Seated-Preacher-Curl_Upper-Arms_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/04021201-Dumbbell-Seated-Preacher-Curl_Upper-Arms.mp4","howto":["Set the height of the preacher bench seat. You should be able to comfortably place the back of your upper arms against the pad.","Grab a pair of dumbbells and sit down.","Place your arms on the pad, bend your elbows, and have your wrists facing your body.","Engage your abs and take a breath.","Lower the dumbbells until your arms are straight.","Curl the weights to the top position, stopping when your forearms are almost upright. Breathe out."]},{"id":"1E9A6B8E","name":"Preacher Curl (Machine)","primary":"biceps","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/05921201-Lever-Preacher-Curl_Upper-Arms_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/05921201-Lever-Preacher-Curl_Upper-Arms.mp4","howto":["Select the appropriate load.","Adjust the seat’s height. You should be able to put your triceps against the pad while seated.","Sit down, extend your arms, and grab the handles.","Engage your abs and take a breath.","Bend your arms to lift the weight until your forearms are almost upright. Exhale at the top.","Slowly extend your arms as you breathe in."]},{"id":"84A77566","name":"Press Under","primary":"full_body","secondary":[],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/49661201-Press-Under_Weightlifting_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/49661201-Press-Under_Weightlifting_.mp4","howto":["Grab a barbell with a double overhand grip. Use a wide grip, but not to the point of shoulder discomfort.","Lift the barbell and position it on your upper back behind your neck.","Have your feet in a comfortable stance, bring your shoulders back, and engage your abs.","Inhale and simultaneously press the barbell overhead as you descend into a squat.","Move down until your thighs are parallel to the floor.","Press through your heels to straighten your legs and breathe out as you place the barbell on your upper back.","Inhale and repeat."]},{"id":"1B2B1E7C","name":"Pull Up","primary":"lats","secondary":["upper_back","biceps","forearms"],"equipment":"machine","type":"reps_only","thumb":"assets/thumbs/06521201-Pull-up_Back_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/06521201-Pull-up_Back.mp4","howto":["Stand underneath a pull-up bar.","Reach up and grab the bar with an even, overhand grip (palms facing forward). Have your hands slightly wider than shoulder level apart.","Bring your shoulders back and engage your abs.","Bend your knees to lift your feet off the floor and hang from the bar.","Take a breath and pull yourself up by bending your elbows.","Move up as much as possible––ideally, until your chin is over the pull-up bar. Exhale.","Lower yourself slowly by extending your elbows and breathe in on the way down."]},{"id":"2C37EC5E","name":"Pull Up (Assisted)","primary":"lats","secondary":["upper_back","biceps","forearms"],"equipment":"machine","type":"bodyweight_assisted_reps","thumb":"assets/thumbs/00171201-Assisted-Pull-up_Back_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00171201-Assisted-Pull-up_Back.mp4","howto":["Select the appropriate load on the pull-up machine.","Grab the pull-up bar with an overhand grip (palms facing forward).","Place your knees on the padded platform.","Bring your shoulders back, engage your abs, and take a breath.","Pull yourself up until your chin is slightly over the bar and exhale.","Lower yourself and fully straighten your arms as you breathe in."]},{"id":"56808FD2","name":"Pull Up (Band)","primary":"lats","secondary":["upper_back","biceps","forearms"],"equipment":"resistance_band","type":"bodyweight_assisted_reps","thumb":"assets/thumbs/29971201-Band-Assisted-Pull-Up-(VERSION-3)_Back_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/29971201-Band-Assisted-Pull-Up-(VERSION-3)_Back.mp4","howto":["Wrap a looped resistance band on a pull-up bar and let it hang.","Put your feet on the band loop one at a time as you grab the pull-up bar with an overhand grip. Your hands should be slightly more than shoulder-width apart.","With your body suspended, bring your shoulders back and take a breath.","Pull yourself up and bring your chin over the bar as you breathe out.","Pause at the top for a moment and slowly lower yourself, extending your arms fully. Breathe in as you move down."]},{"id":"729237D1","name":"Pull Up (Weighted)","primary":"lats","secondary":["upper_back","biceps","forearms"],"equipment":"machine","type":"bodyweight_reps","thumb":"assets/thumbs/08411201-Weighted-Pull-Up_Back_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/08411201-Weighted-Pull-Up_Back_.mp4","howto":["Attach a weight plate to yourself with a weight belt.","Reach up and grab the pull-up bar with an even overhand grip.","Bring your shoulders back, engage your abs, and take a breath.","Pull yourself up in one fluid motion and exhale at the top.","Lower yourself slowly and breathe in, keeping your feet off the floor."]},{"id":"67280085","name":"Pullover (Dumbbell)","primary":"lats","secondary":["chest","upper_back","triceps"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/03751201-Dumbbell-Pullover_Chest_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/03751201-Dumbbell-Pullover_Chest.mp4","howto":["Pick a dumbbell and set it on the floor next to a gym bench.","Position your upper back against the flat gym bench.","Bend your knees and have your feet flat on the floor.","Reach down and grab the dumbbell.","Position the weight over your torso with your hands flat against the top weight plate.","Bring your shoulders back, engage your abs, and inhale.","Lower the dumbbell behind your head while keeping your arms straight.","Hold for a moment and pull the dumbbell over to the starting position as you exhale."]},{"id":"B123DD01","name":"Pullover (Machine)","primary":"lats","secondary":["upper_back","chest","triceps"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/22851201-Lever-Pullover-(plate-loaded)_Back__thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/22851201-Lever-Pullover-(plate-loaded)_Back_.mp4","howto":["Add the appropriate load to the machine and adjust the seat height.","Sit down and place your lower triceps and elbows on the pads, with your hands grasping the handles for additional support.","Breathe in, engage your abs, and pull the weight down until your elbows are at your sides. Exhale.","Raise your arms to the starting overhead position as you breathe in."]},{"id":"542F3CD5","name":"Push Press","primary":"shoulders","secondary":["triceps","quadriceps"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/12001201-Push-Press_Shoulders_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/12001201-Push-Press_Shoulders.mp4","howto":["Have the barbell in a front rack position: your hands outside shoulder-width level with a full grip on the bar as it sits atop your shoulders.","Position your feet at roughly hip-width level with your toes pointed slightly out.","Take a deep breath and initiate the dip phase by bending your knees and hips as you keep your torso upright.","As you dip a few inches, change the direction by pushing through your heels to extend your knees and hips.","Use your lower body’s momentum to push through your torso and lift the bar off your shoulders.","Immediately push through your elbows to extend the bar overhead, exhaling at the top.","Slowly lower the barbell to the initial position, resting atop your shoulders as you breathe in."]},{"id":"392887AA","name":"Push Up","primary":"chest","secondary":["triceps","shoulders"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/06621201-Push-up-m_Chest_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/06621201-Push-up-m_Chest.mp4","howto":["Get down on all fours.","Extend your body into a push-up position. Have your hands flat on the floor, fingertips rotated slightly out, and shoulder blades retracted.","Have your legs straight and your toes supporting your lower body. Your ankles, knees, hips, and shoulders should be in a straight line.","Take a breath and lower yourself by bending your elbows.","Descend as low as possible––ideally, until your face is an inch or two from the floor.","Hold the bottom position for a moment and press yourself back to the top as you exhale."]},{"id":"19372ABC","name":"Push Up (Weighted)","primary":"chest","secondary":["triceps","shoulders"],"equipment":"none","type":"bodyweight_reps","thumb":"assets/thumbs/11721201-Assisted-Weighted-Push-up_Chest_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/11721201-Assisted-Weighted-Push-up_Chest.mp4","howto":["Get down on your knees and hands.","Straighten your legs and have your feet at a hip-width distance.","Position your hands slightly wider than shoulder-level apart, and keep your elbows tucked.","Engage your abs to ensure a neutral spine position.","Have someone place a weight plate on your mid-back.","Take a breath and lower yourself by bending your elbows.","Go down as much as your strength allows––ideally until your torso is a couple of inches from the floor.","Press yourself to the top, extending your elbows and exhaling.","Take another breath and repeat."]},{"id":"947DAC23","name":"Push Up - Close Grip","primary":"chest","secondary":["triceps","shoulders"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/02591201-Close-Grip-Push-up_Upper-Arms_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/02591201-Close-Grip-Push-up_Upper-Arms.mp4","howto":["Get down on your hands and knees.","Bring your hands close.","Extend your body into a push-up position. Your shoulders, hips, knees, and ankles should be aligned.","Bring your shoulders back and take a breath.","Descend by bending your elbows. Lower yourself as much as possible.","Hold the bottom position for a moment and press to bring yourself to the top as you exhale."]},{"id":"FE389074","name":"Rack Pull","primary":"upper_back","secondary":["glutes","hamstrings","lower_back","lats","traps"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/00741101-Barbell-Rack-Pull_Hips-FIX_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00741201-Barbell-Rack-Pull_Hips_.mp4","howto":["Set the bar at mid-shin height.","Stand in front of the bar and keep your shins an inch or two away.","Lean forward and grab the bar with your hands just outside your thighs.","Press your shins against the barbell and simultaneously push your knees slightly against your elbows.","Bring your chest out and arch your upper back.","Extend your hips as you engage your upper back and drag the barbell up against your shins and thighs. Breathe out at the top.","Initiate the descent by bringing your hips back. Lower the bar in the same straight line. Inhale on the way down or before the next rep."]},{"id":"C315DC2A","name":"Rear Delt Reverse Fly (Cable)","primary":"shoulders","secondary":["upper_back"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/02251201-Cable-Standing-Cross-over-High-Reverse-Fly_Shoulders_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/02251201-Cable-Standing-Cross-over-High-Reverse-Fly_Shoulders_.mp4","howto":["Set the pulleys of a double cable machine in the highest position and attach handles.","Select the appropriate weight and stand in the middle of the machine.","With your left shoulder facing the pulley, grab the handle with your right hand.","Walk to the pulley on your right and grab the handle with your left hand.","Stand in the middle of the machine, engage your abs, and extend your arms in front of your body.","Take a breath and spread your arms, squeezing your upper back muscles. Exhale.","Slowly bring your arms to the starting position as you breathe in."]},{"id":"E5988A0A","name":"Rear Delt Reverse Fly (Dumbbell)","primary":"shoulders","secondary":["upper_back"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/03801201-Dumbbell-Rear-Lateral-Raise_Shoulders-FIX_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/03801201-Dumbbell-Rear-Lateral-Raise_Shoulders-FIX_.mp4","howto":["Grab a pair of light dumbbells and have your feet at a hip-width distance.","Hinge at the hip to lean your torso forward and maintain a neutral spine.","Extend your arms and have your wrists neutral (facing one another).","Bring your shoulders back and take a breath.","Raise both dumbbells to the sides by engaging your posterior deltoids.","Lift until your elbows align with your shoulders and hold for a moment. Breathe out.","Lower the dumbbells to the starting position and breathe in."]},{"id":"D8281C62","name":"Rear Delt Reverse Fly (Machine)","primary":"shoulders","secondary":["upper_back"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/06021201-Lever-Seated-Reverse-Fly_Shoulders_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/06021201-Lever-Seated-Reverse-Fly_Shoulders.mp4","howto":["Select the appropriate load.","Adjust the seat height. The handles should be at shoulder level when you're seated.","Sit down and grab the handles with your palms facing down.","Bring your shoulders back and take a breath.","Extend your arms to your sides and back as you breathe out.","Bring your arms to the starting position as you breathe in."]},{"id":"1ADF8723","name":"Rear Kick (Machine)","primary":"glutes","secondary":["hamstrings"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/107771201-Lever-Pure-Rear-Kick-(male)_Hips_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/107771201-Lever-Pure-Rear-Kick-(male)_Hips_.mp4","howto":["Add the correct load and stand inside the machine with your front facing the chest pad and handles.","Position one shin against the bottom pad to create a more stable position and raise your opposite leg back with the foot flat against the footplate.","Lean forward and position your stomach and chest against the pad. Grab the handles.","Breathe in, engage your abs, and push the platform back and up in one smooth motion until your knee is fully extended. Exhale.","Slowly bend your knee as you breathe in. Push again and exhale.","Once finished training one side, switch leg positions and do the same number of reps."]},{"id":"7FD2EC3E","name":"Recumbent Bike","primary":"cardio","secondary":[],"equipment":"machine","type":"distance_duration","thumb":"assets/thumbs/21931201-Bicycle-Recline-Walk_Cardio_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/21931201-Bicycle-Recline-Walk_Cardio.mp4","howto":["Pull the lever underneath the seat to adjust it to the correct position. Your legs should be able to extend without your knees locking out.","Sit down, place your feet on the pedals, and select your resistance.","Grab the handles at the sides of the seat for support.","Begin to cycle with a sustainable pace and breathe steadily as you do."]},{"id":"1B89CA1B","name":"Renegade Row (Dumbbell)","primary":"upper_back","secondary":["lats","biceps","forearms"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/29801201-Dumbbell-Renegade-Row_Back-FIX_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/29801201-Dumbbell-Renegade-Row_Back-FIX_.mp4","howto":["Set a pair of hexagonal dumbbells parallel to one another and at a distance where you can grab them and perform push-ups.","Get down and grab both dumbbells. Extend your legs to straighten your body and bring your chest out. Your arms and body should be straight.","Space your feet apart for better balance.","Shift your weight slightly to the left.","Take a breath and row the right dumbbell until your elbow aligns with your torso. Exhale at the top.","Lower the weight to the starting position and breathe in.","Lean slightly to the right and row the left dumbbell.","Continue alternating until you're finished."]},{"id":"7952B5CD","name":"Reverse Crunch","primary":"abdominals","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/08721201-Reverse-Crunch-m_waist_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/08721201-Reverse-Crunch-m_waist.mp4","howto":["Lie on the floor, place your arms at your sides, and have your hands flat.","Bend your knees at a 90-degree angle and position them directly over your hips.","Take a breath, engage your abs, and bring your knees to your upper torso in one fluid motion, lifting your buttocks off the floor. Exhale.","Slowly bring your knees to the starting position and breathe in."]},{"id":"112FC6B7","name":"Reverse Curl (Barbell)","primary":"biceps","secondary":["forearms"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/00801201-Barbell-Reverse-Curl_Forearm_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00801201-Barbell-Reverse-Curl_Forearm.mp4","howto":["Grab a barbell with an overhand grip (palms facing your body).","Stand tall, have your feet in a comfortable stance, and retract your shoulder blades.","Engage your abs and take a breath.","Curl the barbell and bend your arms until your wrists are slightly higher than your elbows. Breathe out.","Slowly extend your arms as you breathe in."]},{"id":"9F48F858","name":"Reverse Curl (Cable)","primary":"biceps","secondary":["forearms"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/29541201-Cable-Standing-Reverse-Grip-Curl-(Straight-bar)_Fo_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/29541201-Cable-Standing-Reverse-Grip-Curl-(Straight-bar)_Fo.mp4","howto":["Select the appropriate load, set the pulley to the lowest position, and attach a straight bar.","Lean forward, grab the bar with an overhand grip (palms facing down), and stand up.","Take a step back to lift the weight off its stack.","Retract your shoulder blades and engage your abs.","Curl the weight in one fluid motion until your wrists are slightly higher than your elbows and exhale. Keep your elbows at your side.","Slowly extend your arms as you breathe in."]},{"id":"B567DD46","name":"Reverse Curl (Dumbbell)","primary":"biceps","secondary":["forearms"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/03821201-Dumbbell-Revers-grip-Biceps-Curl_Forearms_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/03821201-Dumbbell-Revers-grip-Biceps-Curl_Forearms.mp4","howto":["Grab a pair of dumbbells and stand tall.","Bring your arms in front of your body and have the dumbbells against your upper thighs. Your wrists should be pronated (palms facing your body).","Retract your shoulder blades, engage your abs, and take a breath.","Curl the dumbbells up until your wrists are slightly higher than your elbows, and breathe out.","Slowly extend your arms as you breathe in."]},{"id":"9264ADA1","name":"Reverse Fly Single Arm (Cable)","primary":"shoulders","secondary":["upper_back"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/98681201-Cable-45-degrees-Single-Arm-Reverse-Fly-(male)_Sho_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/98681201-Cable-45-degrees-Single-Arm-Reverse-Fly-(male)_Sho.mp4","howto":["Position a pulley at shoulder height and attach a handle.","Select the appropriate load, grab the handle with your right hand, and take a diagonal step to the right and back to lift the weight from its stack.","Bring your shoulders back, engage your abs, and breathe in.","Extend your arm to your right side and back, squeezing your shoulder muscle and breathing out.","Slowly bring your arm in front of your body as you breathe in.","Repeat.","Once finished, grab the handle with your left hand, take two steps to the left, and do the same number of reps."]},{"id":"1FF4097B","name":"Reverse Grip Concentration Curl","primary":"biceps","secondary":["forearms"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/04031201-Dumbbell-Seated-Revers-grip-Concentration-Curl_Forearms_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/04031201-Dumbbell-Seated-Revers-grip-Concentration-Curl_Forearms_.mp4","howto":["Grab a dumbbell and sit on the edge of a flat gym bench.","Spread your legs and have your feet flat on the floor.","Grab the dumbbell with your right hand and rotate the wrist in, having the palm facing in.","Place your right elbow against your inner thigh.","Take a breath and lift the dumbbell by bending your arm.","Lift until your wrist is slightly higher than your elbow and breathe out.","Extend your arm as you breathe in.","Once finished, do the same number of reps for your other side."]},{"id":"046E25A2","name":"Reverse Grip Lat Pulldown (Cable)","primary":"lats","secondary":["upper_back","biceps"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/02081201-Cable-Reverse-grip-Straight-Back-Seated-High-Row_Back_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/02081201-Cable-Reverse-grip-Straight-Back-Seated-High-Row_Back.mp4","howto":["Select the appropriate weight.","Adjust the pad height so your legs fit snugly.","Stand tall and grab the bar with an even underhand grip (palms facing back).","Sit down and bring your shoulders back.","Take a breath and pull the bar to your chest. Exhale immediately.","Extend your arms as you breathe in."]},{"id":"8B5BED30","name":"Reverse Grip Triceps Pushdown","primary":"triceps","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/16061201-Cable-Reverse-Grip-Triceps-Pushdown-(SZ-bar)_Upper-arms_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/16061201-Cable-Reverse-Grip-Triceps-Pushdown-(SZ-bar)_Upper-arms.mp4","howto":["Set the pulley to the highest position, attach a bar, and select your weight.","Grab the bar with your palms facing up.","Bring your elbows to your sides and take a step back to unrack the weight.","Slightly lean forward to clear room for full arm extension at the bottom position.","Bring your shoulders back, breathe in, and extend your arms as you exhale.","Slowly bend your arms until your wrists are slightly higher than your elbows and breathe in.","Repeat."]},{"id":"7C0028C3","name":"Reverse Hyperextension","primary":"glutes","secondary":["hamstrings","lower_back"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/05931201-Lever-Reverse-Hyperextension-(plate-loaded)_Hips_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/05931201-Lever-Reverse-Hyperextension-(plate-loaded)_Hips.mp4","howto":["Add the appropriate weight to the machine.","Adjust the foot pads to be against your Achilles heels when you lie on top of the machine.","Position yourself on the machine with your hips on the edge of the pad and grab the handles for support.","Secure your feet between the bottom pads.","Bring your shoulders back and take a breath.","Raise your legs up in one fluid motion until your body is straight, exhaling at the top.","Slowly lower your legs to the starting position as you breathe in."]},{"id":"C284D923","name":"Reverse Lunge","primary":"quadriceps","secondary":["hamstrings","glutes"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/15811201-Bodyweight-Rear-Lunge_Thighs_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/15811201-Bodyweight-Rear-Lunge_Thighs.mp4","howto":["Stand tall with your shoulders back, abs tight, and hands on your hips.","Have your feet in a comfortable stance with your toes pointing slightly out.","Take a breath and bring the right leg back, landing on the ball of the right foot. Sink into a lunge by bending your front leg. A good stride length is when your front shin remains relatively vertical (knee over ankle) as you descend.","Descend until your front thigh is almost parallel to the floor and your rear knee is an inch or two from the floor.","Pause at the bottom and engage your front leg to bring yourself back to the top.","Bring the right leg to the starting position and exhale.","Take another breath as you lunge back with your left leg.","Keep alternating."]},{"id":"818BA121","name":"Reverse Lunge (Barbell)","primary":"quadriceps","secondary":["hamstrings","glutes"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/00781201-Barbell-Rear-Lunge_Thighs_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00781201-Barbell-Rear-Lunge_Thighs_.mp4","howto":["Place a barbell on your back and hold it with both hands.","Stand tall with your shoulders back, abs engaged, and feet in a comfortable stance.","Take a breath and bring your right leg back, landing on the ball of the foot.","Sink into a controlled lunge by bending your front leg.","Descend until your front thigh is almost parallel to the floor and your rear knee is an inch or two from the floor. Your front shin should be relatively vertical as you move down.","Pause at the bottom and push through your front heel to extend your leg, bringing yourself to the top. Exhale.","Inhale again and lunge back with your left leg, landing on the ball of the foot.","Keep alternating until you finish the set."]},{"id":"FFDA283B","name":"Reverse Lunge (Dumbbell)","primary":"quadriceps","secondary":["glutes","hamstrings"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/03811201-Dumbbell-Rear-Lunge_Thighs_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/03811201-Dumbbell-Rear-Lunge_Thighs.mp4","howto":["Grab a pair of dumbbells and stand tall.","Have your feet in a comfortable stance, bring your shoulders back, and engage your abs.","Take a breath and bring the right leg back, landing on the ball of the right foot. Immediately sink into a lunge by bending your front leg.","Descend until your front thigh is almost parallel to the floor and your rear knee is an inch or two from the floor. A good stride length is when your front shin remains relatively vertical (knee over ankle) as you descend.","Pause at the bottom and engage your front leg to bring yourself back to the top as you exhale.","Take another breath and lunge back with your left leg, landing on the ball of your left foot.","Keep alternating."]},{"id":"99B49684","name":"Reverse Plank","primary":"abdominals","secondary":["triceps"],"equipment":"none","type":"duration","thumb":"assets/thumbs/08671201-Reverse-plank_Back_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/08671201-Reverse-plank_Back.mp4","howto":["Sit on the floor with your legs straight and feet together.","Extend your arms to your sides and behind your body. Keep your elbows straight, and place your palms flat on the floor.","With your hands planted firmly, contract your glutes and extend your hips toward the ceiling as you simultaneously raise your torso.","Have your head, neck, torso, and legs in a straight line. Keep your arms straight and look up.","Keep your glutes and midsection engaged, breathe steadily, and hold the plank position.","Once you’re done, drop your buttocks to the floor and take a break."]},{"id":"D8460FA6","name":"Reverse Wrist Curl (Dumbbell)","primary":"forearms","secondary":[],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/03851201-Dumbbell-Reverse-Wrist-Curl_Forearms_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/03851201-Dumbbell-Reverse-Wrist-Curl_Forearms_.mp4","howto":["Grab a pair of dumbbells and sit on a flat gym bench.","Place your elbows and forearms on your thighs with palms facing down. Your wrists should be just in front of your knees and the weights hanging.","Breathe in and extend your wrists, lifting the dumbbells up. Breathe out at the top.","Slowly lower the weights as you breathe in.","Repeat."]},{"id":"51A0EDAA","name":"Ring Dips","primary":"chest","secondary":["shoulders","triceps"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/06771201-Ring-Dip_Upper-Arms_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/06771201-Ring-Dip_Upper-Arms_.mp4","howto":["Adjust the height of the rings to be at roughly stomach level.","Stand between the rings and grab them with both hands.","Keep your arms straight and elbows close to your body.","Bring your shoulders back, engage your abs, and squeeze your glutes.","Take a breath and raise your feet off the floor one at a time.","Once you're confident that you're stable enough, take another breath and bend your arms.","Lower yourself gradually until your elbows are somewhat bent, and you feel a stretch in your chest.","Press through your triceps and return to the top as you exhale. Avoid explosive movements because these can lead to instability."]},{"id":"5F09F0FC","name":"Ring Pull Up","primary":"lats","secondary":["upper_back","biceps","forearms"],"equipment":"other","type":"reps_only","thumb":"assets/thumbs/55221201-Ring-Pull-Up_Back_1_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/55221201-Ring-Pull-Up_Back_.mp4","howto":["Secure a pair of rings and set them at pull-up bar height.","Reach up and grab the rings with an overhand grip (palms facing forward).","Bring your shoulders back and down and engage your abs.","Bend your knees or bring your feet slightly forward to suspend yourself in the air.","Breathe in and pull yourself up in one fluid motion. Exhale at the top.","Slowly extend your arms as you breathe in."]},{"id":"AEA56BDC","name":"Ring Push Up","primary":"chest","secondary":["shoulders","triceps"],"equipment":"other","type":"reps_only","thumb":"assets/thumbs/08061201-Suspended-Push-Up_Chest_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/08061201-Suspended-Push-Up_Chest_.mp4","howto":["Secure a pair of rings and set them just an inch or two above the ground.","Get down on your knees and grab the rings.","Bring your shoulders back and flex your triceps, chest, and abs for maximum stability.","Extend your legs to assume a push-up position. Support your lower body on your toes.","Flex your glutes for additional stability.","Breathe in and slowly lower yourself to the ground while keeping your elbows close to your torso.","Descend as much as your strength allows and push back to the top as you exhale.","Breathe in and repeat."]},{"id":"2B4B7310","name":"Romanian Deadlift (Barbell)","primary":"hamstrings","secondary":["glutes","lower_back","upper_back","lats"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/00851201-Barbell-Romanian-Deadlift_Hips-FIX_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00851201-Barbell-Romanian-Deadlift_Hips-FIX_.mp4","howto":["Grab a barbell with a double overhand grip (palms facing back). Your hands should be shoulder-width apart.","Stand tall, retract your shoulder blades, engage your abs, and have your feet in a comfortable stance.","Take a breath and lean forward by bringing your buttocks back (hinging at the hip). Your back should be neutral from start to finish.","Lower the bar in a straight vertical line, keeping it close to your body. You should feel a stretch in your hamstrings.","Straighten your body by driving your hips forward and exhale near the top."]},{"id":"72CFFAD5","name":"Romanian Deadlift (Dumbbell)","primary":"hamstrings","secondary":["glutes","lower_back","upper_back","lats"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/14591201-Dumbbell-Romanian-Deadlift_Hips_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/14591201-Dumbbell-Romanian-Deadlift_Hips.mp4","howto":["Grab a pair of dumbbells and stand tall.","Position the weights in front of your hips with your palms facing your body.","Bring your shoulders back, position your feet a few inches apart, and take a breath.","Lean your torso forward by hinging at the hip. Your back should remain neutral, and you should feel a stretch in your posterior thigh muscles.","Lower the dumbbells in a straight line until they are below knee level.","Extend your hips forward and exhale."]},{"id":"0B9B92BA","name":"Romanian Deadlift (Smith Machine)","primary":"hamstrings","secondary":["glutes","lower_back","upper_back","lats"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/15971201-Smith-Stiff-Legged-Deadlift_Hips_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/15971201-Smith-Stiff-Legged-Deadlift_Hips_.mp4","howto":["Set the bar at mid-thigh height and add your weight.","Stand close to the bar, almost pressing your thighs against it. Your feet should be hip-width apart.","Grab the bar with an overhand grip - palms facing back. Have your hands roughly shoulder-width apart.","Unrack the bar and stand tall.","Bring your shoulders back, engage your abs, and breathe in.","Slowly lower the bar by leaning your torso forward and pushing your buttocks back. You should feel tension at the back of your thighs.","Lean forward until your torso is almost parallel to the floor and drive your hips forward to stand up, exhaling at the top.","Breathe in on the way down and repeat."]},{"id":"234897AB","name":"Rope Cable Curl","primary":"biceps","secondary":["forearms"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/01651201-Cable-Hammer-Curl-(with-rope)-(male)_Forearms_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/01651201-Cable-Hammer-Curl-(with-rope)-(male)_Forearms_.mp4","howto":["Set the pulley in the lowest position and attach a rope.","Select the appropriate weight on the cable machine.","Bend forward and grab both ends of the rope with a neutral grip (palms facing one another).","Stand tall, bring your shoulders back, and step back to lift the weight from its stack.","Take a breath and curl the cable by bending your elbows.","Lift until your wrists are slightly higher than your elbows, and breathe out.","Extend your arms slowly and breathe in."]},{"id":"9273BA17","name":"Rope Straight Arm Pulldown","primary":"lats","secondary":["triceps"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/02371201-Cable-Straight-Arm-Pulldown-(with-rope)_Back_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/02371201-Cable-Straight-Arm-Pulldown-(with-rope)_Back.mp4","howto":["Select the appropriate load.","Set the pulley to the highest position and attach a rope.","Grab both ends of the rope with your hands neutral (facing one another) and straighten your arms.","Take a step back, engage your abs, and retract your shoulders.","Take a breath and pull the rope to your hips while keeping your arms straight. Breathe out.","Slowly bring the rope to the top as you breathe in."]},{"id":"0222DB42","name":"Rowing Machine","primary":"cardio","secondary":[],"equipment":"machine","type":"distance_duration","thumb":"assets/thumbs/11611201-Rowing-(with-rowing-machine)_Cardio_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/11611201-Rowing-(with-rowing-machine)_Cardio.mp4","howto":["Select the appropriate resistance and sit down.","Reach forward and grab the cable attachment.","Bend your knees and place your feet flat on the footplates.","With your arms straight, inhale and push yourself back by engaging your thigh muscles.","As you move back, row the cable to your torso and exhale.","Extend your arms and bend your knees simultaneously to bring yourself back to the starting position as you breathe in."]},{"id":"AC1BB830","name":"Running","primary":"cardio","secondary":[],"equipment":"none","type":"distance_duration","thumb":"assets/thumbs/52301201-Long-Distance-Running_Cardio_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/52301201-Long-Distance-Running_Cardio_.mp4","howto":["Stand tall with your shoulders back.","Move forward and aim for a midfoot strike: landing the middle of your foot on the ground.","Keep your arms bent and hands relaxed.","Move your arms in sync with your feet in a natural way.","Land lightly on your feet, but avoid bouncing up and down as you move forward.","Keep your torso upright, core engaged, and gaze directed a few feet in front of you.","Maintain a steady breath, aiming to inhale through the nose and exhale through the mouth."]},{"id":"BB83BDDE","name":"Russian Twist (Bodyweight)","primary":"abdominals","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/06871201-Russian-Twist_waist_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/06871201-Russian-Twist_waist.mp4","howto":["Sit down on the floor.","Bend your knees and have your feet flat on the ground.","Bring your arms in front of your torso and lean back as you engage your abs.","Take a breath and twist your torso to the right, holding for a moment and exhaling.","Immediately rotate your torso to the starting position as you breathe in.","Twist to the left and breathe out.","Keep alternating."]},{"id":"2982AA23","name":"Russian Twist (Weighted)","primary":"abdominals","secondary":[],"equipment":"plate","type":"weight_reps","thumb":"assets/thumbs/23711201-Weighted-Russian-Twist_Waist_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/23711201-Weighted-Russian-Twist_Waist.mp4","howto":["Grab a weight plate or dumbbell and sit on the floor.","Bend your knees and plant your feet flat on the ground. You can secure your feet under a bench or have a friend hold them down.","Grab the weight, position it in front of your torso, and extend your arms.","Lean your torso slightly back and engage your abs.","Take a breath and move the weight to the right, twisting your torso in that direction as you exhale.","Bring the weight to the starting position as you breathe in.","Twist to the left and exhale.","Keep alternating."]},{"id":"C7AE420A","name":"Scapular Pull Ups","primary":"upper_back","secondary":["lats","forearms"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/06881201-Scapular-Pull-Up_Back_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/06881201-Scapular-Pull-Up_Back_.mp4","howto":["Grab a pull-up bar with an even overhand grip (palms facing forward).","Engage your abs and lift your feet off the floor to suspend yourself in the air.","As you hang from the bar, keep your abs and glutes engaged to remain still and not swing back and forth.","Take a breath and initiate the scapular pull-up by bringing your shoulders back and down. Keep your arms straight. Doing so will elevate your body slightly.","Hold the retracted position for a second or two as you breathe out.","Relax your body and allow your shoulders to move forward and up, breathing in as you do."]},{"id":"DF3BDB9C","name":"Seal Row (Barbell)","primary":"upper_back","secondary":["lats","biceps","forearms"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/87981201-Barbell-Lying-Seal-Row-on-Rack_Back_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/87981201-Barbell-Lying-Seal-Row-on-Rack_Back_.mp4","howto":["Load the bar and lie face down on the seal row bench with your body straight.","Grab the bar with an overhand grip (palms facing back) at roughly shoulder-width level.","Unrack the bar and bring it underneath your chest. Let your arms hang straight down and fully extended.","Bring your shoulders back, engage your abs, and pull the bar while keeping your elbows tucked in.","Pull until your elbows are at torso level and exhale.","Slowly lower the barbell to the starting position as you breathe in.","Repeat."]},{"id":"7E93E23F","name":"Seal Row (Dumbbell)","primary":"upper_back","secondary":["lats","biceps","forearms"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/105721201-Dumbbell-Lying-Seal-Row-on-Rack_Back_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/105721201-Dumbbell-Lying-Seal-Row-on-Rack_Back_.mp4","howto":["Place your weights within arm’s reach.","Lie face down on a seal row bench or elevated gym bench (for instance, elevated with two plyometric boxes) with your body straight.","Grab the dumbbell and let your arms hang straight down and fully extended.","Bring your shoulders back, engage your abs, and pull the dumbbells while keeping your elbows tucked in.","Pull until your elbows are at torso level and exhale.","Slowly lower the weights to the starting position as you breathe in.","Repeat."]},{"id":"F1D60854","name":"Seated Cable Row - Bar Grip","primary":"upper_back","secondary":["lats","biceps","forearms"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/01801201-Cable-Low-Seated-Row_Back_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/01801201-Cable-Low-Seated-Row_Back.mp4","howto":["Select the appropriate load and sit down.","Reach ahead and grab the bar evenly.","Sit back and position your feet on the footplates.","Bring your shoulders back and engage your abs.","Take a breath and pull the handle attachment to your upper stomach. Breathe out.","Hold for a moment and extend your arms fully as you breathe in."]},{"id":"C3BCABB3","name":"Seated Cable Row - Bar Wide Grip","primary":"upper_back","secondary":["lats","traps","biceps","forearms"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/02181201-Cable-Seated-Wide-grip-Row_Back_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/02181201-Cable-Seated-Wide-grip-Row_Back.mp4","howto":["Attach a curved bar to a seated cable row machine.","Select the appropriate weight.","Sit down, place your feet on the platform, and bend your knees slightly.","Lean forward and grab the bar with a double overhand grip (palms facing down).","Lean back to lift the weight from its stack, engage your abs, and retract your shoulder blades.","Take a breath and row the bar to your stomach, squeezing your back and breathing out.","Slowly extend your arms and breathe in."]},{"id":"0393F233","name":"Seated Cable Row - V Grip (Cable)","primary":"upper_back","secondary":["lats","biceps","forearms"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/26611201-Cable-Seated-Row-with-V-bar_Back_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/26611201-Cable-Seated-Row-with-V-bar_Back.mp4","howto":["Attach a V-handle to a seated row machine and select the appropriate weight.","Sit down and grab the handle with both hands.","Place your feet on the platform and sit back. Maintain a slight bend in your knees.","Retract your shoulder blades and engage your abs. Keep your torso upright, and don't lean too far back.","Take a deep breath and pull the handle to your stomach in one fluid motion, pausing briefly and exhaling.","Slowly extend your arms as you breathe in."]},{"id":"062AB91A","name":"Seated Calf Raise","primary":"calves","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/05941201-Lever-Seated-Calf-Raise-(plate-loaded)_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/05941201-Lever-Seated-Calf-Raise-(plate-loaded).mp4","howto":["Load the machine, sit down, and adjust the pad. Your thighs should fit snugly, allowing you to unrack the weight by extending your ankles.","Position your thighs against the pad and grab the handles firmly.","Take a breath and unrack the weight by flexing your calves.","Put the safety bar to the side and flex your ankles to lower the weight until you feel a stretch in your calves.","Press through the balls of your feet and flex your calves, exhaling near the top."]},{"id":"6B4C797E","name":"Seated Chest Flys (Cable)","primary":"chest","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/38691101-Cable-Seated-Chest-Fly_Chest_small_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/38691201-Cable-Seated-Chest-Fly_Chest_.mp4","howto":["Select the same weight on both stacks of a double cable machine.","Set both pulleys at the same height––roughly stomach level.","Attach handles to both pulleys and position an upright bench facing away and in front of the cable machine.","Grab the handles one by one, walk over to the gym bench, and sit down.","Extend your arms in front of your body, retract your shoulder blades, inhale, and squeeze your abs.","Slowly bring your arms to your sides until you feel a stretch in your chest muscles.","Bring your hands together and flex your chest as you exhale."]},{"id":"5122E7D9","name":"Seated Dip Machine","primary":"triceps","secondary":["chest","shoulders"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/14511201-Lever-Seated-Dip_Upper-Arms_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/14511201-Lever-Seated-Dip_Upper-Arms.mp4","howto":["Select the appropriate load.","Sit down and grab the handles to your sides.","Plant your feet on the floor, bring your shoulders back, and engage your abs.","Take a breath and press the handles down, fully extending your arms and exhaling.","Bend your arms as you breathe in."]},{"id":"8BAB2735","name":"Seated Incline Curl (Dumbbell)","primary":"biceps","secondary":[],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/03151201-Dumbbell-Incline-Biceps-Curl_Upper-Arms_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/03151201-Dumbbell-Incline-Biceps-Curl_Upper-Arms.mp4","howto":["Adjust a gym bench to an incline of 65 to 75 degrees.","Grab a pair of dumbbells and sit down and back.","Have your arms straight and to your sides, with your palms facing one another.","Bring your shoulders back, engage your abs, and take a breath.","Curl both dumbbells, rotating your wrists out, and exhale. Lift the weights until your wrists are slightly higher than your elbows. Your palms should face the ceiling at the top position.","Extend your arms slowly as you breathe in."]},{"id":"C01F58D1","name":"Seated Incline Hammer Curl (Dumbbell)","primary":"biceps","secondary":["forearms"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/03201201-Dumbbell-Incline-Hammer-Curl_Upper-Arms_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/03201201-Dumbbell-Incline-Hammer-Curl_Upper-Arms.mp4","howto":["Adjust a gym bench to an incline of 65 to 75 degrees.","Grab a pair of dumbbells and sit down and back.","Have your arms straight and to your sides, with your palms facing one another.","Bring your shoulders back, engage your abs, and take a breath.","While maintaining a neutral wrist position, curl both dumbbells and exhale at the top. Lift the weights until your wrists are slightly higher than your elbows.","Extend your arms slowly as you breathe in."]},{"id":"9372FFAA","name":"Seated Lateral Raise (Dumbbell)","primary":"shoulders","secondary":[],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/03961201-Dumbbell-Seated-Lateral-Raise_shoulder_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/03961201-Dumbbell-Seated-Lateral-Raise_shoulder.mp4","howto":["Grab a pair of light dumbbells and sit at the edge of a flat gym bench.","Hold a dumbbell in each hand, have your arms at your sides, and bring your palms to a neutral position (facing your body).","Bring your shoulders back and engage your abs.","Inhale and raise the dumbbells to your sides until they are at shoulder level. Breathe out.","Slowly lower the weights to your sides as you breathe in."]},{"id":"11A123F3","name":"Seated Leg Curl (Machine)","primary":"hamstrings","secondary":["calves"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/05991201-Lever-Seated-Leg-Curl_Thighs_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/05991201-Lever-Seated-Leg-Curl_Thighs.mp4","howto":["Select the appropriate load.","Adjust the pad position. It should be against your Achilles' heels as you sit down.","Sit down, position the back of your lower legs against the pad, and grab the handles at your sides.","Bring your shoulders back, engage your abs, and inhale.","Bend your knees by contracting your hamstrings and breathe out.","Hold for a moment and slowly extend your knees as you breathe in."]},{"id":"91AF29E0","name":"Seated Overhead Press (Barbell)","primary":"shoulders","secondary":["triceps"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/68771201-Barbell-Incline-Shoulders-Press-(inside-squat-cage_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/68771201-Barbell-Incline-Shoulders-Press-(inside-squat-cage.mp4","howto":["Position an upright gym bench inside a squat rack.","Place the barbell on the rack and sit on the bench. You should be able to reach and unrack the barbell while seated and with your arms slightly bent.","Plant your feet on the floor.","Reach up and grab the barbell with an even overhand grip (palms facing forward). Your hands should be roughly shoulder-width apart.","Engage your abs, take a breath, and carefully unrack the bar.","Bring the bar to your chest, lean back into the bench, and bring your chest out.","Take another breath and press the bar overhead, exhaling as you reach the top.","Lower the bar to collarbone level as you breathe in. Your elbows should be slightly lower than your shoulders at the bottom position.","Press the barbell again.","Once finished, carefully rack the bar."]},{"id":"9930DF71","name":"Seated Overhead Press (Dumbbell)","primary":"shoulders","secondary":["triceps"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/02901201-Dumbbell-Bench-Seated-Press_Shoulders_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/02901201-Dumbbell-Bench-Seated-Press_Shoulders.mp4","howto":["Grab a pair of dumbbells and sit on a flat gym bench or plyo box.","Place the weights on your thighs, bring your shoulders back, and engage your abs.","In one motion, thrust the weights and position them to your sides.","Take a breath and press the dumbbells overhead, tapping them at the top as you exhale.","Slowly lower the dumbbells until your elbows are slightly lower than your shoulders, breathing in on the way down."]},{"id":"1006DF48","name":"Seated Palms Up Wrist Curl","primary":"forearms","secondary":[],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/04011201-Dumbbell-Seated-Palms-Up-Wrist-Curl_Forearms_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/04011201-Dumbbell-Seated-Palms-Up-Wrist-Curl_Forearms_.mp4","howto":["Grab a pair of light dumbbells and sit on a flat gym bench.","Place your forearms on your thighs with your wrists just in front of your knees.","Take a breath and lower the dumbbells by extending your wrists.","Immediately lift the weights by flexing your forearm muscles. Hold the top position for a moment and exhale."]},{"id":"1DF4A847","name":"Seated Row (Machine)","primary":"upper_back","secondary":["lats","biceps","forearms"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/22651201-Lever-Seated-Row-(version-2)_Back_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/22651201-Lever-Seated-Row-(version-2)_Back.mp4","howto":["Select the appropriate load.","Sit down and grab the handles with a neutral grip (hands facing one another).","Bring your shoulders back and engage your abs.","Take a breath and pull the handles simultaneously.","Squeeze your back as you breathe out.","Extend your arms slowly and breathe in."]},{"id":"9237BAD1","name":"Seated Shoulder Press (Machine)","primary":"shoulders","secondary":["triceps"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/14541201-Lever-Seated-Shoulder-Press_Shoulders_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/14541201-Lever-Seated-Shoulder-Press_Shoulders.mp4","howto":["Select the appropriate load.","Sit down and bring your shoulder blades into the back support.","Plant your feet flat on the floor.","Grab the handles to your sides and keep your palms facing forward.","Take a breath and engage your abs.","Press the weight straight up until your arms are fully extended. Breathe out at the top.","Lower the weight to the starting position and breathe in."]},{"id":"234BC743","name":"Seated Triceps Press","primary":"triceps","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/18711201-Lever-Triceps-Dip-(plate-loaded)_Upper-Arms-FIX_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/18711201-Lever-Triceps-Dip-(plate-loaded)_Upper-Arms-FIX_.mp4","howto":["Set the appropriate weight and sit down.","Grab the handles at your sides with a comfortable grip.","Bring your shoulders back, take a breath, and squeeze your abs.","Push the handles down until your elbows lock out and breathe out.","Slowly bend your arms as you breathe in."]},{"id":"95F2E076","name":"Seated Wrist Curl (Barbell)","primary":"forearms","secondary":[],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/01261201-Barbell-Wrist-Curl_Forearms_1_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/01261201-Barbell-Wrist-Curl_Forearms_.mp4","howto":["Grab a straight bar with an underhand grip (palms facing forward) and sit on a flat gym bench.","Widen your foot stance and place your elbows and forearms flat on the bench with your wrists at the edge.","Breathe in and curl your wrists to raise the bar in one fluid motion.","Pause briefly at the top as you exhale.","Slowly lower the bar as you breathe in.","Repeat."]},{"id":"9202CC23","name":"Seated Wrist Extension (Barbell)","primary":"forearms","secondary":[],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/00791201-Barbell-Revers-Wrist-Curl-II_Forearms_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00791201-Barbell-Revers-Wrist-Curl-II_Forearms.mp4","howto":["Grab a loaded bar with an overhand grip (palms facing your body).","Sit on the edge of a flat gym bench and plant your feet on the floor.","Position your forearms on top of your thighs with your wrists in front of your knees.","Take a breath and lower the barbell in front of your knees by flexing your wrists.","Lift the bar by extending your wrists and exhale."]},{"id":"878CD1D0","name":"Shoulder Press (Dumbbell)","primary":"shoulders","secondary":["triceps"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/04051201-Dumbbell-Seated-Shoulder-Press_Shoulders_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/04051201-Dumbbell-Seated-Shoulder-Press_Shoulders.mp4","howto":["Set an adjustable gym bench at a close to 90-degree angle (almost upright back support).","Grab a pair of dumbbells and sit down.","Place the weights on top of your thighs.","Bring your shoulders back, engage your abs, and take a breath.","Lift the dumbbells and kick them up with your thighs.","Position the weights to your sides.","Take another breath and press the dumbbells up and in, tapping them at the top as you exhale.","Lower the dumbbells until your elbows are slightly lower than your shoulders, breathing in on the way down."]},{"id":"059E835D","name":"Shoulder Press (Machine Plates)","primary":"shoulders","secondary":["triceps"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/05871201-Lever-Military-Press-(plate-loaded)_shoulder_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/05871201-Lever-Military-Press-(plate-loaded)_shoulder.mp4","howto":["Add the appropriate amount of weight to the machine, ensuring it’s equal on both sides.","Adjust the seat height. Your elbows should be slightly lower than your shoulders as you grab the handles when you sit down.","Sit down and grab the handles.","Lean back and retract your shoulder blades.","Take a deep breath and engage your abs.","Press the weight up in one fluid motion and exhale at the top.","Slowly lower the weight as you breathe in."]},{"id":"502FCE31","name":"Shoulder Taps","primary":"shoulders","secondary":["chest","triceps"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/06991201-Shoulder-Tap-Push-up_Plyometrics_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/06991201-Shoulder-Tap-Push-up_Plyometrics.mp4","howto":["Get down on your hands and knees.","Extend your legs and support your lower body on your toes.","Plant your hands flat on the floor at roughly shoulder-width distance.","Engage your abs to straighten your body and retract your shoulder blades.","Inhale and descend by bending your elbows. Go down as much as possible and press through your palms to move to the top.","Immediately lift your left hand off the floor and tap your right shoulder as you exhale.","Bring the hand to the floor and do another push-up as you breathe in on the way down.","Lift your right hand to tap your left shoulder.","Keep alternating."]},{"id":"0B841777","name":"Shrug (Barbell)","primary":"traps","secondary":["neck"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/00951201-Barbell-Shrug_Back_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00951201-Barbell-Shrug_Back.mp4","howto":["Grab a barbell with an overhand grip (palms facing back). Your hands should be just outside your thighs.","Straighten your arms, engage your abs, and retract your shoulder blades.","Take a breath and shrug the barbell by elevating your shoulders, exhaling at the top. Imagine that you’re trying to touch your ears with your trapezius.","Lower your shoulder blades as you breathe in."]},{"id":"FFABC123","name":"Shrug (Cable)","primary":"traps","secondary":["neck"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/02201201-Cable-Shrug_Back_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/02201201-Cable-Shrug_Back.mp4","howto":["Set the pulley to the lowest position and attach a straight bar.","Select the appropriate weight.","Lean forward and grab the straight bar with an overhand grip (palms facing your body).","Stand up and step back to lift the weight off its stack.","Bring your shoulders back, squeeze your glutes, and engage your abs.","Take a breath and shrug, lifting your shoulder blades. Exhale at the top.","Slowly lower your shoulder blades as you breathe in."]},{"id":"ABEC557F","name":"Shrug (Dumbbell)","primary":"traps","secondary":["neck"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/04061201-Dumbbell-Shrug_Back_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/04061201-Dumbbell-Shrug_Back.mp4","howto":["Grab a pair of dumbbells, stand tall, position your arms to your sides, and have your wrists neutral.","Bring your shoulders back and engage your abs.","Take a breath, shrug your shoulders as high as possible, and squeeze your trapezius muscle at the top. Keep your arms straight.","Exhale at the top and lower your shoulder blades to the starting position as you breathe in."]},{"id":"19A38071","name":"Shrug (Machine)","primary":"traps","secondary":["neck"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/06041201-Lever-Shrug-(plate-loaded)_Back_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/06041201-Lever-Shrug-(plate-loaded)_Back.mp4","howto":["Add the appropriate load to the machine.","Stand between the handles, grab them, and stand tall.","With your arms straight and at your sides, take a deep breath and engage your abs.","Shrug your shoulders up in one fluid motion, exhaling at the top. Don’t bend your elbows.","Lower your shoulder blades as you breathe in."]},{"id":"742E5BD5","name":"Shrug (Smith Machine)","primary":"traps","secondary":["neck"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/07461201-Smith-Back-Shrug_Back_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/07461201-Smith-Back-Shrug_Back.mp4","howto":["Position the Smith machine bar at hip height and add weight.","Face away from the bar and grab it with an overhand grip (palms facing back).","Engage your abs and take a breath.","Rotate the bar to unrack it.","Shrug your shoulders as high as possible and squeeze your traps at the top as you breathe out.","Lower your shoulder blades and breathe in.","Once finished, rotate the bar to rack it on the Smith machine."]},{"id":"37F9EDA7","name":"Side Bend","primary":"abdominals","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/00021201-45-Side-Bend_Waist_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00021201-45-Side-Bend_Waist.mp4","howto":["Stand sideways on a back hyperextension machine. Your right upper thigh should be against the pad, and your feet should be secure.","Engage your abs and place your hands behind your head.","Take a breath and bend your torso to the right.","Squeeze your obliques to bend your torso to the left and exhale.","Once finished, rotate your body 180 degrees and do the same number of reps."]},{"id":"026FD047","name":"Side Bend (Dumbbell)","primary":"abdominals","secondary":[],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/04071201-Dumbbell-Side-Bend_Waist_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/04071201-Dumbbell-Side-Bend_Waist.mp4","howto":["Grab a dumbbell with your right hand and stand tall with your arm to your side. Place your left hand behind your head.","Engage your abs and bring your shoulders back.","Take a breath and crunch your torso to the left. Exhale.","Extend your torso and breathe in.","Crunch again.","Once finished, grab the dumbbell with the opposite hand and do the same number of reps."]},{"id":"E3EDA509","name":"Side Plank","primary":"abdominals","secondary":[],"equipment":"none","type":"duration","thumb":"assets/thumbs/07151201-Side-Plank-m_Waist_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/07151201-Side-Plank-m_Waist.mp4","howto":["Lie on your left side.","Place your left forearm on the floor for balance.","Stack your legs and bring one foot over the other.","Take a breath and engage your midsection to lift your hips off the floor.","Hold the position for 30 to 60 seconds and relax.","Turn to your other side and hold the same position."]},{"id":"8372BBCC","name":"Single Arm Cable Crossover","primary":"chest","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/62191201-Cable-Standing-Single-Arm-Fly_Chest_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/62191201-Cable-Standing-Single-Arm-Fly_Chest_.mp4","howto":["Set the pulley at chest height and attach a handle.","Select the appropriate load.","Grab the handle, step away from the machine, and turn your side to it. The cable pulley should be to your side and slightly behind your body.","Bring your shoulders back, breathe in, and engage your abs.","With your arm slightly bent and to the side, bring the cable in front of your torso. Squeeze your chest and exhale.","Slowly bring your arm to the side and breathe in.","Once finished, grab the handle with your other hand, have the pulley at your side and slightly behind your body, and do the same number of reps."]},{"id":"D0C4A899","name":"Single Arm Cable Row","primary":"upper_back","secondary":["lats","biceps","forearms"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/75641201-Cable-Split-Stance-Single-Arm-Row-(male)_Back_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/75641201-Cable-Split-Stance-Single-Arm-Row-(male)_Back_.mp4","howto":["Set a cable pulley in a low position or at chest level and attach a handle.","Select the appropriate load, grab the handle, and step back to lift the weight off its stack.","Bring your shoulders back, stagger your stance, bend your knees slightly, engage your abs, and breathe in.","Pull the handle to your side, aligning your elbow to your torso. Squeeze your back and hold the position for a moment and exhale.","Slowly extend your arm and breathe in.","Once you have finished training one side, grab the handle with your opposite hand and repeat for the same number of reps."]},{"id":"B33B526E","name":"Single Arm Curl (Cable)","primary":"biceps","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/01901201-Cable-One-Arm-Curl_Upper-Arms_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/01901201-Cable-One-Arm-Curl_Upper-Arms.mp4","howto":["Select the appropriate weight, set the pulley to the lowest position, and attach a handle.","Grab the handle with your right hand and position the palm up.","Take a step back, inhale, and squeeze your abs.","Curl the weight and squeeze your bicep at the top momentarily as you exhale.","Slowly extend your arm as you breathe in.","Once finished, grab the handle with your left hand and repeat."]},{"id":"1837BA23","name":"Single Arm Landmine Press (Barbell)","primary":"shoulders","secondary":["triceps","chest"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/50941201-Landmine-Single-Arm-Press_Shoulders_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/50941201-Landmine-Single-Arm-Press_Shoulders_.mp4","howto":["Anchor one end of a barbell on a landmine attachment.","Add a weight plate on the opposite barbell sleeve.","Lean forward and grab the loaded side with both hands.","Carefully lift the bar to chest level and stand tall.","Bring your shoulders back, engage your abs, and raise your left arm to your side.","Take a breath and press the bar forward and up until your arm is straight. Exhale at the top.","Slowly lower the bar to your upper chest as you breathe in.","Once finished training one side, grab the bar with your left hand and do the same number of reps."]},{"id":"2EE45F81","name":"Single Arm Lat Pulldown","primary":"lats","secondary":["upper_back","biceps","forearms"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/12041101-Cable-one-arm-lat-pulldown_back_small_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/12041201-Cable-one-arm-lat-pulldown_back.mp4","howto":["Select the appropriate weight and attach a handle to the pulley.","Adjust the knee pad to a height where your thighs fit snugly underneath.","Stand tall, reach up, and grab the handle with one hand.","Sit down and secure your thighs underneath the pad.","With your arm straight, retract your shoulder blades, engage your midsection, and inhale.","Pull the cable down and in until you feel a contraction on your back. Keep your elbow in line with your torso and close to your body.","Hold for a moment as you exhale.","Slowly extend your arm as you breathe in before the next rep.","Once finished, stand tall, grab the handle with your other hand, and do the same number of reps."]},{"id":"DE68C825","name":"Single Arm Lateral Raise (Cable)","primary":"shoulders","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/01921201-Cable-One-Arm-Lateral-Raise_Shoulders-3_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/01921201-Cable-One-Arm-Lateral-Raise_Shoulders.mp4","howto":["Select the appropriate load, set the pulley to the lowest position, and attach a handle.","Stand with your left side facing the cable attachment and grab the handle with your right hand.","Take a lateral step away to lift the weight off its stack and maintain a slight bend in your right arm.","Breathe in, engage your abs, and lift your arm to the side until the wrist and elbow align with your shoulder. Exhale at the top.","Slowly lower your arm as you breathe in.","Once finished training one side, turn your body 180 degrees, grab the handle with your left hand, and repeat."]},{"id":"8347DFD1","name":"Single Arm Tricep Extension (Dumbbell)","primary":"triceps","secondary":[],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/03621201-Dumbbell-One-Arm-Triceps-Extension-(on-bench)_Upper-Arms_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/03621201-Dumbbell-One-Arm-Triceps-Extension-(on-bench)_Upper-Arms.mp4","howto":["Grab a dumbbell and sit on a flat gym bench or chair.","Lift the weight overhead and straighten your arm.","Bring your shoulders back, engage your midsection, and inhale.","Lower the dumbbell behind your head while keeping your elbow steady.","Bend your arm until you feel a stretch in your tricep, and extend your elbow as you exhale.","Once finished, grab the weight with your other hand, and do the same number of reps."]},{"id":"552AB030","name":"Single Arm Triceps Pushdown (Cable)","primary":"triceps","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/50331201-Cable-Single-Arm-Triceps-Pushdown-(rope-attachment_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/50331201-Cable-Single-Arm-Triceps-Pushdown-(rope-attachment.mp4","howto":["Select the appropriate load, set the pulley to the highest position, and attach a rope.","Grab the rope with your right hand, position your elbow to your side, and step back.","Grab the cable machine's pillar with your left hand, take a deep breath, and engage your abs.","Slowly extend your arm and flex your triceps as you exhale.","Bend your arm as you breathe in.","Once finished, grab the rope with your left hand and repeat."]},{"id":"629AE73D","name":"Single Leg Extensions","primary":"quadriceps","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/71081201-Lever-Seated-Leg-Extension-(VERSION-2)_Thighs_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/71081201-Lever-Seated-Leg-Extension-(VERSION-2)_Thighs_.mp4","howto":["Select the appropriate load on a leg extension machine.","Set the pad to be just over your feet as you sit down.","Adjust the back support to have your knees just in front of the edge of the seat.","Sit down, position one leg against the pad, grab the handles to your sides, bring your shoulders back, and inhale.","Extend your leg fully and exhale.","Bend the leg as you inhale.","Once finished training one side, position your opposite shin against the pad, and do the same number of reps."]},{"id":"CBC0D834","name":"Single Leg Glute Bridge","primary":"glutes","secondary":["hamstrings","quadriceps"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/60001201-Single-Leg-Bridge-with-Outstretched-Leg-(left)-(ma_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/60001201-Single-Leg-Bridge-with-Outstretched-Leg-(left)-(ma.mp4","howto":["Place an exercise mat and lie down with your arms to your sides and hands flat on the floor.","Bend your knees and place your feet flat on the floor.","Raise one leg in the air.","Take a breath and press through the heel of your planted foot, engaging your posterior chain to drive your hips toward the ceiling.","Extend your hips until they align with your knee and shoulders, and exhale at the top.","Lower your buttocks to the floor, breathing in on the way down.","Switch feet position and do the same number of reps for your opposite side."]},{"id":"487B3755","name":"Single Leg Hip Thrust","primary":"glutes","secondary":["hamstrings","quadriceps"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/20711101-Single-Leg_Hip-Thrusts_Hips_small_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/20711201-Single-Leg_Hip-Thrusts_Hips_.mp4","howto":["Sit on the floor with your back against a flat gym bench.","Bring your arms to your sides and place them flat on the gym bench.","Bend your knees and have your feet flat on the floor.","Lift one foot off the floor, take a breath, and engage your abs.","Press through your other foot and extend your hips until they align with your torso. Breathe out.","Lower your buttocks to the floor as you breathe in.","Once finished, plant the opposite foot on the floor and do the same number of reps."]},{"id":"D1CD146F","name":"Single Leg Hip Thrust (Dumbbell)","primary":"glutes","secondary":["hamstrings","quadriceps"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/47551101-Dumbbell-Single-Leg-Hip-Thrust_Hips_small_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/80751201-Dumbbell-Single-Leg-Hip-Thrust_Hips_.mp4","howto":["Place a dumbbell next to a flat gym bench.","Sit on the floor, position your upper back against the bench's edge, grab the weight, and place it over your hips.","Bend your right knee and plant the foot on the floor. Keep your left leg straight.","Take a deep breath, engage your abs, and push through your right heel to drive your hips toward the ceiling. Hold the dumbbell with both hands for safety.","Pause briefly at the top as you exhale.","Lower your buttocks to the floor as you breathe in.","Repeat.","Once finished training your right side, plant your left foot on the floor and extend your right leg. Repeat for the same number of reps."]},{"id":"3FD83744","name":"Single Leg Press (Machine)","primary":"quadriceps","secondary":["glutes","hamstrings"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/26111201-Lever-Horizontal-One-leg-Press_Hips_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/26111201-Lever-Horizontal-One-leg-Press_Hips.mp4","howto":["Set the appropriate load on the machine and sit down.","Place one foot flat on the platform and grab the handles to your sides. Keep your other foot on the floor.","Engage your abs and take a breath.","Extend your leg and remove the safety.","Slowly bend your knee, bringing yourself close to the platform as you breathe in.","Press through your heel and extend your leg as you exhale.","Once finished training one leg, place the opposite foot on the platform and do the same number of reps."]},{"id":"93472AC1","name":"Single Leg Romanian Deadlift (Barbell)","primary":"hamstrings","secondary":["glutes","lower_back","upper_back","lats"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/17561201-Barbell-Single-Leg-Deadlift_Hips_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/17561201-Barbell-Single-Leg-Deadlift_Hips_.mp4","howto":["Grab a barbell with a double overhand grip (palms facing back). Your hands should be shoulder-width apart.","Stand tall with your feet close, back straight, shoulders back, and abs engaged.","Take a breath and lean forward by hinging at the hip. Simultaneously raise your right foot off the floor, bringing the right leg back for balance.","Lean forward until you feel a stretch in your left hamstring. Lower the barbell in a straight line, keeping it close to your body.","Straighten your body and bring your right leg forward as you exhale.","Take another breath and repeat.","Once finished training one side, do the same number of reps by raising your left foot and extending the leg back."]},{"id":"937292AB","name":"Single Leg Romanian Deadlift (Dumbbell)","primary":"hamstrings","secondary":["glutes","lower_back"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/97541201-Dumbbell-Single-Leg-Romanian-Deadlift-Leg-Raise-(m_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/97541201-Dumbbell-Single-Leg-Romanian-Deadlift-Leg-Raise-(m.mp4","howto":["Hold a dumbbell in one hand and position it in front of your upper thigh.","Raise your right foot off the floor and support yourself on the left.","Bring your shoulders back, engage your abs, and breathe in.","Slowly lean your torso forward by hinging at the hips. Allow your right leg to move behind your body for balance.","Lean forward until you feel a stretch at the back of your left thigh.","Straighten your body, squeeze your glutes, and exhale.","Once finished, plant your right foot on the floor, lift your left one in the air, and do the same number of reps."]},{"id":"238BA231","name":"Single Leg Standing Calf Raise","primary":"calves","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/50521201-Single-Leg-Calf-Raise-Off-Step_Calves_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/50521201-Single-Leg-Calf-Raise-Off-Step_Calves_.mp4","howto":["Place the ball of your right foot on an elevated platform and grab onto something for balance.","Bring your shoulders back, engage your abs, and straighten your right leg.","Take a breath and lower your heel to the floor by flexing your ankle.","Move down until you feel a stretch in your calve and press through your heel to extend your ankle.","Squeeze your calf at the top and exhale.","Once finished, place the ball of your opposite foot on the platform and do the same number of reps."]},{"id":"E51CCBE5","name":"Single Leg Standing Calf Raise (Barbell)","primary":"calves","secondary":[],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/101691201-Barbell-Standing-Single-Leg-Calf-Raise_Calves_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/101691201-Barbell-Standing-Single-Leg-Calf-Raise_Calves_.mp4","howto":["Place a loaded barbell on your back, similar to how you would for the squat.","Position the ball of one foot on an elevated platform. Keep your other foot on the platform for balance.","Bring your shoulders back, flex your abs, and take a breath.","Extend your ankle, squeezing your calve muscle at the top. Breathe out.","Flex your ankle to lower yourself to the starting position as you breathe in.","Once finished, position the ball of your other foot on the platform and repeat for the same number of reps."]},{"id":"5DA40761","name":"Single Leg Standing Calf Raise (Dumbbell)","primary":"calves","secondary":[],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/04091201-Dumbbell-Single-Leg-Calf-Raise_Calves_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/04091201-Dumbbell-Single-Leg-Calf-Raise_Calves.mp4","howto":["Hold a dumbbell in your left hand and place the ball of your right foot on an elevated platform. Keep your left foot in the air.","Grab onto something for balance with your right hand.","Engage your abs, take a breath, and straighten your right leg.","Press through the ball of your foot to elevate yourself and squeeze your calf as you breathe out.","Slowly lower your body by flexing your ankle and breathe in. You should feel a stretch in your calves.","Repeat.","Once finished, place the ball of your left foot on the platform and do the same number of reps."]},{"id":"B05C2C29","name":"Single Leg Standing Calf Raise (Machine)","primary":"calves","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/100761201-Lever-Standing-Single-Leg-Calf-Raise_Calves_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/100761201-Lever-Standing-Single-Leg-Calf-Raise_Calves_.mp4","howto":["Select the appropriate load on the machine.","Place the ball of your right foot on the platform and position your shoulders against the pads. Keep your leg straight.","Grab the handles for support, engage your abs, and take a breath.","Push through the ball of your foot to extend your ankle and squeeze your calve muscle as you breathe out.","Slowly lower your ankle to the floor, stretching your calf. Breathe in on the way down.","Once finished training your right calve, place your left foot on the platform and repeat for the same number of reps."]},{"id":"F5DEF1EB","name":"Sissy Squat (Weighted)","primary":"quadriceps","secondary":[],"equipment":"none","type":"weight_reps","thumb":"assets/thumbs/08511201-Weighted-Sissy-Squat_Thighs_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/08511201-Weighted-Sissy-Squat_Thighs.mp4","howto":["Grab a weight plate, lift it in front of your chest, and hold it with one arm.","Stand before a gym bench or another object you can hold onto for balance.","Grab the object for support.","Have your feet a few inches apart, engage your abs, and take a breath.","Descend into a squat while simultaneously leaning your torso back.","As you move down, allow your heels to lift off the floor and support yourself on the balls of your feet.","Go down as much as possible, feeling your quadriceps stretch.","Engage your quadriceps to straighten your legs and stand tall. Exhale near the top."]},{"id":"022DF610","name":"Sit Up","primary":"abdominals","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/00011201-3-4-Sit-up_Waist_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00011201-3-4-Sit-up_Waist.mp4","howto":["Place an exercise mat on the floor and lie on it.","Bend your knees and plant your feet flat on the floor.","Position your hands in front of your face or behind your head.","Take a breath and crunch your torso by engaging your abs, lifting your upper body to an upright position.","Breathe out at the top position and slowly lower your torso as you breathe in."]},{"id":"9237BA12","name":"Sit Up (Weighted)","primary":"abdominals","secondary":[],"equipment":"none","type":"bodyweight_reps","thumb":"assets/thumbs/47561201-Dumbbell-Sit-up_Waist_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/47561201-Dumbbell-Sit-up_Waist_.mp4","howto":["Place a dumbbell or weight plate on the floor and lie next to it.","Bend your knees and plant your feet flat on the floor.","Grab the weight and position it over your chest.","Take a breath and crunch your torso by engaging your abs, lifting your torso to an upright position. Exhale.","Hold for a moment and lower your torso slowly as you breathe in."]},{"id":"24A809EF","name":"Skating","primary":"cardio","secondary":[],"equipment":"none","type":"duration","thumb":"assets/thumbs/109801201-Inline-Skating-(male)_Plyometrics_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/109801201-Inline-Skating-(male)_Plyometrics_.mp4","howto":[]},{"id":"5D99A2FA","name":"Ski Erg","primary":"cardio","secondary":[],"equipment":"machine","type":"distance_duration","thumb":"assets/thumbs/21421201-Ski-Ergometer_Cardio_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/21421201-Ski-Ergometer_Cardio_.mp4","howto":["Select the appropriate resistance, preferably 50-60% of the maximum.","Reach up, grab the two handles, and step back slightly to clear enough room for pulling.","Position your feet shoulder-width apart or slightly wider.","With your elbows bent, breathe in, and initiate the pull by engaging your core and pushing your buttocks back.","As you pull on the cables, use the initial momentum by continuing to hinge at the hips, driving the handles down by fully extending your arms, and breathing out.","Allow the cables to return to the starting position as you stand up and breathe in for the next rep.","Continue breathing, pulling, hinging at the hips, and standing up in a controlled, rhythmic manner."]},{"id":"84325755","name":"Skiing","primary":"cardio","secondary":[],"equipment":"none","type":"duration","thumb":"assets/thumbs/55391201-Ski-Runners-(male)_Plyometrics_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/55391201-Ski-Runners-(male)_Plyometrics_.mp4","howto":[]},{"id":"875F585F","name":"Skullcrusher (Barbell)","primary":"triceps","secondary":[],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/00601201-Barbell-Lying-Triceps-Extension-Skull-Crusher_Upper-Arms_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00601201-Barbell-Lying-Triceps-Extension-Skull-Crusher_Upper-Arms.mp4","howto":["Load a straight bar, lift it off the floor, and support it in front of your chest.","Carefully sit on a flat gym bench and lie back while keeping the bar close to your torso.","Extend your arms and bring your shoulders back. Plant your feet on the floor.","Take a breath and lower the barbell to your forehead or behind your head.","Pause for a moment and extend your arms while keeping your elbows in position. Exhale near the top."]},{"id":"68F8A292","name":"Skullcrusher (Dumbbell)","primary":"triceps","secondary":[],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/03511201-Dumbbell-Lying-Triceps-Extension_Upper-Arms-FIX_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/03511201-Dumbbell-Lying-Triceps-Extension_Upper-Arms-FIX_.mp4","howto":["Grab a pair of dumbbells and lie on a flat gym bench.","Straighten your arms and position the dumbbells over your chest with your wrists neutral (hands facing one another).","Bring your shoulders back, engage your abs, and plant your feet flat on the floor.","Take a breath and slowly bend your elbows to bring the dumbbells to the sides of your head.","Hold the position momentarily and extend your arms by squeezing your triceps. Exhale near the top."]},{"id":"7D1BD41D","name":"Sled Pull","primary":"full_body","secondary":[],"equipment":"other","type":"short_distance_weight","thumb":"assets/thumbs/99391201-Power-Sled-Pull-(male)_Back_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/99391201-Power-Sled-Pull-(male)_Back_.mp4","howto":["Grab the rope attached to the sled with both hands.","Stand up with your feet hip-width apart.","Push your buttocks back and lean slightly forward to maintain a neutral spine position.","Pull the rope with your right hand.","As your elbow gets to the side of your torso, immediately pull with your left hand and place your right hand further down on the rope, ready for the next pull. To breathe effectively, inhale while switching hands, just before initiating each pull, and exhale as you pull.","Keep alternating steadily, switching hands as you pull, and maintain a consistent tempo."]},{"id":"7757171F","name":"Sled Push","primary":"full_body","secondary":[],"equipment":"other","type":"distance_duration","thumb":"assets/thumbs/44281201-Power-Sled-Push-(male)_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/44281201-Power-Sled-Push-(male).mp4","howto":["Load a sled with the appropriate amount of weight.","Lean forward, grab the two handles, and straighten your arms.","Bring your shoulders back, engage your abs, and have the balls of your feet on the ground.","Take a breath and press through the balls of your feet to move forward.","Move forward slowly, pressing through your feet. Breathe steadily and go for as long as possible."]},{"id":"FB09C938","name":"Snatch","primary":"full_body","secondary":[],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/15331101-Barbell-Snatch_Weightlifts_small_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/15331201-Barbell-Snatch_Weightlifts_.mp4","howto":["Stand in front of a loaded barbell. Your feet should be underneath the bar, and your shins should be a couple of inches away.","Lean forward and grab the bar with a wide snatch grip.","Lower your hips, bring your shoulders back to straighten your back, and adjust yourself to the bar. Your knees should extend over the bar.","Engage your abs and take a breath.","Powerfully drive through your heels as if trying to squat the weight.","As the barbell glides close to your body and reaches your hips, press through your heels for a second time, powerfully extending your knees and hips. Simultaneously, pull the bar up in a vertical line.","Drop by bending your knees and receive the barbell overhead with your arms straight.","Press through your heels to perform an overhead squat and exhale at the top.","Lower the barbell to the floor, keeping it close to your body."]},{"id":"911A58D3","name":"Snowboarding","primary":"cardio","secondary":[],"equipment":"none","type":"duration","thumb":"","video":"","howto":[]},{"id":"2348AB72","name":"Spider Curl (Barbell)","primary":"biceps","secondary":[],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/00721201-Barbell-Prone-Incline-Curl_Upper-Arms_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00721201-Barbell-Prone-Incline-Curl_Upper-Arms.mp4","howto":["Set the incline of a gym bench at roughly 45 degrees.","Position yourself on the bench with your stomach and chest flat against the back support.","Reach down and grab the barbell with an even underhand grip (palms facing forward). Alternatively, have someone hand you the bar.","Engage your abs and take a breath.","Curl the barbell while keeping your elbows stationary.","Bend your arms until your wrists are higher than your elbows. Squeeze your biceps and breathe out.","Slowly lower the barbell and fully extend your arms as you breathe in."]},{"id":"90427D4A","name":"Spider Curl (Dumbbell)","primary":"biceps","secondary":[],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/03741201-Dumbbell-Prone-Incline-Curl_Upper-Arms_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/03741201-Dumbbell-Prone-Incline-Curl_Upper-Arms.mp4","howto":["Set a gym bench at a 45 to 60-degree incline.","Grab a pair of dumbbells and sit on the bench with your chest and stomach against the back support. Your arms should hang down with your palms facing forward.","Take a deep breath and curl both dumbbells, not moving your elbows forward. Exhale at the top.","Extend your arms as you breathe in."]},{"id":"C10A5AC9","name":"Spiderman","primary":"abdominals","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/48791201-Spiderman-Plank_Waist_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/48791201-Spiderman-Plank_Waist_.mp4","howto":["Get down on all fours and extend your body in an elbow plank position.","Have your forearms flat on the floor, supporting your upper body, and your legs extended with your toes supporting your lower body.","Keep your buttocks slightly elevated, back neutral, and abs engaged for support.","Take a breath, tuck your right knee to your right elbow, and exhale.","Bring your knee back to the starting position as you breathe in.","Tuck your left knee to your left elbow.","Continue alternating between left and right until you finish the set."]},{"id":"213AB238","name":"Spinning","primary":"cardio","secondary":[],"equipment":"machine","type":"duration","thumb":"assets/thumbs/22791201-Stationary-Bike-Run-(version-4)_Cardio_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/22791201-Stationary-Bike-Run-(version-4)_Cardio.mp4","howto":["Adjust the seat height and get on top of the cardio machine.","Select the appropriate program and grab the handles.","Place your feet flat on the pedals, bring your shoulders back, and direct your gaze forward.","Cycle steadily and maintain a steady breath."]},{"id":"E764B907","name":"Split Jerk","primary":"full_body","secondary":[],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/15381101-Barbell-Split-Jerk_Weightlifts_small_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/15381201-Barbell-Split-Jerk_Weightlifts_.mp4","howto":["Hold a barbell at neck level with your arms wide.","Bring your shoulders back, engage your abs, and have your feet in a comfortable stance.","Take a breath and descend a few inches by bending your knees.","Push through your heels and immediately thrust the barbell overhead.","Immediately split your stance, bringing your dominant leg forward and the non-dominant one back to receive the barbell.","Position your feet in line and slowly lower the barbell to neck level as you exhale."]},{"id":"20C1A3CB","name":"Split Squat (Dumbbell)","primary":"quadriceps","secondary":["hamstrings","glutes"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/29601201-Dumbbell-Split-Squat_Thighs_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/29601201-Dumbbell-Split-Squat_Thighs.mp4","howto":["Grab a pair of dumbbells and stand tall.","Retract your shoulder blades, engage your abs, and bring your right leg forward, planting the foot flat on the ground.","Take a breath and bend your right knee to descend into a split squat.","Descend until your back knee taps the floor and press through your front heel to straighten your right leg. Exhale near the top.","Once finished training your right leg, bring your left leg forward and do the same number of reps."]},{"id":"9283BABA","name":"Sprints","primary":"cardio","secondary":[],"equipment":"none","type":"distance_duration","thumb":"assets/thumbs/52161201-Sprint_Cardio_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/52161201-Sprint_Cardio_.mp4","howto":[]},{"id":"F1258206","name":"Squat (Band)","primary":"quadriceps","secondary":["hamstrings","glutes"],"equipment":"resistance_band","type":"weight_reps","thumb":"assets/thumbs/10041201-Band-squat_Hips_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/10041201-Band-squat_Hips.mp4","howto":["Take a large looped resistance band and step over it with both feet.","Have your feet in a comfortable stance for squatting.","Grab the opposite side of the band, raise it overhead, and place it behind your neck.","Stand tall, bring your shoulders back, engage your abs, and breathe in.","Descend until your thighs are parallel to the floor.","Hold for a moment and press through your heels to bring yourself to the top. Exhale."]},{"id":"D04AC939","name":"Squat (Barbell)","primary":"quadriceps","secondary":["hamstrings","glutes"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/00431201-Barbell-Full-Squat_Thighs_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00431201-Barbell-Full-Squat_Thighs.mp4","howto":["Position the barbell at collarbone height.","Grab the bar with an even overhand grip (palms facing down).","Tuck yourself underneath the bar and place it on top of your trapezius (upper back).","Align your feet, engage your abs, take a breath, and unrack the bar by straightening your legs.","Take a couple of careful steps back and bring your feet shoulder-width apart.","Bring your shoulders back, inhale, and squat until your thighs are parallel to the floor. Keep your heels in contact with the floor.","Hold for a moment and press through your heels to bring yourself back to the top. Exhale near the top.","Once finished, move forward and rack the barbell carefully before relaxing your body."]},{"id":"9694DA61","name":"Squat (Bodyweight)","primary":"quadriceps","secondary":["hamstrings","glutes"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/11971201-Squat-m_Thighs_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/11971201-Squat-m_Thighs.mp4","howto":["Stand tall with your feet in a comfortable stance, shoulders back, and gaze directed forward.","Lift your arms in front of you for balance and take a breath.","Squat and keep your heels in contact with the floor.","Move down until your thighs are parallel to the ground.","Push through your heels to bring yourself to the top and exhale."]},{"id":"DCFF3E9F","name":"Squat (Dumbbell)","primary":"quadriceps","secondary":["hamstrings","glutes"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/04131201-Dumbbell-Squat_Hips_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/04131201-Dumbbell-Squat_Hips_.mp4","howto":["Grab a pair of dumbbells and stand tall with your arms straight and to your sides.","Bring your shoulders back, engage your abs, and have your feet in a comfortable stance.","Take a breath and descend by bending your knees.","Move down until your thighs are parallel to the floor, and keep your heels in contact with the ground.","Press through your heels to move up and exhale near the top."]},{"id":"CC35A01F","name":"Squat (Machine)","primary":"quadriceps","secondary":["hamstrings","glutes"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/55201201-Lever-Vertical-Squat_Thighs_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/55201201-Lever-Vertical-Squat_Thighs_.mp4","howto":["Position your back and shoulders against the pad.","Have your feet hip-width apart with your toes pointing slightly out.","Bring your shoulders back, engage your abs, and take a breath.","Pull the safety lever away to unrack the weight.","Bend your knees to descend into a squat and keep your heels in contact with the floor.","Squat until your thighs are parallel to the floor.","Press through your heels to bring yourself to the top and exhale.","Once finished, bring the safety lever back and rack the weight."]},{"id":"DDCC3821","name":"Squat (Smith Machine)","primary":"quadriceps","secondary":["hamstrings","glutes"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/07501201-Smith-Chair-Squat_Thighs_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/07501201-Smith-Chair-Squat_Thighs.mp4","howto":["Position the Smith machine bar at just below collarbone height.","Grab the bar with an overhand grip, tuck your head underneath, and position your upper back against the bar.","Walk your feet out a bit and have them hip-width apart.","Extend your knees to unrack the bar.","Engage your abs, breathe in, and squat by bending your knees.","Descend until your thighs are parallel to the floor.","Press through your heels to move back to the top and exhale.","Once finished, rack the bar and relax your body."]},{"id":"B82D6418","name":"Squat (Suspension)","primary":"quadriceps","secondary":["glutes","hamstrings"],"equipment":"suspension","type":"reps_only","thumb":"assets/thumbs/108041201-Suspender-Squat-(male)_Thighs_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/108041201-Suspender-Squat-(male)_Thighs_.mp4","howto":["Grab the handles of a suspension kit and bend your arms at a 90-degree angle.","Bring your shoulders back, engage your abs, and have your feet in a comfortable squatting stance.","Inhale and squat while keeping your heels in contact with the floor.","Continue until your thighs become parallel to the floor, and pause for a moment.","Press through your heels and bring yourself to the top as you exhale."]},{"id":"A8814C06","name":"Squat Row","primary":"full_body","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/17171201-Cable-Squat-Row-(with-rope-attachment)_Back_Thighs_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/17171201-Cable-Squat-Row-(with-rope-attachment)_Back_Thighs.mp4","howto":["Select the appropriate load on a cable machine.","Set the pulley at hip height and attach a rope or handle.","Grab the cable attachment, take a step back to lift the weight off its stack, and bring your shoulders back.","With your arms straight, descend into a squat.","Go down until your thighs are parallel to the floor.","Press through your heels to move up and immediately row the weight to your stomach as you breathe out."]},{"id":"4377A52B","name":"Stair Machine (Floors)","primary":"cardio","secondary":[],"equipment":"machine","type":"floors_duration","thumb":"assets/thumbs/23111201-Walking-on-Stepmill_Cardio_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/23111201-Walking-on-Stepmill_Cardio.mp4","howto":["Climb on top of the machine and turn it on.","Select a low speed and grab the handrails for support.","Climb the moving stairs while keeping your shoulders back and abs engaged.","Maintain a steady breath.","Increase the speed to a sustainable pace once you’re familiar with the machine."]},{"id":"4377A52C","name":"Stair Machine (Steps)","primary":"cardio","secondary":[],"equipment":"machine","type":"steps_duration","thumb":"assets/thumbs/23111201-Walking-on-Stepmill_Cardio_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/23111201-Walking-on-Stepmill_Cardio.mp4","howto":["Climb on top of the machine and turn it on.","Select a low speed and grab the handrails for support.","Climb the moving stairs while keeping your shoulders back and abs engaged.","Maintain a steady breath.","Increase the speed to a sustainable pace once you’re familiar with the machine."]},{"id":"ACB2751D","name":"Standing Cable Glute Kickbacks","primary":"glutes","secondary":["hamstrings"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/60401201-Cable-Donkey-Kickback-(male)_Hips_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/60401201-Cable-Donkey-Kickback-(male)_Hips_.mp4","howto":["Set the pulley to the lowest position and select the appropriate weight.","Attach an ankle strap to the pulley.","Face the cable machine and wrap the strap around your right ankle, just above the foot.","Bend forward, grab the cable machine’s pillars for balance, and engage your abs.","Take a breath and bring your right leg back in one fluid motion, squeezing your glute at the top and exhaling.","Slowly bring the leg to the starting position and breathe in.","Once finished, wrap the strap over your other ankle, lean forward, and do the same number of reps."]},{"id":"06745E58","name":"Standing Calf Raise","primary":"calves","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/13731201-Bodyweight-Standing-Calf-Raise_Calves_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/13731201-Bodyweight-Standing-Calf-Raise_Calves.mp4","howto":["Stand tall with your feet together, knees extended, shoulders back, and arms to your sides.","Take a breath.","Press through the balls of your feet to extend your ankles, raising yourself a couple of inches. Exhale.","Lower yourself to the starting position as you breathe in."]},{"id":"E53CCBE5","name":"Standing Calf Raise (Barbell)","primary":"calves","secondary":[],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/01081101-Barbell-Standing-Leg-Calf-Raise_Calf_small_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/01081201-Barbell-Standing-Leg-Calf-Raise_Calves.mp4","howto":["Position a barbell on your upper back muscles behind your neck and hold it with both hands.","Place the balls of your feet on an elevated platform and have your heels on the floor.","Bring your shoulders back and engage your abs.","Take a breath and extend your ankles, lifting your heels and squeezing your calves as you exhale.","Lower your heels without resting them on the floor as you breathe in."]},{"id":"6DA40660","name":"Standing Calf Raise (Dumbbell)","primary":"calves","secondary":[],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/04171201-Dumbbell-Standing-Calf-Raise_Calves_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/04171201-Dumbbell-Standing-Calf-Raise_Calves.mp4","howto":["Hold a dumbbell in one hand.","Place the balls of your feet on an elevated platform.","Use your free hand to grab onto something for balance.","Extend your knees, squeeze your glutes, engage your abs, and retract your shoulders.","Take a breath and flex your ankles, bringing your heels to the floor.","Go down as much as possible, feeling your calves stretch.","Hold for a moment and extend your ankles to raise yourself, squeezing your calves at the top as you exhale."]},{"id":"E05C2C38","name":"Standing Calf Raise (Machine)","primary":"calves","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/06051201-Lever-Standing-Calf-Raise_Calves_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/06051201-Lever-Standing-Calf-Raise_Calves.mp4","howto":["Select the appropriate load.","Put your shoulders and upper back against the machine’s pad.","Position the balls of your feet on the platform and extend your knees.","Grab the handles by the machine’s pad for extra support.","Take a breath and extend your ankles, squeezing your calves at the top, and exhale.","Lower yourself slowly, feeling your calves stretch at the bottom. Breathe in on the way down."]},{"id":"AA52E8D2","name":"Standing Calf Raise (Smith)","primary":"calves","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/11641101-Smith-Calf-Raise-(version-2)_Calves_small_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/11641201-Smith-Calf-Raise-(version-2)_Calves.mp4","howto":["Set the bar at the appropriate height, where you can unrack it as you fully extend your knees.","Add the appropriate weight and position a calf raise block under the bar.","Position your trapezius against the bar, grab it with both hands, and place the balls of your feet on the platform.","Engage your entire body and straighten your knees to unrack the bar.","Inhale and slowly lower yourself by allowing your ankles to flex. Keep your knees extended.","Pause briefly at the bottom and push through the balls of your feet to extend your ankles. Squeeze your calves and pause briefly as you exhale."]},{"id":"6120CAAB","name":"Standing Leg Curls","primary":"hamstrings","secondary":["calves"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/51811201-Lever-Standing-Single-Leg-Curl-(plate-loaded)_Thig_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/51811201-Lever-Standing-Single-Leg-Curl-(plate-loaded)_Thig.mp4","howto":["Select the appropriate weight on the machine.","Stand tall, grab the handles for support, and position your right Achilles heel against the machine’s pad.","Bring your shoulders back, engage your abs, and take a breath.","Slowly bend your leg until your ankle is slightly higher than your knee.","Squeeze your hamstring muscle at the top and exhale.","Slowly extend your leg as you breathe in.","Once finished training one side, position your opposite Achilles heel against the pad and do the same number of reps."]},{"id":"073032BB","name":"Standing Military Press (Barbell)","primary":"shoulders","secondary":["triceps"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/11651201-Barbell-Standing-Military-Press-(without-rack)_Shoulders_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/11651201-Barbell-Standing-Military-Press-(without-rack)_Shoulders.mp4","howto":["Position the barbell at collarbone height on a rack or stand.","Stand a few inches from the bar and grab it with an overhand grip. Have your hands shoulder-width apart.","With your hands gripping the bar, tuck yourself underneath and retract your shoulders.","Take a breath, engage your glutes, and push through your legs to unrack the bar.","With your elbows tucked in, back straight, and gaze forward, take a couple of steps back and have your feet at hip-width distance.","Take a deep breath, engage your abs, and push through your elbows in a vertical line.","Push until your elbows lock out and exhale.","Slowly lower the bar to neck level as you breathe in."]},{"id":"28927A36","name":"Standing Y Raise (Cable)","primary":"shoulders","secondary":["upper_back"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/88991201-Cable-Standing-Y-raise-(VERSION-2)-(male)_Shoulder_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/88991201-Cable-Standing-Y-raise-(VERSION-2)-(male)_Shoulder.mp4","howto":["Set the pulleys to hip height, attach handles, and select the same weight on both stacks.","Facing the machine, grab the handle to your left with your right hand, and the handle to your right with your left.","Take a step or two back to lift the weights off of their stacks.","Stand tall with your arms extended in front of your chest and hands crossed.","Bring your shoulders back, breathe in, and engage your abs.","Pull both handles upward and out, exhaling at the top.","Slowly lower the handles to the starting position in front of your chest as you breathe in.","Repeat."]},{"id":"128A2381","name":"Step Up","primary":"quadriceps","secondary":["hamstrings","glutes"],"equipment":"other","type":"reps_only","thumb":"assets/thumbs/94901201-Step-Up-on-Box_Thighs_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/94901201-Step-Up-on-Box_Thighs_.mp4","howto":["Stand in front of a flat gym bench or plyometric box. Have your feet hip-width apart with your toes pointing slightly out.","Bring your shoulders back and engage your abs.","Take a breath, lift your right leg, and plant the foot on the elevated platform.","Push through the heel to extend your body and bring yourself on top of the elevated object. Exhale.","Step off the platform, take another breath and extend your opposite leg."]},{"id":"EE2938D1","name":"Sternum Pull up (Gironda)","primary":"lats","secondary":["upper_back","biceps","forearms"],"equipment":"machine","type":"reps_only","thumb":"assets/thumbs/04661201-Sternum-Pull-up-(Gironda)_Back_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/04661201-Sternum-Pull-up-(Gironda)_Back_.mp4","howto":["Reach up and grab the pull-up bar with an even overhand grip (palms facing forward). Have your hands shoulder-width apart or slightly wider.","Bring your shoulders back, engage your abs, and squeeze your glutes.","Bring your shoulder blades as far back as your strength and mobility allow. Keep your midsection engaged and lean your torso back.","Take a breath and pull yourself up until your lower chest touches the bar, then exhale.","Lower yourself with control and breathe in as you descend."]},{"id":"D2387AB1","name":"Straight Arm Lat Pulldown (Cable)","primary":"lats","secondary":["triceps"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/02381201-Cable-Straight-Arm-Pulldown_Back_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/02381201-Cable-Straight-Arm-Pulldown_Back.mp4","howto":["Select the appropriate load.","Set the pulley to the highest position and attach a straight bar.","Grab the bar with an overhand grip (palms facing down).","Step back to raise the weight from its stack.","Engage your abs, retract your shoulder blades, and squeeze your glutes. You can stagger your stance (bring one foot forward and the other back) for balance.","Take a breath and bring the bar to your hips in one fluid motion. Keep your arms straight and exhale.","Slowly let the bar travel forward and up as you breathe in."]},{"id":"2A48E443","name":"Straight Leg Deadlift","primary":"hamstrings","secondary":["glutes","lower_back","upper_back","lats","traps"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/01161201-Barbell-Straight-Leg-Deadlift_Thighs_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/01161201-Barbell-Straight-Leg-Deadlift_Thighs.mp4","howto":["Stand in front of a loaded barbell.","Position your feet underneath and have your shins a couple of inches from the bar.","Lean forward by hinging at the hips.","Grab the bar with a double overhand grip (palms facing back).","Bring your shoulders back and engage your abs. Keep your legs straight.","Take a breath and pull the bar in a straight vertical line while pushing through your heels.","Squeeze your glutes at the top and exhale.","Slowly lower the bar in the same straight line and breathe in on the way down or before initiating the next rep."]},{"id":"527DA061","name":"Stretching","primary":"other","secondary":[],"equipment":"none","type":"duration","thumb":"assets/thumbs/73811201-Seated-Single-Leg-Hamstring-Stretch-(male)_Thighs_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/73811201-Seated-Single-Leg-Hamstring-Stretch-(male)_Thighs_.mp4","howto":[]},{"id":"7593855D","name":"Suitcase Carry (Dumbbell)","primary":"full_body","secondary":[],"equipment":"dumbbell","type":"short_distance_weight","thumb":"assets/thumbs/29101201-Dumbbell-Suitcase-Carry_Thighs_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/29101201-Dumbbell-Suitcase-Carry_Thighs_.mp4","howto":["Grab a single dumbbell and stand tall.","Bring your shoulders back and engage your abs.","Walk forward steadily, looking several steps in front of you. Breathe steadily.","Once you complete the distance, grab the weight with your other hand, and repeat."]},{"id":"D20D7BBE","name":"Sumo Deadlift","primary":"glutes","secondary":["hamstrings","quadriceps","adductors","lower_back","upper_back","lats","traps"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/01171201-Barbell-Sumo-Deadlift_Hips_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/01171201-Barbell-Sumo-Deadlift_Hips.mp4","howto":["Stand before a loaded barbell with your feet spread wide and your toes pointing out. Your shins should be close to the bar but not in contact.","Bend forward and grab the barbell with a double overhand grip (palms facing back). Your hands should be shoulder-width apart, with your elbows a few inches from your inner thighs.","Bring your shoulders back and lift your chest. Doing so will straighten your back, position your hips at the correct height, and bring your shins against the barbell.","With your body tense and arms straight, breathe into your belly.","Pull the barbell forcefully as you dig your heels into the floor.","Extend your knees and hips as the barbell travels in a straight vertical line and close to your body.","Squeeze your glutes at the top to complete the repetition and exhale, but don’t hyperextend your back.","Lower the barbell in the same vertical line. Breathe in on the way down or before initiating the next rep."]},{"id":"3F5F8D40","name":"Sumo Squat","primary":"quadriceps","secondary":["glutes","adductors","hamstrings"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/10641201-Sumo-Squat-(male)_Thighs-FIX__thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/10641201-Sumo-Squat-(male)_Thighs-FIX_.mp4","howto":["Stand tall and assume a wider-than-shoulder-level stance with your toes pointing out.","Retract your shoulder blades and raise your arms in front of your body for balance.","Take a deep breath, engage your abs, and squat.","Move down until your thighs are parallel to the floor, and press through your heels to return to the top as you exhale."]},{"id":"6622E5A0","name":"Sumo Squat (Barbell)","primary":"quadriceps","secondary":["hamstrings","glutes","adductors"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/10631201-Barbell-sumo-squat_Thighs_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/10631201-Barbell-sumo-squat_Thighs.mp4","howto":["Set the barbell at collarbone height.","Place your hands evenly over the bar, slightly wider than shoulder level apart.","Tuck your head under the bar, placing it on your upper back.","Plant your feet on the floor, take a breath, and unrack the bar.","Take a couple of steps back.","Widen your stance as much as possible with your toes pointing out.","Bring your chest out and take a breath.","Squat slowly, keeping your heels in contact with the floor.","Descend until your thighs are parallel to the floor, hold for a moment, and press through your heels, exhaling near the top."]},{"id":"05293BCA","name":"Sumo Squat (Dumbbell)","primary":"quadriceps","secondary":["glutes","adductors","hamstrings"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/51211201-Dumbbell-Sumo-Squat-(male)_Thighs_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/51211201-Dumbbell-Sumo-Squat-(male)_Thighs_.mp4","howto":["Place a dumbbell in a vertical position on the floor and stand before it.","Squat down and grab the top weight plate with both hands.","Stand tall and assume a comfortable squatting stance. A wide (sumo) stand would give you more room to squat comfortably.","Take a deep breath and engage your abs.","Slowly descend into a squat until your thighs are parallel to the floor.","Push through your heels to move back to the top as you exhale."]},{"id":"5E10D0E6","name":"Sumo Squat (Kettlebell)","primary":"quadriceps","secondary":["glutes","adductors","hamstrings"],"equipment":"kettlebell","type":"weight_reps","thumb":"assets/thumbs/50731201-Kettlebell-Sumo-Squat-(VERSION-2)_Hips_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/50731201-Kettlebell-Sumo-Squat-(VERSION-2)_Hips_.mp4","howto":["Grab a kettlebell by the handle and stand tall with your arms straight and the weight in front of your body.","Assume a wider-than-shoulder-level stance, with your toes pointing out.","Retract your shoulder blades, take a deep breath, and engage your abs.","Descend until your thighs are parallel to the floor, and pause for a moment.","Press through your heels to move back to the top and exhale."]},{"id":"218DA87C","name":"Superman","primary":"lower_back","secondary":["glutes","hamstrings"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/68861201-Superman-Hold-(male)_Hips_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/68861201-Superman-Hold-(male)_Hips_.mp4","howto":["Lie face down on the floor with your legs straight and arms extended to the sides of your head.","Have your toes, knees, thighs, stomach, and chest in contact with the floor.","Take a breath and extend your arms and legs toward the ceiling as high as possible. Breathe out.","Hold the arched position for a couple of seconds, and relax your body as you breathe in."]},{"id":"B60A678F","name":"Swimming","primary":"cardio","secondary":[],"equipment":"none","type":"distance_duration","thumb":"assets/thumbs/69441201-Swimming-Crawl-Style-(male)_Plyometrics_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/69441201-Swimming-Crawl-Style-(male)_Plyometrics_.mp4","howto":[]},{"id":"08A2974E","name":"T Bar Row","primary":"upper_back","secondary":["lats","biceps","forearms"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/06061201-Lever-T-bar-Row-(plate-loaded)_Back_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/06061201-Lever-T-bar-Row-(plate-loaded)_Back.mp4","howto":["Add some weight to the T-bar station.","Step on the platform, lean forward and grab the handles with an overhand grip.","Retract your shoulder blades, engage your abs, and inhale.","With your back neutral, push through your heels and extend your hips a bit to lift the weight off the floor.","Keep your torso almost parallel with the floor and have your arms straight.","Inhale again and pull the weight until the handles get close to your torso. Breathe out at the top.","Extend your arms as you breathe in. Don’t set the weight on the floor."]},{"id":"90E506D5","name":"Thruster (Barbell)","primary":"full_body","secondary":[],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/33051201-Barbell-Thruster_Weightlifting_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/33051201-Barbell-Thruster_Weightlifting_.mp4","howto":["Have the barbell in a front rack position: resting on your shoulders with your elbows bent and fingertips supporting.","Position your feet in a comfortable squatting stance.","Engage your abs and take a breath.","Descend into a squat and keep your heels in contact with the floor.","Move down until your thighs are parallel to the floor.","Press through your heels to move up.","As your legs straighten, immediately transition into an overhead press, thrusting the barbell overhead and breathing out.","Lower the barbell to the front rack position as you breathe in.","Descend into another squat."]},{"id":"10313AFD","name":"Thruster (Kettlebell)","primary":"full_body","secondary":[],"equipment":"kettlebell","type":"weight_reps","thumb":"assets/thumbs/05501101-Kettlebell-Thruster_Shoulders_small_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/05501201-Kettlebell-Thruster_Shoulders-FIX_.mp4","howto":["Grab a pair of kettlebells, stand tall, and lift them to shoulder level. Keep your elbow bent and the kettlebells on the outer side, resting against your forearms and biceps (rack position).","Have your feet at a hip-width distance with your toes pointing slightly out.","Bring your shoulders back, engage your abs, take a breath, and squat.","Descend until your thighs are parallel to the floor and move up, pushing through your heels.","As you reach the top of the squat, press the kettlebells overhead, extending your elbows fully and exhaling.","Lower the kettlebells to the sides of your shoulder, take another breath, and squat."]},{"id":"75BAC5C3","name":"Toe Touch","primary":"abdominals","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/52751201-Lying-Toe-Touch_Waist_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/52751201-Lying-Toe-Touch_Waist_.mp4","howto":["Lie on the floor, straighten your legs, and raise them toward the ceiling.","Engage your abs and raise your arms over your chest with your fingers pointing up.","Take a breath and crunch your abs to lift your shoulder blades several inches off the floor.","Touch your toes with your fingers (or crunch as high as possible in one fluid motion) and exhale.","Lower your upper back to the floor as you breathe in."]},{"id":"B94E35E1","name":"Toes to Bar","primary":"abdominals","secondary":["forearms"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/04741201-Hanging-Straight-Leg-Hip-Raise_Waist_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/04741201-Hanging-Straight-Leg-Hip-Raise_Waist.mp4","howto":["Reach up and grab a pull-up bar with an overhand grip (palms facing forward).","Bring your feet together and lift them off the floor to suspend yourself in the air.","Retract your shoulder blades and engage your abs.","Take a breath and lift your legs in one fluid motion.","Go up as high as possible––ideally, until your toes are close to the pull-up bar you’re holding. Breathe out at the top.","Slowly lower your legs to the starting position as you breathe in. Do repetitions slowly and keep your abs engaged to prevent your body from swinging back and forth."]},{"id":"FBB62888","name":"Torso Rotation","primary":"abdominals","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/100651201-Lever-Torso-Rotation-(male)_Waist_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/100651201-Lever-Torso-Rotation-(male)_Waist_.mp4","howto":["Select the appropriate weight.","Adjust the seat height so that you can comfortably place your forearms on the pads at your sides and grab the handles.","With your knees bent, position your shins against the bottom pads and push forward to create whole-body rigidity.","Breathe in and twist your lower body to the right as you exhale. It should be a fluid motion.","Slowly return your lower body to the starting position as you breathe in.","Rotate your legs to the left and breathe out again.","Continue alternating from left to right, breathing steadily as you do reps."]},{"id":"243710DE","name":"Treadmill","primary":"cardio","secondary":[],"equipment":"machine","type":"distance_duration","thumb":"assets/thumbs/06841201-Run-(equipment)_Cardio_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/06841201-Run-(equipment)_Cardio.mp4","howto":["Stand on the treadmill and clip the safety key to your tank top or T-shirt.","Start the treadmill and gradually increase the speed from slow walking to a jog.","Maintain an upright posture, direct your gaze forward, and maintain a steady breath.","Keep your arms bent and move them in sync with your strides."]},{"id":"28BB4A95","name":"Triceps Dip","primary":"triceps","secondary":["chest","shoulders"],"equipment":"machine","type":"reps_only","thumb":"assets/thumbs/08141201-Triceps-Dip_Upper-Arms_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/08141201-Triceps-Dip_Upper-Arms.mp4","howto":["Grab a pair of parallel bars and suspend yourself in the air.","Maintain an upright body, bring your shoulders back, and engage your abs.","Take a breath and lower yourself by bending your elbows.","Move down until your elbows are at a 90-degree angle.","Hold the position for a moment and press yourself back to the top as you exhale."]},{"id":"4B4BF8C2","name":"Triceps Dip (Assisted)","primary":"triceps","secondary":["chest","shoulders"],"equipment":"machine","type":"bodyweight_assisted_reps","thumb":"assets/thumbs/00191201-Assisted-Triceps-Dip-(kneeling)_Upper-Arms_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00191201-Assisted-Triceps-Dip-(kneeling)_Upper-Arms.mp4","howto":["Select the appropriate load on the machine.","Grab the parallel bars, place your knees on the platform, and bring your legs together.","Retract your shoulder blades, straighten your arms, and engage your abs.","Take a breath and lower yourself by bending your arms.","Descend until your elbows are at a 90-degree angle, hold for a moment, and press back to the top as you breathe out."]},{"id":"10347BAC","name":"Triceps Dip (Weighted)","primary":"triceps","secondary":["chest","shoulders"],"equipment":"machine","type":"bodyweight_reps","thumb":"assets/thumbs/17551201-Weighted-Tricep-Dips_Upper-Arms_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/17551201-Weighted-Tricep-Dips_Upper-Arms_.mp4","howto":["Attach a weight plate to yourself via a special belt.","Grab a pair of parallel bars and suspend yourself in the air.","Maintain an upright body, bring your shoulders back, and engage your abs.","Take a breath and lower yourself by bending your elbows.","Move down until your elbows are at a 90-degree angle.","Hold the position for a moment and press yourself back to the top as you exhale."]},{"id":"2F8D3067","name":"Triceps Extension (Barbell)","primary":"triceps","secondary":[],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/00921201-Barbell-Seated-Overhead-Triceps-Extension_Upper-Arms_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/00921201-Barbell-Seated-Overhead-Triceps-Extension_Upper-Arms.mp4","howto":["Load a barbell.","Grab the bar with an even overhand grip (palms facing back).","Bring your shoulders back and engage your abs.","Lift the bar to chest level.","Sit down on a flat gym bench.","Raise the barbell overhead and extend your arms.","Take a breath and lower the bar behind your head, feeling your triceps stretch.","Hold the bottom for a moment and extend your arms as you exhale."]},{"id":"21310F5F","name":"Triceps Extension (Cable)","primary":"triceps","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/01491201-Cable-Alternate-Triceps-Extension_Upper-Arms_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/01491201-Cable-Alternate-Triceps-Extension_Upper-Arms_.mp4","howto":["Set a cable pulley in a low position and attach a handle.","Select a light load with a pin.","Reach down and grab the handle with one hand.","Turn your body away from the cable machine and extend your arm toward the ceiling.","Place your opposite hand on your elbow for support, retract your shoulder blades, and engage your abs.","Take a breath and slowly bend your elbow until you feel a stretch in your tricep.","Flex your tricep to extend your arm and exhale near the top.","Once finished training one tricep, grab the handle with your opposite hand and do the same number of reps."]},{"id":"3765684D","name":"Triceps Extension (Dumbbell)","primary":"triceps","secondary":[],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/04301201-Dumbbell-Standing-Triceps-Extension_Upper-Arms_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/04301201-Dumbbell-Standing-Triceps-Extension_Upper-Arms.mp4","howto":["Grab a dumbbell and stand tall.","Lift the weight overhead and place your hands flat against the top weight plate with your palms facing the ceiling.","Bring your shoulders back and engage your abs.","Take a breath and lower the dumbbell behind your head while keeping your elbows to the sides of your head.","Bend your arms until you feel a stretch, and extend your elbows as you breathe out."]},{"id":"3092FADD","name":"Triceps Extension (Machine)","primary":"triceps","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/10331201-Lever-Triceps-Extension_Upper-Arms_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/10331201-Lever-Triceps-Extension_Upper-Arms.mp4","howto":["Set the appropriate load and sit down.","Grab the handles to your sides, bring your shoulders back into the pad, and plant your feet on the floor.","Take a breath and push the handles down by extending your elbows.","Straighten your arms fully and hold the position momentarily as you exhale.","Bend your arms slowly and breathe in."]},{"id":"6182EE83","name":"Triceps Extension (Suspension)","primary":"triceps","secondary":[],"equipment":"suspension","type":"reps_only","thumb":"assets/thumbs/58761201-Suspension-Triceps-Extension-(male)_Upper-Arms_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/58761201-Suspension-Triceps-Extension-(male)_Upper-Arms_.mp4","howto":["Grab the handles of the suspension kit and turn away from the anchor point.","Extend your arms in front of your body, bring your feet together, and flex your abs.","Retract your shoulders and take a breath.","Lean your body forward by bending your elbows.","Descend until you feel a stretch in your triceps.","Flex your arm muscles to extend your body and exhale."]},{"id":"EC3B69A3","name":"Triceps Kickback (Cable)","primary":"triceps","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/45661101-Cable-Neutral-Grip-Kickback_Upper-arms_small_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/45661201-Cable-Neutral-Grip-Kickback_Upper-arms_.mp4","howto":["Set the cable pulley in a low position and select the appropriate load. Don’t add an attachment.","Grab the plastic piece at the rope’s end with your right hand and take a step back.","Lean your torso forward and keep your back straight.","Raise your elbow to the side of your torso and inhale.","Extend your arm fully and pause briefly as you exhale.","Slowly bend your arm as you breathe in.","Repeat.","Once finished, grab the rope with your left hand and repeat for the same number of reps."]},{"id":"6127A3AD","name":"Triceps Kickback (Dumbbell)","primary":"triceps","secondary":[],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/03331201-Dumbbell-Kickback_Upper-Arms_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/03331201-Dumbbell-Kickback_Upper-Arms.mp4","howto":["Grab a light dumbbell and hold it to your side with your palm facing your thigh.","Lean your torso forward as you push your butt back to maintain a neutral back.","Lift your elbow to your side, inhale, and extend your arm by engaging your tricep. Breathe out.","Hold the contraction for a second and slowly bring the dumbbell back down as you breathe in.","Keep your shoulder and elbow in a stationary position throughout each repetition."]},{"id":"CDC472B1","name":"Triceps Pressdown","primary":"triceps","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/16051201-Cable-Triceps-Pushdown-(SZ-bar)_Upper-arms_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/16051201-Cable-Triceps-Pushdown-(SZ-bar)_Upper-arms.mp4","howto":["Set the appropriate weight on a cable machine.","Put the pulley in the highest position and attach a straight or V-shaped bar.","Grab the bar with an even overhand grip (palms facing down).","Bring your elbows to your sides, take a step back, and retract your shoulder blades.","Engage your abs and take a breath.","Extend your arms fully and hold the bottom position for a moment as you breathe out.","Slowly bend your arms until your wrists are slightly higher than your elbows, breathing in along the way."]},{"id":"93A552C6","name":"Triceps Pushdown","primary":"triceps","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/02011201-Cable-Pushdown_Upper-Arms_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/02011201-Cable-Pushdown_Upper-Arms.mp4","howto":["Pick the appropriate load, set the pulley in the highest position, and attach a bar.","Grab the bar with an even overhand grip and bring your elbows to your sides.","Take a couple of steps back and lean your torso slightly forward.","Engage your abs, retract your shoulder blades, and take a breath.","Extend your arms while keeping your elbows to your sides and hold for a moment. Exhale.","Slowly bend your arms until your wrists are slightly higher than your elbows. Breathe in as your arms bend."]},{"id":"94B7239B","name":"Triceps Rope Pushdown","primary":"triceps","secondary":[],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/02001201-Cable-Pushdown-(with-rope-attachment)_Upper-Arms-FIX_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/02001201-Cable-Pushdown-(with-rope-attachment)_Upper-Arms-FIX_.mp4","howto":["Pick the appropriate weight, set the pulley to the highest position, and attach a rope.","Grab the rope with both hands and bring your elbows to your sides.","Take a step back and lean your torso forward slightly.","Take a breath and extend your arms while keeping your elbows in position. Breathe out.","Bend your arms slowly and breathe in. Stop when your wrists end up slightly higher than your elbows."]},{"id":"7AB9A362","name":"Upright Row (Barbell)","primary":"shoulders","secondary":["traps","upper_back","biceps","forearms"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/01211201-Barbell-Upright-Row_Shoulders_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/01211201-Barbell-Upright-Row_Shoulders.mp4","howto":["Grab a barbell with an overhand grip (palms facing back). Your hands should be shoulder-width apart.","Stand tall, retract your shoulder blades, flex your abs, and take a breath.","Row the barbell in a straight line from your hips to your chest and breathe out. Squeeze your upper back and biceps at the top.","Extend your arms slowly and breathe in on the way down."]},{"id":"286C1D0B","name":"Upright Row (Cable)","primary":"shoulders","secondary":["traps","upper_back","biceps","forearms"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/02461201-Cable-Upright-Row_shoulder_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/02461201-Cable-Upright-Row_shoulder.mp4","howto":["Set the pulley to the lowest position and attach a straight bar.","Select the appropriate weight.","Lean forward and grab the bar with an overhand grip (palms facing down).","Stand up and step back to lift the weight off its stack.","Bring your shoulders back, engage your abs, and put one foot slightly forward for support.","Take a breath and row the bar to your upper chest in one fluid motion. Exhale at the top.","Slowly extend your arms as you breathe in."]},{"id":"797F0782","name":"Upright Row (Dumbbell)","primary":"shoulders","secondary":["traps","upper_back","biceps","forearms"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/04371201-Dumbbell-Upright-Row_shoulder_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/04371201-Dumbbell-Upright-Row_shoulder.mp4","howto":["Grab a pair of dumbbells and stand tall. Have your feet in a comfortable stance, shoulders retracted, and arms straight.","Position the dumbbells in front of your body and engage your abs.","Inhale and pull the dumbbells in a straight vertical line toward your upper chest. Exhale at the top.","Extend your arms, breathing in on the way down."]},{"id":"6BE68B62","name":"V Up","primary":"abdominals","secondary":[],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/05071201-Jackknife-Sit-Up_Waist_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/05071201-Jackknife-Sit-Up_Waist_.mp4","howto":["Lie on the floor with your legs straight, feet together, and arms stretched behind your head.","Engage your abs and take a breath.","Simultaneously raise your legs and upper body in one fluid motion, folding your body into a V shape and breathing out.","Hold the top position for a moment and slowly lower your torso and legs as you breathe in. Don’t rest your feet on the floor between repetitions."]},{"id":"72880C57","name":"Vertical Traction (Machine)","primary":"lats","secondary":["upper_back","biceps","forearms"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/71791201-Lever-Cross-Lat-Pulldown-(VERSION-2)-(male)_Back_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/71791201-Lever-Cross-Lat-Pulldown-(VERSION-2)-(male)_Back_.mp4","howto":["Select the appropriate load.","Face away from the machine with your backside close to the back pad with the handles overhead.","Grab the handles with a neutral (palms facing one another) or overhand (palms facing forward) grip and sit down.","Bring your chest out, engage your abs, and breathe in.","Pull the handles down and to your sides with your elbows traveling in a semi-arc toward your lats. Exhale.","Slowly extend your arms and breathe in."]},{"id":"72297E8C","name":"Waiter Curl (Dumbbell)","primary":"biceps","secondary":["forearms"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/52011201-Dumbbell-Waiter-Biceps-Curl_Upper-Arms_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/52011201-Dumbbell-Waiter-Biceps-Curl_Upper-Arms_.mp4","howto":["Hold a dumbbell vertically and place your hands flat against the underside of the top weight plate with your thumbs on top for grip support.","Stand tall, spread your feet slightly wider than your hips, and lean forward slightly.","Bring your chest out, engage your abs, and breathe in.","Curl the dumbbell until your wrists are slightly higher than your elbows and pause for a moment as you exhale.","Slowly lower the weight until your arms are fully extended. Breathe in on the way down.","Repeat."]},{"id":"33EDD7DB","name":"Walking","primary":"cardio","secondary":[],"equipment":"none","type":"distance_duration","thumb":"assets/thumbs/22581201-Walking_Cardio-FIX_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/22581201-Walking_Cardio-FIX_.mp4","howto":[]},{"id":"32HKJ34K","name":"Walking Lunge","primary":"quadriceps","secondary":["glutes","hamstrings"],"equipment":"none","type":"reps_only","thumb":"assets/thumbs/14601201-Walking-Lunge-Male_Hips_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/14601201-Walking-Lunge-Male_Hips.mp4","howto":["Retract your shoulder blades and engage your abs.","Take a breath and extend your right leg forward, planting the foot on the floor.","Immediately sink into a lunge until your back knee is almost in contact with the ground.","Press through your front foot to extend the leg as you exhale.","Breathe in as you lift your back foot off the floor and extend the back leg forward, planting the foot in front of your body and descending into another lunge.","Continue moving forward until you’re done."]},{"id":"A733CC5B","name":"Walking Lunge (Dumbbell)","primary":"quadriceps","secondary":["glutes","hamstrings"],"equipment":"dumbbell","type":"short_distance_weight","thumb":"assets/thumbs/15571201-Dumbbell-Walking-Lunges_Thighs___thumbnail_@3x.png","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/15571201-Dumbbell-Walking-Lunges_Thighs_.mp4","howto":["Grab a pair of dumbbells and stand tall.","Retract your shoulder blades and engage your abs.","Take a breath and extend your right leg forward, planting the foot on the floor.","Immediately sink into a lunge until your back knee is almost in contact with the ground.","Press through your front foot to extend the leg as you exhale.","Breathe in as you lift your back foot off the floor and extend the back leg forward, planting the foot in front of your body and descending into another lunge.","Continue moving forward until you’re done."]},{"id":"F30A4F01","name":"Walking Lunge (Sandbag)","primary":"quadriceps","secondary":["hamstrings","glutes"],"equipment":"other","type":"short_distance_weight","thumb":"assets/thumbs/113141201-Weighted-Sandbag-Walking-Lunge-(male)_Thighs_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/113141201-Weighted-Sandbag-Walking-Lunge-(male)_Thighs_.mp4","howto":["Lean forward and grab the sandbag by the handles.","Lift the bag to chest level, press it overhead, and position it behind your neck.","Stand tall with your feet hip-width apart. Breathe in and engage your abs.","Extend your right leg forward, plant the foot, and sink into a lunge, descending until your back knee is close to or taps the ground.","Push through your front foot to extend the knee and stand up as you breathe out. Immediately bring your left leg forward to align your feet.","Breathe in, bring your left leg forward, plant the foot on the floor, and perform the next lunge.","Continue alternating as you move forward."]},{"id":"A1F47ACC","name":"Wall Ball","primary":"full_body","secondary":[],"equipment":"other","type":"weight_reps","thumb":"assets/thumbs/51611201-Medicine-Ball-Throw-Squat-with-Wall_Shoulders_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/51611201-Medicine-Ball-Throw-Squat-with-Wall_Shoulders_.mp4","howto":["Grab a medium-sized medicine ball and stand in front of a wall.","Lift the ball in front of your chest and keep your elbows bent.","Have your feet in a comfortable stance for squats, with your toes pointing slightly out.","Engage your abs and take a breath.","Descend into a squat, keeping your heels in contact with the floor.","Move down until your thighs are parallel to the floor, and press through your heels to move up.","As your legs straighten, throw the ball up and against the wall and exhale.","Immediately grab the ball, take another breath, and descend into another squat."]},{"id":"C8706C80","name":"Wall Sit","primary":"quadriceps","secondary":["abdominals"],"equipment":"other","type":"duration","thumb":"assets/thumbs/07341201-Sit-(wall)_Thighs_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/07341201-Sit-(wall)_Thighs.mp4","howto":["Face away from a wall and stand a few inches away.","Carefully lean back and position your upper back and buttocks against the wall.","Engage your abs and slowly bend your knees to descend into a squat.","Adjust your foot position and have your ankles underneath your knees. Your thighs should be roughly parallel to the floor.","Bring your arms in front of your body or have them to your sides.","Hold the position for 30 to 60 seconds, breathing steadily as you do."]},{"id":"79EF4E4F","name":"Warm Up","primary":"full_body","secondary":[],"equipment":"none","type":"duration","thumb":"assets/thumbs/98311201-Standing-Alternating-Arms-Swing-(male)_Stretching_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/98311201-Standing-Alternating-Arms-Swing-(male)_Stretching_.mp4","howto":[]},{"id":"7C50F118","name":"Wide Pull Up","primary":"lats","secondary":["upper_back","biceps","forearms"],"equipment":"machine","type":"reps_only","thumb":"assets/thumbs/14291201-Wide-Grip-Pull-Up_Back_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/14291201-Wide-Grip-Pull-Up_Back.mp4","howto":["Reach up and grab a pull-up bar with a wide overhand grip (palms facing forward). Your hands should be more than shoulder-width apart but not too wide.","Bring your shoulders back, engage your abs, and lift your feet off the floor to suspend yourself in the air. Keep your feet together or bend your knees and interlock your lower legs.","Take a breath and pull yourself up in one fluid motion. Go up until your chin is over the bar and hold for a moment as you exhale.","Slowly lower yourself and breathe in."]},{"id":"B31EB524","name":"Wide-Elbow Triceps Press (Dumbbell)","primary":"triceps","secondary":["chest","shoulders"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/04361201-Dumbbell-Tate-Press_Triceps_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/04361201-Dumbbell-Tate-Press_Triceps.mp4","howto":["Grab a pair of dumbbells and sit on a flat gym bench.","Place the weights on top of your thighs and hold them steady.","Lie back with your elbows bent and the weights close to your body.","Press the dumbbells to extend your arms. Your palms should face forward (toward your lower body).","Plant your feet on the floor, bring your shoulders back, engage your abs, and breathe in.","Slowly bend your elbows to bring the dumbbells inward and toward your chest. This will force your elbows to flare out to some degree.","Carefully lower the weights on your chest and extend your arms as you exhale."]},{"id":"0E4523F4","name":"Wrist Roller","primary":"forearms","secondary":["shoulders"],"equipment":"machine","type":"weight_reps","thumb":"assets/thumbs/08591101-Wrist-Roller_Forearms_small_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/08591201-Wrist-Roller_Forearms_.mp4","howto":["Grab a wrist roller and attach a weight plate to it.","Stand tall and lift your arms in front of your body with your palms facing down.","Bring your shoulders back and engage your abs.","Inhale and begin rolling the plate up.","Once the plate reaches your hands, roll in the opposite direction to lower the weight to the floor.","Breathe steadily and roll for as long as possible."]},{"id":"8C9D2928","name":"Yoga","primary":"full_body","secondary":[],"equipment":"none","type":"duration","thumb":"assets/thumbs/48671201-Butterfly-Yoga-Flaps_Hips_thumbnail_@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/48671201-Butterfly-Yoga-Flaps_Hips_.mp4","howto":[]},{"id":"40C6A9FC","name":"Zercher Squat","primary":"quadriceps","secondary":["hamstrings","glutes","biceps"],"equipment":"barbell","type":"weight_reps","thumb":"assets/thumbs/15451101-Barbell-full-Zercher-Squat_Thighs_small_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/15451201-Barbell-full-Zercher-Squat_Thighs.mp4","howto":["Position the barbell at roughly belly button height.","Walk up to the bar and press the crease of your elbows against it.","Bend your arms to create a shelf and press the barbell against your stomach.","Take a couple of steps back, bring your chest out, and take a deep breath into your belly.","Squat by imagining that you’re sitting down in an invisible chair. Keep your heels on the floor and maintain an upright torso.","Go down as comfortably as you can and push through your heels to move to the top position. Exhale."]},{"id":"123EE239","name":"Zottman Curl (Dumbbell)","primary":"biceps","secondary":["forearms"],"equipment":"dumbbell","type":"weight_reps","thumb":"assets/thumbs/04391201-Dumbbell-Zottman-Curl_Upper-Arms-FIX_thumbnail@3x.jpg","video":"https://d2l9nsnmtah87f.cloudfront.net/exercise-assets/04391201-Dumbbell-Zottman-Curl_Upper-Arms-FIX.mp4","howto":["Grab a pair of dumbbells, stand tall, and position your arms to your sides.","Have the weights in front of your upper thighs with your palms facing forward.","Engage your abs and take a breath.","Curl the dumbbells up until your wrists are slightly higher than your elbows, and breathe out.","As you reach the top position, rotate your wrists 180 degrees and lower the dumbbells to the starting position with your palms facing down. Breathe in on the way down.","Rotate your wrists again and repeat."]}];
